window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0126", [{"word":"antiquarian","ipa_uk":"/ˌæntɪˈkweəriən/","ipa_us":"/ˌæntɪˈkweriən/","definition_zh":"古物研究者；古物与旧书收藏者；旧书珍本商；古董的；旧式的","definition_en":"a person who studies or collects objects and books from the past, or something relating to such old material","core_image":"一张书桌，桌上摊着拓片、碎印章与旧书，每件旧物都挂着写有年份的小纸牌，旁边放着一只放大镜","scene":"冬夜的私人书房里，研究者把一枚碎印章放到灯下，桌上摊满编好号的卡片。The antiquarian spent the winter cataloguing broken seals from a forgotten monastery.","sceneCN":"这里 antiquarian 指「以研究、编目古物为业的人」（第 1 个义项：研究古代器物与文献的学者）；句意为这位古物研究者用整个冬天为一座被遗忘的修道院出土的残破印章编目。场景物件：放大镜、编号卡片、碎印章、旧书。","pos":[{"tag":"n.","zh":"古物研究者；古物收藏者；旧书珍本商"},{"tag":"adj.","zh":"古物的；旧书珍本的；古物研究的；旧式的"}],"collocations":[{"phrase":"antiquarian books","zh":"古旧珍本"},{"phrase":"antiquarian bookshop","zh":"旧书珍本店"},{"phrase":"antiquarian society","zh":"古物学会"},{"phrase":"antiquarian dealer","zh":"古董商"},{"phrase":"antiquarian research","zh":"古物研究"},{"phrase":"antiquarian collection","zh":"古物收藏"}],"forms":[{"label":"复数","form":"antiquarians"},{"label":"旧称（名词）","form":"antiquary"},{"label":"旧称复数","form":"antiquaries"},{"label":"形容词（限定用法）","form":"antiquarian"},{"label":"名词（研究风气）","form":"antiquarianism"}],"derivatives":[{"word":"antiquarianism","pos":"n.","zh":"古物研究；好古之风"},{"word":"antiquary","pos":"n.","zh":"古物研究者（旧称）"},{"word":"antiquity","pos":"n.","zh":"古代；古物"},{"word":"antique","pos":"n./adj.","zh":"古董 / 古董的"},{"word":"antiquated","pos":"adj.","zh":"过时的；陈旧的"}],"senses":[{"no":"01","title":"A scholar of old remains","titleCN":"研究古代遗物的学者","definition":"a person who studies old objects, documents and sites as a subject","definitionCN":"以古代器物、文书与遗址为研究对象的人","example":"The antiquarian read the inscription before the mason touched the stone.","exampleCN":"石匠还没动凿子，这位古物研究者就读出了铭文。","why":"antiquus 'old' plus -arian 'person concerned with' simply names the person whose business is old things.","whyCN":"antiquus「旧的」加 -arian「与…相关的人」，直接标出以旧物为业的人。"},{"no":"02","title":"A private collector of old objects","titleCN":"古物与旧书的私人收藏者","definition":"a person who gathers old books, coins or furniture out of personal passion","definitionCN":"出于个人喜好收集旧书、钱币或旧家具的人","example":"The antiquarian filled three rooms with coins that nobody else could date.","exampleCN":"这位收藏者用三个房间堆满钱币，别人谁也说不出年代。","why":"collecting grew out of studying, because the same person often owned what he examined.","whyCN":"收藏由研究延伸而来：同一个人常常既研究也拥有他所看的东西。"},{"no":"03","title":"A dealer in old and rare books","titleCN":"经营旧书珍本的商人","definition":"a bookseller whose stock is second-hand, rare or otherwise antiquarian material","definitionCN":"以二手书、珍本等古旧书籍为货源的书商","example":"The antiquarian priced the folio higher than a year of wages.","exampleCN":"这位旧书商给那部对开本的定价高过一年的工钱。","why":"the trade sense is a specialisation of the collector's eye: judgement of age becomes a service sold to others.","whyCN":"买卖义是收藏眼光的专业化：判断年代的本事变成为他人提供的服务。"},{"no":"04","title":"Relating to old objects as a field","titleCN":"与古物研究相关的（学会、机构）","definition":"used of societies, journals and meetings devoted to old objects and documents","definitionCN":"用于指致力于古物与古文献的学会、刊物与集会","example":"The antiquarian society met monthly to compare rubbings of old inscriptions.","exampleCN":"古物学会每月聚会，比对古碑的拓片。","why":"the adjective marks the institutional side of the same pursuit, where amateurs organised themselves into clubs.","whyCN":"形容词标出同一追求的制度面：业余爱好者把自己组织成社团。"},{"no":"05","title":"Of books: old, rare and collectible","titleCN":"旧书珍本的","definition":"used of books that are old, scarce and valued by collectors rather than by ordinary readers","definitionCN":"指年代久远、稀少、由收藏者而非普通读者估价的书籍","example":"Antiquarian books are catalogued by edition and binding, not by title alone.","exampleCN":"古旧珍本按版本与装帧编目，不能只看书名。","why":"book catalogues fixed this phrase, so the word now labels a market category as much as a person.","whyCN":"旧书目录固定了这一搭配，于是这个词如今既指人，也标出一个市场门类。"},{"no":"06","title":"Of research: based on old documents","titleCN":"古文献研究的","definition":"used of study that relies on old manuscripts, registers and printed records","definitionCN":"指依赖旧手稿、教区登记簿与旧印本的考据研究","example":"Her antiquarian research began with parish registers and ended with a map of vanished fields.","exampleCN":"她的古文献研究从教区登记簿开始，最后画出一张消失了的田地地图。","why":"the method, not the object, is what the adjective qualifies here: patient reading of paper traces.","whyCN":"这里形容词限定的是方法而非对象：耐心阅读纸上的痕迹。"},{"no":"07","title":"Old-fashioned, stuck in the past","titleCN":"旧式的；固守旧法的","definition":"used of habits or attitudes that cling to old methods and refuse present ones","definitionCN":"指固守旧法、拒绝当下做法的习惯或态度","example":"His antiquarian habits kept the office on paper long after every rival had gone digital.","exampleCN":"他那种旧式习惯让办公室在同行都已数字化之后仍靠纸运转。","why":"the same word turns into a criticism once care for old things stops being a method and becomes a refusal to move.","whyCN":"当对旧物的在意不再是方法而变成拒绝前行，同一个词就转为批评。"},{"no":"08","title":"Imitating antique style","titleCN":"仿古样式的","definition":"used of bindings, typefaces or finishes made to look older than they are","definitionCN":"指装帧、字体或做工刻意做成比实际年代更古旧的样子","example":"The binder chose an antiquarian finish for a book printed last year.","exampleCN":"装订师给一本去年印的书选了仿古做旧的处理。","why":"the last step turns age into a style: the surface of oldness is copied without the object being old.","whyCN":"最后一步把「旧」变成一种风格：只复制旧的表面，物件本身并不旧。"}],"etymology":{"intro":{"en":"Antiquarian comes from Latin antiquarius 'of old things, a student of old things', built on antiquus 'old, former'. Dates are approximate.","cn":"antiquarian 来自拉丁 antiquarius「与古物相关的、研究古物的人」，其基础是 antiquus「旧的、从前的」。年代均为约数。"},"items":[{"era":"LATIN ANTIQUUS","en":"Antiquus meant 'former, old, ancient'. It is generally analysed as ante 'before' plus an adjective suffix, though the shape of that suffix is disputed.","cn":"antiquus 意为「从前的、旧的、古老的」。一般认为它由 ante「在前」加一个形容词后缀构成，但该后缀的具体形式存有争议。"},{"era":"LATIN ANTIQUARIUS","en":"Antiquarius worked both as an adjective 'of old things' and as a noun for a person who read or collected them.","cn":"antiquarius 既作形容词「与古物相关的」，也作名词指阅读或收集古物的人。"},{"era":"ENGLISH ANTIQUARY","en":"English antiquary appeared in the sixteenth century for the student of remains, and antiquarian followed as its adjective.","cn":"英语 antiquary 在 16 世纪出现，指研究古代遗存的人；antiquarian 随后作为它的形容词出现。"},{"era":"NOUN FROM ADJECTIVE","en":"In the seventeenth century antiquarian also became a noun, naming the person and not only the pursuit.","cn":"到 17 世纪，antiquarian 也用作名词，既指这门行当，也指从事它的人。"},{"era":"NARROWING","en":"Professional archaeology took over fieldwork, so antiquarian survived chiefly for dealers, collectors and amateur historians.","cn":"专业考古学接过了野外工作，antiquarian 主要留在旧书商、收藏者与业余史家身上。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest noun use is dated loosely to the early seventeenth century, and the pre-Latin base of antiquus is reconstructed rather than attested.","cn":"来源不确定（首见年代与更深词源）：名词用法最早只能约略定在 17 世纪初；antiquus 在拉丁语之前的词基属重构形式，并无直接书证。"}]},"similar":{"note":{"en":"Group one holds words built on the same antiquus stock or easily mistaken for it; group two holds people and things that deal with the past without sharing the root.","cn":"第一组是同出 antiquus 词干或极易看错的词；第二组是同样与过去打交道、但词根不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"antique","ipa":"/ænˈtiːk/","tag":"the object itself","definition":"From the same antiquus stock through French, but it names a valuable old object, not the person who studies it.","definitionCN":"同出 antiquus、经法语而来，但指有价值的旧物件，而非研究它的人。"},{"word":"antiquity","ipa":"/ænˈtɪkwəti/","tag":"the age or the remains","definition":"The quality of being old, or the ancient world and its remains; it never names a living specialist.","definitionCN":"指「古老」这一性质，或古代世界及其遗存；从不指在世的专门研究者。"},{"word":"antiquated","ipa":"/ˈæntɪkweɪtɪd/","tag":"made obsolete","definition":"An adjective for methods or machines that have been left behind, with no hint of study or collecting.","definitionCN":"形容词，指被时代抛下的方法或机器，不含研究或收藏之意。"},{"word":"antiquary","ipa":"/ˈæntɪkwəri/","tag":"older synonym for the person","definition":"The older noun for the same figure; it survives in titles of learned societies and now sounds formal.","definitionCN":"指同一类人的旧称，仍见于学会名称，如今听来正式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"archaeologist","ipa":"/ˌɑːkiˈɒlədʒɪst/","tag":"digs the site","definition":"A trained specialist who excavates and interprets sites; the antiquarian usually works from objects already found.","definitionCN":"受过训练、以发掘与解释遗址为业的专家；古物研究者通常处理已经出土的物件。"},{"word":"collector","ipa":"/kəˈlektə/","tag":"gathers anything","definition":"A general word for anyone who assembles objects, with no claim to scholarship.","definitionCN":"泛指收集物件的人，不含有学术研究之意。"},{"word":"curator","ipa":"/kjʊˈreɪtə/","tag":"cares for a collection","definition":"The person responsible for a museum or archive holdings; care and display, rather than private study, define the role.","definitionCN":"负责博物馆或档案馆藏品的人；其职责是保管与陈列，而非私人研究。"},{"word":"historian","ipa":"/hɪˈstɔːriən/","tag":"writes the account","definition":"Works with records to explain change over time; antiquarian interest stops at the object and its date.","definitionCN":"依据史料解释时间中的变化；古物之趣止于物件及其年代。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real book-trade phrases and real relatives.","cn":"正常联想：真实的构词成分、真实的旧书行业搭配与真实同族词。"},"normal":[{"en":"antiquus 'old' + -arian 'person concerned with' = a person concerned with old things.","cn":"antiquus「旧的」+ -arian「与…相关的人」= 与旧物打交道的人。"},{"en":"The family runs antiquarian, antiquary, antiquarianism, antique, antiquity and antiquated.","cn":"同族词包括 antiquarian、antiquary、antiquarianism、antique、antiquity、antiquated。"},{"en":"Book-trade phrases keep it alive: antiquarian books, antiquarian bookshop, antiquarian fair.","cn":"旧书行业的搭配让它活着：古旧珍本、珍本旧书店、古书展。"},{"en":"-arian also builds librarian, vegetarian and disciplinarian, all 'person concerned with'.","cn":"-arian 还构成 librarian、vegetarian、disciplinarian，都是「与…相关的人」。"},{"en":"Today the word most often sits directly before books, maps or prints.","cn":"今天这个词最常直接放在书、地图或版画之前。"}],"abstract":[{"en":"Picture a shelf where every object wears a small paper tag bearing a year.","cn":"想象一排架子，每件旧物都挂着写有年份的小纸牌。"},{"en":"Picture a hand lens resting on a page whose edges have gone brown.","cn":"想象一只放大镜搁在纸页上，纸边已经发褐。"},{"en":"Picture a shop bell that sounds older than the customer who rings it.","cn":"想象一只店铃，声音比按铃的顾客还要老。"}]},"examples":[{"en":"The antiquarian could date the coin from the wear on its edge alone.","cn":"这位古物研究者只看钱币边缘的磨损就能定出年代。"},{"en":"An antiquarian bookshop on the corner still sells maps folded by hand.","cn":"街角的珍本旧书店仍在卖手工折叠的地图。"},{"en":"The society's antiquarian journal publishes one careful catalogue each year.","cn":"该学会的古物刊物每年刊出一份严谨的目录。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「安提克」听起来像「安放旧物」的架子，后面再接「人」——整天围着老物件打转的人 → 古物研究者、古物收藏者","word":"antiquarian"},"root":"拉丁 antiquus「旧的、从前的」一般认为由 ante「在前」加形容词后缀构成，后缀形式存疑；经 antiquarius「与古物相关的、古物研究者」进入英语。antiquus 在拉丁语之前的来源不确定。","sensesIntro":{"en":"Eight senses circle one figure, the person whose life is organised around old objects: first the scholar, then the collector, then the dealer, then the adjective uses of that world, and finally the stiffness that comes when care for age stops being a method.","cn":"八个义项围绕同一类人展开：先是学者，再是收藏者，再是商人，然后是这类人所在世界的形容词用法，最后是当「在意旧物」不再是方法而变成僵硬时的那层贬义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a desk where every old object carries a numbered paper tag.","cn":"核心意象：一张书桌，每件旧物都挂着写有编号的纸牌。"},"chain":["OLD THINGS","KEEPER OF OLD THINGS","PRIVATE COLLECTION","BOOK TRADE","SCHOLARLY STUDY","FOSSILISED TASTE"],"branches":[{"senses":"S1 · S2","en":"KEEPER AND HOARDER: one studies the relics, the other simply keeps them, and the same person often does both.","cn":"守护者与囤积者：一个人研究遗物，另一个人只是保存它们，而这两种角色常落在同一人身上。"},{"senses":"S3 · S4","en":"TRADE AND SOCIETY: the shop sells what the learned society studies, so the same old objects pass through both.","cn":"交易与社团：商店卖出学会所研究的东西，同一批旧物在两处流转。"},{"senses":"S5 · S6","en":"BOOKS AND RESEARCH: rare volumes and documented finds are the two working materials of this world.","cn":"书与研究：珍本书与有记录的出土物，是这个世界两种工作材料。"},{"senses":"S7","en":"OUT-OF-DATE: what is merely old can harden into an obstacle to present work.","cn":"过时：仅仅「旧」的东西会硬化成当下工作的障碍。"},{"senses":"S8","en":"FAKE AGE: imitating an antique finish turns age into a purchasable style.","cn":"仿古：模仿古董做工，把「旧」变成可以购买的风格。"}]},"affixes":{"intro":{"en":"Antiquarian is built from a Latin root, a Latin noun-forming suffix and an English noun ending, so the word can be read piece by piece.","cn":"antiquarian 由拉丁词根、拉丁名词构成成分与英语名词词尾搭成，可以逐段读出。"},"latinIntro":{"en":"Latin antiquus gives antique, antiquity and antiquated through French and English, while antiquarius gives the person words antiquary and antiquarian.","cn":"拉丁 antiquus 经法语与英语衍生出 antique、antiquity、antiquated；antiquarius 则衍生出指人的 antiquary 与 antiquarian。"},"items":[{"word":"antiqu-","structure":"antiquus (Latin adjective, 'old, former')","meaning":"old; former","meaningCN":"旧的；从前的","example":"The root supplies the idea of age in every member of the family.","exampleCN":"这个词根为整个词族提供「年代久远」的意思。"},{"word":"-arian","structure":"-arius (Latin suffix, 'concerned with')","meaning":"a person concerned with","meaningCN":"与…相关的人","example":"The suffix also makes librarian and vegetarian.","exampleCN":"这个后缀还构成 librarian 与 vegetarian。"},{"word":"antiquary","structure":"antiquarius + -ary","meaning":"a student of old things","meaningCN":"古物研究者","example":"The antiquary catalogued the parish chest.","exampleCN":"这位古物研究者给教区木柜里的东西编了目。"},{"word":"antiquarianism","structure":"antiquarian + -ism","meaning":"the pursuit or cult of old things","meaningCN":"好古之风；古物研究","example":"His antiquarianism filled the house with labelled stones.","exampleCN":"他的好古癖让整座房子堆满贴了标签的石头。"},{"word":"antique","structure":"antiquus through French","meaning":"an old and valued object","meaningCN":"古董；古物","example":"The antique had lost its label but not its value.","exampleCN":"那件古董丢了标签，价值却还在。"},{"word":"antiquity","structure":"antiquitas, antiquitatis (Latin noun)","meaning":"the ancient past or the quality of age","meaningCN":"古代；古老","example":"The statue was sold as a piece of antiquity.","exampleCN":"这尊雕像被当作古代文物出售。"},{"word":"antiquated","structure":"antiquarian + -ed","meaning":"made obsolete","meaningCN":"过时的","example":"The antiquated filing system survived one more year.","exampleCN":"那套过时的归档办法又多撑了一年。"},{"word":"antiquarian","structure":"antiquarius + -an","meaning":"relating to old things or the person who studies them","meaningCN":"古物的；古物研究者","example":"The antiquarian label appears on maps as well as books.","exampleCN":"古物这个标签不只贴书，也贴地图。"}],"latinEntries":[{"word":"antiquus","structure":"antiquus, antiqua, antiquum (adjective)","meaning":"old, former, ancient","meaningCN":"旧的；从前的；古老的"},{"word":"antiquarius","structure":"antiquarius, antiquaria, antiquarium (adjective and noun)","meaning":"of old things; a student of old things","meaningCN":"古物的；古物研究者"},{"word":"antiquitas","structure":"antiquitas, antiquitatis (f., third declension)","meaning":"antiquity, the olden time","meaningCN":"古代；往昔"}]}},{"word":"medieval","ipa_uk":"/ˌmiːdiˈiːvəl/","ipa_us":"/ˌmediˈiːvəl/","definition_zh":"中世纪的；中世纪风格的；中世纪式的（野蛮、落后）；中世纪的人","definition_en":"belonging to the Middle Ages, or resembling the period in style, and by extension crude or backward","core_image":"一张泛黄的羊皮纸上画着带雉堞的城墙、修士与骑士，边角发脆，墨色已经被时间咬出小洞","scene":"修道院的抄经房里，烛光下摊着羊皮卷，抄写者正一个字母一个字母地描。A medieval scribe copied the chronicle by candlelight, one letter at a time.","sceneCN":"这里 medieval 指「属于中世纪时期的」（第 1 个义项：时间上属中世纪）；句意为一位中世纪的抄写员借烛光逐字母抄录编年史。场景物件：羊皮卷、烛台、羽毛笔、窗洞。","pos":[{"tag":"adj.","zh":"中世纪的；中世纪风格的；中世纪式的"},{"tag":"n.","zh":"中世纪的人；(复数)中世纪的文物与研究"}],"collocations":[{"phrase":"medieval history","zh":"中世纪史"},{"phrase":"medieval architecture","zh":"中世纪建筑"},{"phrase":"medieval Europe","zh":"中世纪的欧洲"},{"phrase":"medieval Latin","zh":"中世纪拉丁语"},{"phrase":"medieval manuscript","zh":"中世纪手稿"},{"phrase":"medieval times","zh":"中世纪时期"}],"forms":[{"label":"比较级","form":"more medieval"},{"label":"最高级","form":"most medieval"},{"label":"名词复数","form":"medievals"},{"label":"异体拼写","form":"mediaeval"},{"label":"名词（中世纪学者）","form":"medievalist"}],"derivatives":[{"word":"medievalism","pos":"n.","zh":"中世纪风；中世纪研究"},{"word":"medievalist","pos":"n.","zh":"中世纪学者"},{"word":"medievalistic","pos":"adj.","zh":"中世纪研究式的"},{"word":"medievalize","pos":"v.","zh":"使中世纪化"},{"word":"mediaeval","pos":"adj.","zh":"中世纪的（旧拼法）"}],"senses":[{"no":"01","title":"Belonging to the Middle Ages","titleCN":"时间上属中世纪的","definition":"dating from or existing in the period between classical antiquity and the Renaissance","definitionCN":"属于古典时代与文艺复兴之间那段时期的","example":"A medieval scribe copied the chronicle by candlelight.","exampleCN":"一位中世纪的抄写员借烛光抄录编年史。","why":"the adjective simply dates a thing by placing it between the ancient and the modern, which is what medium aevum means.","whyCN":"这个形容词只按「夹在古代与现代之间」给事物定年，而 medium aevum 正是此意。"},{"no":"02","title":"Typical of the period's culture","titleCN":"具有中世纪文化特征的","definition":"showing the customs, faith, dress or building habits of that period","definitionCN":"表现出那一时期的习俗、信仰、衣着或营造方式","example":"The church keeps a medieval nave, a medieval rood screen and a medieval bell.","exampleCN":"这座教堂保有中世纪的中殿、圣像屏与铜钟。","why":"culture, not the calendar, is being named here: the shape of an arch or a rite identifies the age.","whyCN":"这里说的是文化而非日历：拱券的形状或一种仪式就标出了年代。"},{"no":"03","title":"Revived in medieval style","titleCN":"中世纪风格复兴的","definition":"made in deliberate imitation of medieval forms by a later age","definitionCN":"由后世刻意模仿中世纪形式而制作的","example":"Victorian architects added a medieval tower to a plain Georgian church.","exampleCN":"维多利亚时代的建筑师给一座朴素的乔治式教堂加上了中世纪风格的塔楼。","why":"once the period was safely past, copying it became a style, and the adjective moved from origin to imitation.","whyCN":"当那段时期安全地过去，模仿它就成了一种风格，形容词也从「出自当时」变成「仿其形」。"},{"no":"04","title":"Harsh and brutal, as imagined of the age","titleCN":"中世纪式的野蛮残酷","definition":"cruel or primitive in a way associated in popular memory with that period","definitionCN":"以一种大众记忆中所认为的中世纪方式残酷、原始","example":"The sentence was medieval in its plainness: a fine, a whip and a wall.","exampleCN":"那判决残酷得直白：罚金、鞭子与一堵墙。","why":"popular history reduced a long period to a single mood, and the adjective carried that mood into metaphors.","whyCN":"通俗历史把漫长的时期压缩成一种情绪，形容词便把这情绪带进比喻。"},{"no":"05","title":"Backward or outdated","titleCN":"落后守旧的","definition":"used of attitudes or systems thought to belong to a less advanced age","definitionCN":"指被认为属于较低发展阶段的态度或制度","example":"The company's medieval attitude to leave kept good staff away.","exampleCN":"公司那套中世纪式的休假态度把好员工挡在门外。","why":"the same historical distance now measures progress: to be medieval is to be behind, not merely old.","whyCN":"同一种历史距离此时用来衡量进步：说人「中世纪」就是说他落后，而不只是旧。"},{"no":"06","title":"A person who lived in the period","titleCN":"中世纪的人","definition":"a person living in the Middle Ages, used mostly in histories and in the plural","definitionCN":"生活在那一时期的人，多用于历史叙述与复数形式","example":"The medievals counted years from creation, not from a birth in Bethlehem.","exampleCN":"中世纪人从创世而非从伯利恒的那次降生起算年份。","why":"the noun is simply the adjective standing alone, a common English shortcut for 'people of that time'.","whyCN":"名词只是形容词独立使用，是英语里表示「那个时代的人」的常见省略。"},{"no":"07","title":"Objects or works of the period","titleCN":"中世纪的文物与作品","definition":"collected medieval artefacts or texts, used in the plural by dealers and scholars","definitionCN":"旧物商与学者用来指收集起来的中世纪器物或文本，多用复数","example":"The auction grouped the medievals with the early printed books.","exampleCN":"拍卖行把中世纪的器物与早期印本归在一起。","why":"specialist speech turns the adjective into a noun for the things themselves, so a category label becomes a shelf label.","whyCN":"专业行话把形容词转成指物件本身的名词，于是分类标签变成了货架标签。"},{"no":"08","title":"Of medieval Latin or manuscript tradition","titleCN":"中世纪拉丁语与手抄传统的","definition":"used of the Latin, script or textual tradition of the period, as distinct from classical forms","definitionCN":"指那一时期的拉丁语、字体或文本传统，以区别于古典形式","example":"The glossary lists medieval Latin spellings beside classical ones.","exampleCN":"这部词表把中世纪拉丁拼法列在古典拼法旁边。","why":"scholars needed a term for the period's own written language, and the adjective was narrowed onto the manuscript world.","whyCN":"学者需要为那一时期自身的书面语命名，形容词便收窄到手稿世界。"}],"etymology":{"intro":{"en":"Medieval goes back to Modern Latin medium aevum 'middle age', a label invented by scholars to name the gap between antiquity and their own day.","cn":"medieval 可追到近代拉丁 medium aevum「中间的时代」，这是学者为古代与自身时代之间的空档所造的标签。"},"items":[{"era":"MODERN LATIN MEDIUM AEVUM","en":"Medium aevum 'middle age' was coined by learned writers in the seventeenth century as a neutral dividing label.","cn":"medium aevum「中间的时代」由 17 世纪的学者造出，用作中性的分段标签。"},{"era":"LATIN MEDIUS AND AEVUM","en":"Medius 'middle' is an old Italic adjective, and aevum 'age, lifetime' supplies the time word; the deeper origin of aevum is not settled.","cn":"medius「中间」是古老的意大利语族形容词，aevum「年纪、一生」提供时间义；aevum 更深来源并无定论。"},{"era":"ENGLISH MEDIAEVAL","en":"English took the Modern Latin adjective mediaevalis in the early nineteenth century and spelled it mediaeval.","cn":"英语在 19 世纪初借入近代拉丁形容词 mediaevalis，拼作 mediaeval。"},{"era":"SPELLING SIMPLIFIED","en":"Twentieth-century printers dropped the digraph, so medieval is now standard while mediaeval survives in older titles.","cn":"20 世纪的印刷习惯去掉了二合元音，medieval 成为标准，mediaeval 只留在旧书名里。"},{"era":"TONE WIDENED","en":"The word also acquired a tone: to call something medieval can mean picturesque, superstitious or simply brutal.","cn":"这个词还带上语调：说某物「中世纪的」可以指如画、迷信，也可以指纯粹野蛮。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact year of the Latin coinage is undocumented, and the earliest English use is dated loosely to the 1810s to 1820s.","cn":"来源不确定（首见年代）：拉丁造词的确切年份无文献可查，英语最早用例只能约略定在 19 世纪一十至二十年代。"}]},"similar":{"note":{"en":"Group one holds the spellings and near neighbours of the same word; group two holds period words that are often substituted for it.","cn":"第一组是同一词的拼写变体与形近词；第二组是常被拿来替换它的分期词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mediaeval","ipa":"/ˌmediˈiːvəl/","tag":"same word, older spelling","definition":"The pre-twentieth-century spelling of the same adjective, still used in reprints of old scholarship.","definitionCN":"同一个形容词在 20 世纪前的拼法，仍见于旧学术著作的重印本。"},{"word":"medievalism","ipa":"/ˌmediˈiːvəlɪzəm/","tag":"the movement, not the period","definition":"The noun for the cult or imitation of medieval forms, so it names a later taste rather than a date.","definitionCN":"指对中世纪形式的迷恋或模仿，因此是后世的趣味，而非一个年代。"},{"word":"medievalist","ipa":"/ˌmediˈiːvəlɪst/","tag":"the scholar","definition":"A person who studies the period; the ending marks a person, not a time.","definitionCN":"指研究那一时期的学者；词尾标出的是人，不是时间。"},{"word":"middle-aged","ipa":"/ˌmɪdl ˈeɪdʒd/","tag":"different compound","definition":"Built from middle and age but means 'neither young nor old' about a person, with no historical reference.","definitionCN":"同样由 middle 与 age 构成，却指人「中年」，与历史分期无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ancient","ipa":"/ˈeɪnʃənt/","tag":"before the fall of Rome","definition":"Covers the Greek and Roman world and earlier; medieval begins where ancient ends.","definitionCN":"涵盖希腊罗马世界及更早时期；medieval 从 ancient 结束处开始。"},{"word":"classical","ipa":"/ˈklæsɪkl/","tag":"the high culture of Greece and Rome","definition":"Names the art and learning held up as models, which medieval culture was later said to have lost.","definitionCN":"指被奉为典范的希腊罗马艺术与学术，后世常说中世纪丢失了它们。"},{"word":"feudal","ipa":"/ˈfjuːdl/","tag":"the social system","definition":"A narrower word for land and service relations, not for the whole period or its art.","definitionCN":"较窄的词，指土地与服役关系，不指整个时期或其艺术。"},{"word":"gothic","ipa":"/ˈɡɒθɪk/","tag":"the architectural style","definition":"The pointed-arch style within the period, and later a taste for the gloomy and wild.","definitionCN":"指那一时期内的尖拱风格，后来也指对阴森狂野之趣的偏好。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin components, real spellings and real relatives.","cn":"正常联想：真实的拉丁成分、真实的拼写与现代同族词。"},"normal":[{"en":"medium aevum 'middle age': the period sits in the middle, between antiquity and the modern world.","cn":"medium aevum「中间的时代」：这一段夹在古代与现代之间。"},{"en":"The same media- appears in medium, median and intermediate, all 'middle' words.","cn":"同样的 media- 出现在 medium、median、intermediate，都是「中间」的词。"},{"en":"Two spellings are current in older texts: medieval and mediaeval.","cn":"旧文本里两种拼法都在用：medieval 与 mediaeval。"},{"en":"The family runs medieval, medievalism, medievalist, medievalistic, medievalize.","cn":"同族词包括 medieval、medievalism、medievalist、medievalistic、medievalize。"},{"en":"Fixed phrases date the word: medieval history, medieval Latin, medieval manuscript.","cn":"固定搭配替它定位：中世纪史、中世纪拉丁语、中世纪手稿。"}],"abstract":[{"en":"Picture a calendar with one long square greyed out between two bright ones.","cn":"想象一张日历，两个明亮的格子之间有一长格被涂成灰色。"},{"en":"Picture a candle burning beside a page that curls at the corner.","cn":"想象一支蜡烛在旁燃烧，纸页的一角卷了起来。"},{"en":"Picture a stone arch that is round below and pointed above.","cn":"想象一座石拱，下面圆、上面尖。"}]},"examples":[{"en":"Medieval walls still ring the old town, though the gates are gone.","cn":"中世纪的城墙仍围着老城，只是城门早已不存。"},{"en":"The museum labels the piece medieval, though its date is disputed.","cn":"博物馆把这件器物标为中世纪，尽管年代仍有争议。"},{"en":"Critics called the punishment medieval and demanded a review.","cn":"批评者称那项惩罚野蛮落后，要求复核。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「medi」听似「没底」，中间一段没底的年月 → 夹在古代与近代之间的中世纪","word":"medieval"},"root":"近代拉丁 medium aevum「中间的时代」= medius「中间」+ aevum「年纪、一生」；经近代拉丁形容词 mediaevalis 进入英语。aevum 的更深来源不确定。","sensesIntro":{"en":"Eight senses move from a date to a mood: a period, its culture, a later imitation of it, the cruelty and backwardness people read into it, and finally the people and manuscripts that carry the name.","cn":"八个义项从一个年代走向一种情绪：先是时期，再是时期的文化，再是后世的仿制，再是人们读进去的野蛮与落后，最后是承载这个名字的人与手稿。"},"semanticMap":{"core":{"en":"CORE IMAGE: a brittle parchment page showing a battlemented wall, a monk and a knight.","cn":"核心意象：一张发脆的羊皮纸，上面画着雉堞城墙、修士与骑士。"},"chain":["MIDDLE PERIOD","PERIOD CUSTOMS","PERIOD LOOK","REVIVED LOOK","HARSHNESS","BACKWARDNESS"],"branches":[{"senses":"S1 · S2","en":"DATE AND CULTURE: one sense places a thing in time, the other reads the period's habits from the thing itself.","cn":"年代与文化：一个义项替事物定位在时间上，另一个从事物本身读出那一时期的习惯。"},{"senses":"S3","en":"REVIVAL: a later age copies the forms, and origin becomes imitation.","cn":"复兴：后世复制其形制，于是「出自当时」变成「仿其形」。"},{"senses":"S4 · S5","en":"JUDGEMENT: the same distance that makes the period picturesque also makes it a byword for cruelty and backwardness.","cn":"评判：同一种距离既让那时期显得如画，也让其成为野蛮与落后的代名词。"},{"senses":"S6 · S7","en":"PEOPLE AND OBJECTS: the adjective standing alone names the people of the period and, in trade talk, their artefacts.","cn":"人与物：形容词独立使用指那一时期的人，在行话里也指其器物。"},{"senses":"S8","en":"MANUSCRIPT TRADITION: scholarship narrows the word onto the period's own Latin, script and texts.","cn":"手稿传统：学术用法把它收窄到那一时期自身的拉丁语、字体与文本。"}]},"affixes":{"intro":{"en":"Medieval is a Modern Latin phrase compressed into one English adjective, and its pieces also build other common words.","cn":"medieval 是把一个近代拉丁短语压缩成的一个英语形容词，它的各部分还构成别的常用词。"},"latinIntro":{"en":"Latin medius 'middle' also yields medium, median and intermediate, while aevum 'age' appears in longevity and in aevum-based historical labels.","cn":"拉丁 medius「中间」还衍生 medium、median、intermediate；aevum「年纪」见于 longevity 及以 aevum 构成的历史标签。"},"items":[{"word":"medi-","structure":"medius (Latin adjective, 'middle')","meaning":"middle","meaningCN":"中间","example":"The root places the period between two others.","exampleCN":"这个词根把这一段放在另外两段之间。"},{"word":"aev-","structure":"aevum (Latin noun, 'age, lifetime')","meaning":"age; lifetime","meaningCN":"年纪；一生","example":"The second element supplies the time span.","exampleCN":"第二个成分提供时间跨度。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与…相关的","example":"The suffix turns the phrase into an adjective.","exampleCN":"这个后缀把短语变成形容词。"},{"word":"medieval","structure":"medium aevum + -alis","meaning":"relating to the middle age","meaningCN":"中世纪的","example":"The medieval register is still legible.","exampleCN":"那本中世纪的登记簿仍可辨读。"},{"word":"medievalism","structure":"medieval + -ism","meaning":"the cult or study of medieval forms","meaningCN":"中世纪风；中世纪研究","example":"Medievalism rebuilt the abbey in pointed arches.","exampleCN":"中世纪风用尖拱重建了这座修道院。"},{"word":"medievalist","structure":"medieval + -ist","meaning":"a student of the period","meaningCN":"中世纪学者","example":"The medievalist read the charter aloud.","exampleCN":"这位中世纪学者把特许状读了出来。"},{"word":"medievalistic","structure":"medievalist + -ic","meaning":"in the manner of medieval scholarship","meaningCN":"中世纪研究式的","example":"The essay has a medievalistic fondness for lineage.","exampleCN":"这篇文章带着中世纪研究式的谱系癖。"},{"word":"medievalize","structure":"medieval + -ize","meaning":"to make medieval in style","meaningCN":"使中世纪化","example":"The filmmaker medievalized the city with fake towers.","exampleCN":"制片人用假塔楼把这座城市中世纪化。"},{"word":"mediaeval","structure":"variant spelling of medieval","meaning":"the older spelling","meaningCN":"中世纪的旧拼法","example":"The mediaeval spelling survives in reprints.","exampleCN":"mediaeval 这一旧拼法仍留在重印本里。"}],"latinEntries":[{"word":"medius","structure":"medius, media, medium (adjective)","meaning":"middle, in the middle","meaningCN":"中间的"},{"word":"aevum","structure":"aevum, aevi (n., second declension)","meaning":"age, lifetime, eternity","meaningCN":"年纪；一生；漫长岁月"},{"word":"mediaevalis","structure":"mediaevalis, mediaevale (Modern Latin adjective)","meaning":"of the middle age","meaningCN":"中世纪的"}]}},{"word":"medievalism","ipa_uk":"/ˌmiːdiˈiːvəlɪzəm/","ipa_us":"/ˌmediˈiːvəlɪzəm/","definition_zh":"中世纪研究；中世纪精神；对中世纪的模仿与迷恋；中古语词用法","definition_en":"the study of the Middle Ages, or the imitation and cult of medieval forms in later art, architecture and politics","core_image":"一间十九世纪的书房，墙上壁纸印着尖拱花纹，角落立着一副仿制盔甲，书架上并排放着校勘本与骑士小说","scene":"十九世纪的教堂翻修现场，尖拱与彩窗被重新装点，脚手架一直搭到屋脊。Victorian medievalism turned parish churches into stage sets of knighthood.","sceneCN":"这里 medievalism 指「后世对中世纪形式的模仿与迷恋」（第 4 个义项：艺术与文学中的仿中世纪风气）；句意为维多利亚时代的中世纪风潮把教区教堂改造成了骑士制度的舞台布景。场景物件：尖拱、彩窗、仿制盔甲、脚手架。","pos":[{"tag":"n.","zh":"中世纪研究；中世纪精神；仿中世纪风气；中古语词用法"}],"collocations":[{"phrase":"Victorian medievalism","zh":"维多利亚时代的中世纪风"},{"phrase":"romantic medievalism","zh":"浪漫化的中世纪崇拜"},{"phrase":"medievalism in architecture","zh":"建筑中的仿中世纪做法"},{"phrase":"the study of medievalism","zh":"中世纪研究"},{"phrase":"popular medievalism","zh":"大众文化中的中世纪风"}],"forms":[{"label":"复数","form":"medievalisms"},{"label":"指人的名词","form":"medievalist"},{"label":"形容词","form":"medievalistic"},{"label":"异体拼写","form":"mediaevalism"}],"derivatives":[{"word":"medievalist","pos":"n.","zh":"中世纪学者；仿古风爱好者"},{"word":"medievalistic","pos":"adj.","zh":"中世纪研究式的；仿中世纪的"},{"word":"medieval","pos":"adj.","zh":"中世纪的"},{"word":"medievalize","pos":"v.","zh":"使中世纪化"},{"word":"mediaevalism","pos":"n.","zh":"中世纪风（旧拼法）"}],"senses":[{"no":"01","title":"The academic study of the Middle Ages","titleCN":"中世纪研究这一学科","definition":"the scholarly field that reads the documents, buildings and artefacts of the period","definitionCN":"研读那一时期文书、建筑与器物的学术领域","example":"Medievalism as a department grew out of nineteenth-century antiquarian clubs.","exampleCN":"作为学科的中世纪研究，是从 19 世纪的古物社团里长出来的。","why":"the suffix -ism names a system or practice, so the word could label a discipline before it labelled a taste.","whyCN":"后缀 -ism 表示一套做法或体系，因此它先能指一门学问，之后才指一种趣味。"},{"no":"02","title":"The spirit or outlook of the period","titleCN":"中世纪的精神气质","definition":"the faith, hierarchy and imaginative world taken to be characteristic of the age","definitionCN":"被认为是那一时期特有的信仰、等级秩序与想象世界","example":"Critics praised the medievalism of the poem, its candles and its unquestioned order.","exampleCN":"批评家称赞这首诗的中世纪气质，那烛火与不容置疑的秩序。","why":"the word names an atmosphere rather than a date, which lets writers use it of any work that feels anchored in that world.","whyCN":"这个词指的是一种气氛而不是年代，因此作家可以用它形容任何像扎根于那个世界的作品。"},{"no":"03","title":"A surviving medieval custom or word","titleCN":"留存到后世的中世纪习俗或语词","definition":"a habit, idiom or institution that outlived the period and still marks later life","definitionCN":"比那个时期活得更久、仍留在后世生活中的习俗、语词或制度","example":"The mayor's oath is a medievalism that no statute has ever repealed.","exampleCN":"市长的誓词是一处中世纪的遗留，没有任何成文法废除过它。","why":"the suffix can also mark a single surviving item, so one word covers customs, phrases and offices alike.","whyCN":"这个后缀也能标出单件遗留物，因此一个词同时覆盖习俗、语句与职位。"},{"no":"04","title":"Imitation of medieval forms in art and literature","titleCN":"艺术与文学中的仿中世纪风气","definition":"the deliberate revival of medieval story, ornament and mood by later writers and artists","definitionCN":"后世作家与艺术家刻意复兴中世纪的叙事、装饰与情调","example":"Scott's romances gave nineteenth-century medievalism its pictures and its vocabulary.","exampleCN":"司各特的传奇小说为 19 世纪的中世纪风提供了画面与词汇。","why":"once the period was distant enough to be enjoyed, copying it became a fashion with its own market.","whyCN":"当那段时期远到可以被欣赏，模仿它就成了一种有市场的风气。"},{"no":"05","title":"A word or form peculiar to Middle English","titleCN":"中古英语特有的词语或形式","definition":"a spelling, ending or expression that belongs to the English of the period and is kept for effect","definitionCN":"属于那一时期英语的拼法、词尾或说法，被后人为了效果而保留","example":"The translator kept one medievalism per page to hold the flavour of the source.","exampleCN":"译者每页保留一处中古语词，以维持原作的韵味。","why":"language study gave the word this narrow sense, where a single archaic item is itself called a medievalism.","whyCN":"语言研究给了这个词这层窄义：单件古旧语词本身就被称作一处中世纪遗留。"},{"no":"06","title":"Nineteenth-century romantic cult of the Middle Ages","titleCN":"十九世纪浪漫化的中世纪崇拜","definition":"the fashion that idealised the period as a world of faith, honour and craft","definitionCN":"把那一时期理想化为信仰、荣誉与手艺之世界的风尚","example":"Nineteenth-century medievalism decorated factories with battlements.","exampleCN":"19 世纪的中世纪崇拜给工厂也装上了雉堞。","why":"the movement had a clear social face: industrial cities dressed themselves in a past they had not lived in.","whyCN":"这场风潮有清楚的社会面孔：工业城市给自己披上一件自己并未亲历的过去。"},{"no":"07","title":"Political use of medieval imagery","titleCN":"以中世纪意象包装的政治主张","definition":"the appeal to medieval order, hierarchy or community to support a modern political program","definitionCN":"借中世纪的秩序、等级或共同体来支撑现代政治主张","example":"Reactionary medievalism offered the manor as a cure for the strike.","exampleCN":"反动的中世纪主义把庄园当作罢工的解药。","why":"the same images can be turned to argument, so scholars now watch how the past is used rather than only how it is copied.","whyCN":"同样的意象可以被拿来论证，因此学者如今关注过去如何被使用，而不只是如何被复制。"},{"no":"08","title":"Medieval style in building","titleCN":"建筑中的仿中世纪做法","definition":"the use of pointed arches, tracery and heavy walls in buildings erected much later","definitionCN":"在远晚于中世纪的建筑上使用尖拱、窗花格与厚重墙体","example":"The railway hotel is a monument of commercial medievalism.","exampleCN":"那座铁路旅馆是商业性仿中世纪建筑的纪念碑。","why":"architecture gave the movement its most visible body, and the word still labels a building style before it labels a belief.","whyCN":"建筑给了这场风潮最可见的形体，这个词至今先标建筑风格，再标信念。"}],"etymology":{"intro":{"en":"Medievalism is a modern English compound of medieval and the noun suffix -ism, formed when both the academic field and the revival fashion were new.","cn":"medievalism 是近代英语用 medieval 加名词后缀 -ism 构成的复合词，成形时学术领域与复古风气都还年轻。"},"items":[{"era":"MEDIEVAL PLUS -ISM","en":"The word joins medieval to -ism, a suffix for a practice, system or devotion, and dates from the early nineteenth century.","cn":"这个词把 medieval 接上 -ism（表示做法、体系或热衷的后缀），最早见于 19 世纪初。"},{"era":"SUFFIX FROM GREEK","en":"-ism came through French and Latin -ismus from Greek -ismos, which marked an action or a party.","cn":"-ism 经法语与拉丁 -ismus 来自希腊 -ismos，原标动作或派别。"},{"era":"FIRST ACADEMIC USE","en":"Early uses named the study of medieval charters, churches and coins, a neutral label for a young discipline.","cn":"早期用法指对中世纪特许状、教堂与钱币的研究，是这门年轻学科的中性标签。"},{"era":"ROMANTIC WIDENING","en":"By the 1840s the same word described the Gothic revival and its literary taste, so it could praise or mock.","cn":"到 19 世纪四十年代，同一个词开始形容哥特复兴及其文学趣味，于是既可褒也可贬。"},{"era":"MODERN RANGE","en":"Today it covers scholarship, fantasy fiction, re-enactment and political nostalgia, and only context separates them.","cn":"今天它覆盖学术、幻想文学、历史重演与政治怀旧，只能靠语境区分。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English example is dated loosely to the 1830s to 1840s, and the priority of the academic over the artistic sense is not settled.","cn":"来源不确定（首见年代）：英语最早用例只能约略定在 19 世纪三十至四十年代；学术义与艺术义孰先孰后亦无定论。"}]},"similar":{"note":{"en":"Group one holds words formed on the same medieval stem; group two holds rival names for revivals and for the study of the past.","cn":"第一组是同出 medieval 词干的词；第二组是复兴运动与好古之学的竞争性名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"medievalist","ipa":"/ˌmediˈiːvəlɪst/","tag":"the person","definition":"The scholar or enthusiast, marked by the agent suffix; the -ism names the field, not the worker.","definitionCN":"指学者或爱好者，由施事后缀标出；-ism 指领域，不指人。"},{"word":"medieval","ipa":"/ˌmediˈiːvəl/","tag":"the adjective","definition":"Simply dates or describes something as belonging to the period, without naming a movement.","definitionCN":"只把事物定年或描述为属于那一时期，不指一场运动。"},{"word":"mediaevalism","ipa":"/ˌmediˈiːvəlɪzəm/","tag":"older spelling","definition":"The same word before twentieth-century spelling reform, still met in older bibliographies.","definitionCN":"20 世纪拼写简化前的同一词，仍见于旧书目。"},{"word":"modernism","ipa":"/ˈmɒdənɪzəm/","tag":"the mirror image","definition":"A parallel -ism, but one that broke with the past on purpose, which is the reverse of this word.","definitionCN":"同样是 -ism，却刻意与过去决裂，方向正好相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"Gothic Revival","ipa":"/ˈɡɒθɪk rɪˈvaɪvl/","tag":"the architectural movement","definition":"The building side of the revival, named for the pointed style rather than for the period as a whole.","definitionCN":"复兴在建筑上的那一面，以尖拱风格而非整个时期命名。"},{"word":"romanticism","ipa":"/rəʊˈmæntɪsɪzəm/","tag":"the wider cult of feeling and the past","definition":"A broad literary movement that fed medievalism but also looked to nature, the self and the exotic.","definitionCN":"广泛的文学运动，滋养了中世纪风，却也转向自然、自我与异域。"},{"word":"antiquarianism","ipa":"/ˌæntɪˈkweəriənɪzəm/","tag":"collecting rather than copying","definition":"Care for old objects and documents without the wish to rebuild their world in the present.","definitionCN":"在意旧物与旧文献，却没有在当下重建那个世界的愿望。"},{"word":"classicism","ipa":"/ˈklæsɪsɪzəm/","tag":"the ancient counterpart","definition":"The imitation of Greek and Roman models, the rival revival that medievalism set itself against.","definitionCN":"对希腊罗马范式的模仿，是中世纪风所对抗的竞争性复兴。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real compound, a real suffix and real movements that share the name.","cn":"正常联想：真实的复合结构、真实的后缀与真实同名运动。"},"normal":[{"en":"medieval + -ism: the -ism turns a period label into a practice or a cult.","cn":"medieval + -ism：这个后缀把年代标签变成一种做法或热衷。"},{"en":"-ism is the same suffix as in realism, classicism and romanticism, all names of stances.","cn":"-ism 与 realism、classicism、romanticism 用的是同一个后缀，都是立场之名。"},{"en":"The family runs medieval, medievalism, medievalist, medievalistic, medievalize.","cn":"同族词包括 medieval、medievalism、medievalist、medievalistic、medievalize。"},{"en":"Architecture makes the movement visible: pointed arches, tracery, battlements.","cn":"建筑让这场风气可见：尖拱、窗花格、雉堞。"},{"en":"Scholarship and fandom share the word, so a conference and a fantasy fair may both print it.","cn":"学术与粉丝共用这个词，因此一场研讨会和一场幻想市集都可能印上它。"}],"abstract":[{"en":"Picture wallpaper printed with pointed arches behind a plastic suit of armour.","cn":"想象尖拱花纹的壁纸后面立着一套塑料盔甲。"},{"en":"Picture a factory chimney wearing battlements like a castle.","cn":"想象一根工厂烟囱戴着城堡般的雉堞。"},{"en":"Picture a paperback knight beside a leather-bound charter on one shelf.","cn":"想象同一层书架上，平装骑士小说挨着一册皮面特许状。"}]},"examples":[{"en":"Victorian medievalism rebuilt the abbey and invented half its history.","cn":"维多利亚时代的中世纪风重建了这座修道院，还替它编出半部历史。"},{"en":"Her book studies medievalism in advertising rather than in poetry.","cn":"她的书研究的是广告里的中世纪风，而非诗歌里的。"},{"en":"The word itself is a medievalism kept alive by legal oaths.","cn":"这个词本身就是靠法律誓词存活下来的一处中古遗留。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「medi」像「没底」，「eval」像「一窝」——没底的一窝旧东西被后人反复模仿 → 中世纪风","word":"medievalism"},"root":"近代英语复合词：medieval（近代拉丁 medium aevum「中间的时代」）+ -ism（经法语、拉丁 -ismus 来自希腊 -ismos，表做法或体系）。","sensesIntro":{"en":"Eight senses split between a discipline and a fashion: the study of the period, its surviving traits, the later imitation of its art and buildings, and the political use of its images.","cn":"八个义项在「学问」与「风气」之间分开：对那一时期的研究、它留存下来的特征、后世对其艺术与建筑的模仿，以及对其意象的政治使用。"},"semanticMap":{"core":{"en":"CORE IMAGE: a nineteenth-century study where pointed wallpaper, imitation armour and a leather charter share one room.","cn":"核心意象：一间 19 世纪的书房，尖拱壁纸、仿制盔甲与皮面特许状共处一室。"},"chain":["MIDDLE AGES","STUDY OF THE PERIOD","SURVIVING TRAITS","ROMANTIC IMITATION","POLITICAL USE","BUILT STYLE"],"branches":[{"senses":"S1 · S2","en":"DISCIPLINE AND MOOD: one sense is a field with archives, the other an atmosphere felt in a work.","cn":"学科与气氛：一个义项是有档案的领域，另一个是在作品里感到的气氛。"},{"senses":"S3 · S5","en":"SURVIVALS: customs, offices and archaic words outlive the period and are each called a medievalism.","cn":"遗留物：习俗、职位与古旧语词都比时期活得久，各自被称作一处中世纪遗留。"},{"senses":"S4 · S6","en":"ROMANTIC COPY: literature first, then the wider nineteenth-century cult that dressed industry in the past.","cn":"浪漫化的复制：先有文学，再有更广的 19 世纪风潮，把工业披上过去的外衣。"},{"senses":"S7","en":"POLITICS: the same images become an argument about how the present should be ordered.","cn":"政治：同样的意象变成关于当下应如何被组织的论证。"},{"senses":"S8","en":"BUILT FORM: pointed arches and heavy walls give the movement its most visible body.","cn":"建筑形体：尖拱与厚墙给了这场风气最可见的躯体。"}]},"affixes":{"intro":{"en":"Medievalism is transparent: a period adjective plus a suffix of stance, and the same pieces build dozens of movement names.","cn":"medievalism 结构透明：一个时期形容词加一个表立场的后缀，同样的部件构成许多运动名称。"},"latinIntro":{"en":"The first element rests on Latin medius and aevum through Modern Latin mediaevalis; the suffix -ism came from Greek -ismos by way of Latin and French.","cn":"前半部分经近代拉丁 mediaevalis 上承拉丁 medius 与 aevum；后缀 -ism 经拉丁与法语来自希腊 -ismos。"},"items":[{"word":"medieval","structure":"medium aevum + -alis","meaning":"of the Middle Ages","meaningCN":"中世纪的","example":"The medieval charter is the oldest item in the chest.","exampleCN":"那册中世纪特许状是箱中最旧的东西。"},{"word":"-ism","structure":"-ismus from Greek -ismos","meaning":"practice, system, devotion","meaningCN":"做法；体系；热衷","example":"The suffix also builds realism and classicism.","exampleCN":"这个后缀还构成 realism 与 classicism。"},{"word":"medievalism","structure":"medieval + -ism","meaning":"study or imitation of the period","meaningCN":"中世纪研究；中世纪风","example":"Medievalism filled the church with pointed arches.","exampleCN":"中世纪风让教堂布满尖拱。"},{"word":"medievalist","structure":"medieval + -ist","meaning":"person devoted to the period","meaningCN":"中世纪学者","example":"The medievalist edited the chronicle.","exampleCN":"这位中世纪学者校订了那部编年史。"},{"word":"medievalistic","structure":"medievalist + -ic","meaning":"in the manner of such study","meaningCN":"中世纪研究式的","example":"The notes have a medievalistic interest in lineage.","exampleCN":"这些注释带着中世纪研究式的谱系兴趣。"},{"word":"medievalize","structure":"medieval + -ize","meaning":"to make medieval","meaningCN":"使中世纪化","example":"The set designer medievalized the whole street.","exampleCN":"布景师把整条街中世纪化了。"},{"word":"mediaevalism","structure":"older spelling of medievalism","meaning":"the older form of the word","meaningCN":"中世纪风的旧拼法","example":"Mediaevalism appears in nineteenth-century essays.","exampleCN":"mediaevalism 见于 19 世纪的随笔。"},{"word":"-ist","structure":"-ista from Greek","meaning":"agent suffix for a person","meaningCN":"表人的施事后缀","example":"It also marks novelist and archaeologist.","exampleCN":"它也标出 novelist 与 archaeologist。"},{"word":"-istic","structure":"-isticus from Greek -istikos","meaning":"adjective of manner","meaningCN":"表方式或派别的形容词后缀","example":"It turns an agent noun into a descriptive adjective.","exampleCN":"它把施事名词变成描述性形容词。"}],"latinEntries":[{"word":"medius","structure":"medius, media, medium (adjective)","meaning":"middle","meaningCN":"中间的"},{"word":"aevum","structure":"aevum, aevi (n., second declension)","meaning":"age, lifetime","meaningCN":"年纪；一生"},{"word":"mediaevalis","structure":"mediaevalis, mediaevale (Modern Latin adjective)","meaning":"of the middle age","meaningCN":"中世纪的"}]}},{"word":"Renaissance","ipa_uk":"/ˈrenəsɑːns/","ipa_us":"/ˈrenəsɑːns/","definition_zh":"文艺复兴；文艺复兴时期；复兴、再生；文艺复兴风格的","definition_en":"the European revival of classical learning and art from the fourteenth to the seventeenth century, or any similar rebirth","core_image":"一座尚未完工的圆顶教堂，脚手架上摆着测绳与古柱残段，工匠照着罗马废墟的样式把石块重新叠起","scene":"一座尚未完工的圆顶教堂，脚手架上放着测绳与从废墟运来的古柱残段。Renaissance architects measured Roman ruins and drew them back into new domes.","sceneCN":"这里 Renaissance 指「以复兴古典为旗帜的那场欧洲文化运动」（第 1 个义项：文艺复兴运动）；句意为文艺复兴时期的建筑师丈量罗马废墟，再把这些形制重新画进新的圆顶。场景物件：圆顶、脚手架、测绳、古柱残段。","pos":[{"tag":"n.","zh":"文艺复兴；文艺复兴时期；复兴、再生"},{"tag":"adj.","zh":"文艺复兴的；文艺复兴风格的"}],"collocations":[{"phrase":"the Italian Renaissance","zh":"意大利文艺复兴"},{"phrase":"Renaissance art","zh":"文艺复兴艺术"},{"phrase":"early Renaissance","zh":"文艺复兴早期"},{"phrase":"Harlem Renaissance","zh":"哈莱姆文艺复兴"},{"phrase":"Renaissance man","zh":"多才多艺的文艺复兴式人物"},{"phrase":"a renaissance of the city","zh":"城市的复兴"}],"forms":[{"label":"复数","form":"Renaissances"},{"label":"小写通用名词","form":"renaissance"},{"label":"小写复数","form":"renaissances"},{"label":"定语用法","form":"Renaissance（作定语）"}],"derivatives":[{"word":"renascence","pos":"n.","zh":"再生；复兴"},{"word":"renascent","pos":"adj.","zh":"再生的；复兴中的"},{"word":"Renaissance man","pos":"n.","zh":"多才多艺之人"},{"word":"Renaissance revival","pos":"n.","zh":"文艺复兴式复兴"}],"senses":[{"no":"01","title":"The European classical revival","titleCN":"欧洲文艺复兴运动","definition":"the movement that revived classical learning, art and letters in Europe from the fourteenth to the seventeenth century","definitionCN":"十四至十七世纪在欧洲复兴古典学术、艺术与文学的那场运动","example":"Renaissance architects measured Roman ruins and drew them back into new domes.","exampleCN":"文艺复兴时期的建筑师丈量罗马废墟，再把它们画进新的圆顶。","why":"French renaissance means 'rebirth', and the movement was understood by its own promoters as the rebirth of a buried classical world.","whyCN":"法语 renaissance 意为「重生」，这场运动的倡导者自己就把它理解为被埋没的古典世界重新出生。"},{"no":"02","title":"The historical period","titleCN":"文艺复兴时期","definition":"the era in European history when that revival took place, roughly the fourteenth to the sixteenth century","definitionCN":"那场复兴发生时的欧洲历史阶段，约当十四至十六世纪","example":"Prices rose across the Renaissance, and patrons paid painters in wheat as often as in coin.","exampleCN":"整个文艺复兴时期物价上涨，赞助人付给画家的常常是麦子而不是钱币。","why":"a movement name became a period name, the usual path by which cultural labels turn into dates.","whyCN":"运动之名变成了时期之名，这是文化标签转为年代标签的常见路径。"},{"no":"03","title":"A national branch of the movement","titleCN":"某一国的文艺复兴","definition":"the corresponding revival in one country, usually with its own dates and schools","definitionCN":"同一复兴在某一国的对应阶段，通常有自己的年代与流派","example":"The English Renaissance arrived late and borrowed its grammar from Italy.","exampleCN":"英国文艺复兴来得晚，语法还是从意大利借来的。","why":"because the movement spread unevenly, historians needed compound labels such as English or Northern Renaissance.","whyCN":"由于这场运动传播不均，史家需要「英国文艺复兴」「北方文艺复兴」这类复合标签。"},{"no":"04","title":"A later parallel revival","titleCN":"后世类似的全面复兴","definition":"a later cultural flowering named by analogy with the European one","definitionCN":"以欧洲那场运动为类比而命名的后世文化繁荣","example":"The Harlem Renaissance put new fiction, music and painting in one decade.","exampleCN":"哈莱姆文艺复兴把新的小说、音乐与绘画集中在同一个十年。","why":"the name travels because the shape repeats: a community turns to its own sources and produces a burst of art.","whyCN":"这个名字之所以能移植，是因为形状重复：一个群体转向自身根源，随即产出一阵艺术喷发。"},{"no":"05","title":"A general rebirth or renewal","titleCN":"广义的复兴、再生","definition":"a broad return of vigour to a place, institution or activity","definitionCN":"某地、某机构或某项活动重新获得活力的广泛回潮","example":"The old port is enjoying a renaissance after the warehouses became studios.","exampleCN":"仓库改成工作室之后，这座老港正经历一场复兴。","why":"wrenched from its historical setting, the word simply means being born again, and English uses it for any revival.","whyCN":"脱离历史语境后，这个词只剩「重新出生」的意思，英语便用它指任何回潮。"},{"no":"06","title":"The art style of the period","titleCN":"文艺复兴艺术风格","definition":"the style of painting, sculpture and building that the movement produced","definitionCN":"这场运动所产生的绘画、雕塑与建筑风格","example":"The gallery hangs Renaissance next to Baroque, and the difference is visible at once.","exampleCN":"美术馆把文艺复兴作品挂在巴洛克旁边，差别一眼可见。","why":"style is the most portable part of the movement, so a single adjective can label a whole wall of pictures.","whyCN":"风格是这场运动中最易搬运的部分，因此一个形容词就能标出整墙的画。"},{"no":"07","title":"Used before a noun: of that style","titleCN":"定语用法：文艺复兴式的","definition":"placed before a noun to mark something made in or about that style","definitionCN":"置于名词前，标出某物属于或关于那种风格","example":"Renaissance perspective treats the canvas as a window onto a measured room.","exampleCN":"文艺复兴式的透视把画布当作望向一个经过丈量的房间的窗。","why":"English routinely uses period names as modifiers, so Renaissance painting needs no suffix to become an adjective.","whyCN":"英语习惯把时期名直接作修饰语，因此文艺复兴绘画无需后缀就成了形容词。"},{"no":"08","title":"A personal second flowering","titleCN":"个人或事业的第二春","definition":"a late period of renewed achievement in a person's life or work","definitionCN":"一个人或一项工作在后来的阶段重新取得成就","example":"Her Renaissance came at sixty, with the best work of her life.","exampleCN":"她的第二春在六十岁到来，带来一生最好的作品。","why":"the metaphor borrows the grand historical rebirth for a private one, and the irony is usually kind.","whyCN":"这个比喻把宏大的历史复兴借给私人经历，语调通常是善意的。"}],"etymology":{"intro":{"en":"Renaissance is a French noun meaning 'rebirth', from renaître 'to be born again', and English borrowed it first as a common noun before it became a period label.","cn":"Renaissance 是法语名词，意为「重生」，出自 renaître「重新出生」；英语先把它当普通名词借入，后来才用作时期标签。"},"items":[{"era":"FRENCH RENAISSANCE","en":"French renaissance is the noun of renaître 'to be born again', formed with re- 'again' and naître 'to be born'.","cn":"法语 renaissance 是 renaître「重新出生」的名词，由 re-「再次」与 naître「出生」构成。"},{"era":"LATIN NASCI","en":"naître continues Latin nasci 'to be born', whose root also lies behind native, nature and nascent.","cn":"naître 上承拉丁 nasci「出生」，其词根也藏在 native、nature、nascent 里。"},{"era":"ENGLISH BORROWING","en":"English took the French word in the seventeenth century for 'rebirth', often with a religious or literary colour.","cn":"英语在 17 世纪借入这个法语词，意为「重生」，常带宗教或文学色彩。"},{"era":"PERIOD LABEL","en":"Nineteenth-century historians, notably Michelet and Burckhardt, fixed the capitalised sense for the Italian-led revival.","cn":"19 世纪史家，尤其是米什莱与布克哈特，把大写形式固定为意大利主导的那场复兴。"},{"era":"WIDENING","en":"From a period name it became a common noun for any vigorous revival, as in the Harlem Renaissance or a city's renaissance.","cn":"它从时期名变成指任何强劲复兴的普通名词，如哈莱姆文艺复兴或城市的复兴。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English uses are recorded in the 1600s, but the point at which the capitalised period sense became standard is not documented precisely.","cn":"来源不确定（首见年代）：英语最早用例见于 17 世纪，但大写时期义何时成为标准并无精确记载。"}]},"similar":{"note":{"en":"Group one holds words from the same 'born again' stock; group two holds the neighbouring movements and labels.","cn":"第一组是同出「重新出生」词干的词；第二组是相邻的运动与标签。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"renascence","ipa":"/rɪˈnæsəns/","tag":"rarer synonym","definition":"An English form of the same Latin base, used for rebirth in general and sometimes for the period by older writers.","definitionCN":"同一拉丁词基的英语形式，泛指重生，旧时作家有时也用来指那个时期。"},{"word":"renascent","ipa":"/rɪˈnæsnt/","tag":"the adjective","definition":"Means 'coming back to life or vigour', and describes the process rather than the era.","definitionCN":"意为「正在复活、重新有力」，描述过程而非时代。"},{"word":"nascent","ipa":"/ˈnæsnt/","tag":"just being born","definition":"From the same nasci root but means 'only beginning to exist', without any idea of return.","definitionCN":"同出 nasci 词根，却指「刚出现」，不含「返回」之意。"},{"word":"Reformation","ipa":"/ˌrefəˈmeɪʃn/","tag":"near in time, different word","definition":"The religious movement of the same centuries, named for reshaping rather than rebirth, and constantly paired with this word in courses.","definitionCN":"同一时代前后的宗教运动，名字取「重塑」而非「重生」，在课程里常与这个词并列。"}]},{"heading":"NEAR MEANING","entries":[{"word":"revival","ipa":"/rɪˈvaɪvl/","tag":"general return of vigour","definition":"Any return of activity or interest, religious or commercial; the everyday word behind the grander label.","definitionCN":"活动或兴趣的任何回潮，宗教或商业皆可；是大标签背后的日常词。"},{"word":"rebirth","ipa":"/ˌriːˈbɜːθ/","tag":"literal or spiritual new birth","definition":"A plain noun for being born again, used of people and faith as well as of art.","definitionCN":"指重新出生的普通名词，可用于人、信仰，也可用于艺术。"},{"word":"restoration","ipa":"/ˌrestəˈreɪʃn/","tag":"putting back a former state","definition":"Suggests returning something to what it was, often a building or a monarchy, not producing something new.","definitionCN":"指把某物恢复到原状，常用于建筑或王权，而不是产生新东西。"},{"word":"golden age","ipa":"/ˌɡəʊldən ˈeɪdʒ/","tag":"idealised past","definition":"A perfect earlier time imagined by later people; it looks backward without claiming a present rebirth.","definitionCN":"后人想象出的完美早期；它只向后看，并不声称当下已重生。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real French word, a real Latin root and real period labels.","cn":"正常联想：真实的法语词、真实的拉丁词根与真实的时期标签。"},"normal":[{"en":"re- 'again' + naissance 'birth' = a second birth of the classical world.","cn":"re-「再次」+ naissance「出生」= 古典世界的第二次出生。"},{"en":"naissance is French for birth; the same nasci root gives native, nature and nascent.","cn":"naissance 是法语的「出生」；同一 nasci 词根还给出 native、nature、nascent。"},{"en":"The capital letter marks the historical period; the lowercase form marks any revival.","cn":"大写标历史时期，小写标任何复兴。"},{"en":"Compound labels branch out: Italian Renaissance, English Renaissance, Harlem Renaissance.","cn":"复合标签分出多支：意大利文艺复兴、英国文艺复兴、哈莱姆文艺复兴。"},{"en":"Two historians fixed the label: Michelet in the 1850s and Burckhardt in 1860.","cn":"两位史家固定了这个标签：米什莱在 1850 年代，布克哈特在 1860 年。"}],"abstract":[{"en":"Picture a plaster cast of a Roman head standing in a bright new studio.","cn":"想象一尊罗马头像的石膏模放在明亮的新画室里。"},{"en":"Picture a soot-dark fresco coming back to colour under a wet cloth.","cn":"想象一幅被烟熏黑的壁画在湿布下重新显出颜色。"},{"en":"Picture an old harbour where cranes have become street lamps.","cn":"想象一座老港，吊车被改成了街灯。"}]},"examples":[{"en":"Renaissance painters placed their figures in rooms built by rules of perspective.","cn":"文艺复兴画家把人物安置在按透视规则造出的房间里。"},{"en":"The city's renaissance began with a single restored theatre.","cn":"这座城市的复兴从一座修复的剧院开始。"},{"en":"She had a Renaissance at seventy and learned the cello.","cn":"她在七十岁迎来第二春，学会了拉大提琴。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞那桑斯」听似「重又亮起来」——被埋没的古典世界重新亮相 → 文艺复兴","word":"Renaissance"},"root":"法语 renaissance「重生」= re-「再次」+ naître「出生」，naître 上承拉丁 nasci「出生」；同根词有 native、nature、nascent。","sensesIntro":{"en":"Eight senses run from a movement to a mood: the classical revival, the period it named, its national branches and later echoes, the style it left, and the private second spring the word now also serves.","cn":"八个义项从一场运动走到一种心境：古典复兴、它命名的时期、它在各国的分支与后世回声、它留下的风格，以及这个词如今也承担的私人第二春。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unfinished dome whose scaffolding holds measuring lines and fragments of an ancient column.","cn":"核心意象：一座未完工的圆顶，脚手架上放着测绳与古柱残段。"},"chain":["REBIRTH","CLASSICAL REVIVAL","ITALIAN PHASE","NATIONAL BRANCHES","PERIOD STYLE","LATER REVIVAL"],"branches":[{"senses":"S1 · S2","en":"MOVEMENT AND DATE: the revival first, then the era named after it, as a cultural label turns into a calendar entry.","cn":"运动与年代：先是复兴，再是以它命名的时期，文化标签由此变成日历上的一格。"},{"senses":"S3","en":"NATIONAL BRANCH: the same movement arrives at different times in different countries, so the label gains a place name.","cn":"国别分支：同一运动在不同国家抵达时间不同，标签于是加上地名。"},{"senses":"S4 · S5","en":"ECHO AND METAPHOR: later flowerings borrow the name, and finally any renewal does.","cn":"回声与比喻：后世的文化繁荣借用这个名字，最后任何回潮都借用它。"},{"senses":"S6 · S7","en":"STYLE: painting, sculpture and building carry the name most easily, and the noun works as a modifier without change.","cn":"风格：绘画、雕塑与建筑最容易带着这个名字，名词不加变化就能作修饰语。"},{"senses":"S8","en":"PRIVATE REBIRTH: the grand historical metaphor is lent to one person's late flowering.","cn":"私人重生：宏大的历史比喻被借给一个人的晚年勃发。"}]},"affixes":{"intro":{"en":"Renaissance is a French noun resting on a Latin verb of birth, and the same pieces build several English words about beginnings.","cn":"Renaissance 是一个法语名词，其底是拉丁的「出生」动词，同样的部件构成若干关于开端的英语词。"},"latinIntro":{"en":"Latin nasci 'to be born' gives natal, native and nascent, and renasci 'to be born again' stands behind the French word.","cn":"拉丁 nasci「出生」给出 natal、native、nascent；renasci「重新出生」则是这个法语词的底子。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'again, back')","meaning":"again","meaningCN":"再次；返回","example":"The prefix marks a second beginning.","exampleCN":"这个前缀标出第二次开端。"},{"word":"naiss-","structure":"nasci (Latin deponent verb, 'to be born')","meaning":"to be born","meaningCN":"出生","example":"The root carries the idea of birth.","exampleCN":"这个词根带着「出生」的意思。"},{"word":"-ance","structure":"-ance from Latin -antia","meaning":"noun suffix for a state or act","meaningCN":"表状态或动作的名词后缀","example":"The suffix turns the verb into a noun of event.","exampleCN":"这个后缀把动词变成事件名词。"},{"word":"Renaissance","structure":"re- + naissance","meaning":"the rebirth of classical culture","meaningCN":"文艺复兴","example":"The Renaissance began in the Italian city-states.","exampleCN":"文艺复兴始于意大利的城邦。"},{"word":"renaissance","structure":"lowercase use of the same noun","meaning":"any vigorous revival","meaningCN":"复兴；再生","example":"The neighbourhood is enjoying a renaissance.","exampleCN":"这个街区正经历一场复兴。"},{"word":"renascence","structure":"re- + nascence","meaning":"a rebirth","meaningCN":"再生；复兴","example":"The renascence of the harbour began with a bridge.","exampleCN":"这座港口的再生从一座桥开始。"},{"word":"renascent","structure":"renascence + -ent","meaning":"coming back to life","meaningCN":"正在复兴的","example":"A renascent mill town opened its first gallery.","exampleCN":"一座正在复兴的磨坊镇开了第一家画廊。"},{"word":"natal","structure":"nasci + -alis","meaning":"relating to birth","meaningCN":"出生的；分娩的","example":"The hospital keeps a natal ward on the ground floor.","exampleCN":"这家医院在一层设有产科病房。"},{"word":"native","structure":"nasci + -ivus","meaning":"belonging by birth","meaningCN":"出生地的；本地的","example":"The plant is native to the river valley.","exampleCN":"这种植物原生于这条河谷。"}],"latinEntries":[{"word":"nasci","structure":"nasci, natus sum (deponent verb)","meaning":"to be born","meaningCN":"出生"},{"word":"renasci","structure":"renasci, renatus sum (deponent verb)","meaning":"to be born again","meaningCN":"重新出生；再生"},{"word":"nativus","structure":"nativus, nativa, nativum (adjective)","meaning":"born, natural","meaningCN":"天生的；自然的"}]}},{"word":"reformation","ipa_uk":"/ˌrefəˈmeɪʃn/","ipa_us":"/ˌrefərˈmeɪʃn/","definition_zh":"改革；改良；宗教改革；（宗教改革形成的）新教运动","definition_en":"the act or result of reforming something, especially the sixteenth-century movement that reshaped Western Christianity","core_image":"教堂大门上钉着一张列满条目的纸，门内是正被搬走的旧雕像，墙面重新刷成白色","scene":"十六世纪的印书坊里，刚装订好的小册子被一摞摞搬上马车，铅字盘还摊在案上。Printing spread the reformation faster than any council could answer it.","sceneCN":"这里 reformation 指「十六世纪席卷西欧的宗教改革运动」（第 3 个义项：宗教改革这一历史事件）；句意为印刷术让宗教改革的传播快过任何一次宗教会议的回应。场景物件：小册子、铅字盘、马车、装订台。","pos":[{"tag":"n.","zh":"改革；改良；宗教改革"}],"collocations":[{"phrase":"the Protestant Reformation","zh":"新教宗教改革"},{"phrase":"the Catholic Reformation","zh":"天主教改革"},{"phrase":"reformation of the tax system","zh":"税制改革"},{"phrase":"church reformation","zh":"教会改革"},{"phrase":"social reformation","zh":"社会改良"},{"phrase":"reformation of spelling","zh":"拼写改革"}],"forms":[{"label":"复数","form":"reformations"},{"label":"动词","form":"reform"},{"label":"指人的名词","form":"reformer"},{"label":"形容词","form":"reformative"},{"label":"大写专名","form":"the Reformation"}],"derivatives":[{"word":"reform","pos":"v./n.","zh":"改革；改良"},{"word":"reformer","pos":"n.","zh":"改革者"},{"word":"reformative","pos":"adj.","zh":"起改良作用的"},{"word":"reformatory","pos":"adj./n.","zh":"改造的 / 感化院"},{"word":"reformed","pos":"adj.","zh":"改革过的；归正的"}],"senses":[{"no":"01","title":"The act of reforming something","titleCN":"改革、改良的行为","definition":"the process of changing a system, institution or practice for the better","definitionCN":"把制度、机构或做法朝更好方向改变的过程","example":"The reformation of the tax code took three committees and two years.","exampleCN":"税则的改革用了三个委员会和两年时间。","why":"reformatio is simply the noun of action from reformare 'to reshape', so any reshaping can carry the word.","whyCN":"reformatio 只是 reformare「重新塑形」的动作名词，因此任何重塑都能用这个词。"},{"no":"02","title":"The improved state produced","titleCN":"改革后的状态、改良结果","definition":"the better condition that results from reform, seen as an outcome rather than a process","definitionCN":"改革带来的较好状态，被看作结果而非过程","example":"The reformation of the prison was visible in its workshops, not its rules.","exampleCN":"监狱的改良体现在车间里，而不在条文里。","why":"Latin nouns in -tio name both the doing and the thing done, and English kept that double face.","whyCN":"拉丁 -tio 名词同时指动作与所做之事，英语保留了这个双面性。"},{"no":"03","title":"The sixteenth-century Protestant movement","titleCN":"十六世纪新教宗教改革","definition":"the movement that broke with the papacy and reshaped Western Christianity from 1517 onward","definitionCN":"自 1517 年起与教廷决裂并重塑西欧基督教世界的运动","example":"Printing spread the reformation faster than any council could answer it.","exampleCN":"印刷术让宗教改革的传播快过任何一次宗教会议的回应。","why":"a general noun was captured by one event, and the capitalised form now names that event alone.","whyCN":"一个普通名词被一次事件占据，大写形式如今只指那次事件。"},{"no":"04","title":"A wider religious reform movement","titleCN":"更广泛的宗教改革运动","definition":"any organised drive to correct doctrine or discipline within a church, before or after the sixteenth century","definitionCN":"十六世纪前后教会内部任何有组织的教义或纪律整顿","example":"The Gregorian reformation tightened rules on simony long before Luther.","exampleCN":"格里高利改革在路德之前很久就收紧了买卖圣职的规定。","why":"historians needed the general sense to describe earlier reforms, so the same word serves several centuries.","whyCN":"史家需要这层通义来描述更早的改革，同一个词于是服务好几个世纪。"},{"no":"05","title":"Correction of a person's conduct","titleCN":"对人的行为矫正、感化","definition":"the correction and retraining of an offender's habits, as in penal practice","definitionCN":"对犯错者习惯的矫正与再训，如刑罚实践中的做法","example":"The judge sent him to a house of reformation rather than a prison.","exampleCN":"法官把他送进感化院，而不是监狱。","why":"moral reshaping was part of the word from the start, and the prison system gave it an institution.","whyCN":"道德上的重塑从一开始就在这个词里，监狱制度又给了它一个机构。"},{"no":"06","title":"Reform of an institution's rules","titleCN":"机构规章的改革","definition":"the revision of written rules, often in a university, army or religious order","definitionCN":"对成文规章的修订，常见于大学、军队或修会","example":"The abbey's reformation of its rule cut the hours of manual work.","exampleCN":"这座修道院对会规的改革削减了手工劳作的时间。","why":"the word prefers institutions with written constitutions, because reshaping needs a text to reshape.","whyCN":"这个词偏爱有成文宪章的制度，因为要重塑就得有文本可塑。"},{"no":"07","title":"Used as a period label","titleCN":"定语用法：宗教改革时期的","definition":"placed before a noun to mark something belonging to the Reformation era","definitionCN":"置于名词前，标出某物属于宗教改革时代","example":"Reformation theology put grace before merit and the sermon before the Mass.","exampleCN":"宗教改革时期的神学把恩典放在功德之前，把讲道放在弥撒之前。","why":"English uses event names as modifiers, so an adjective is not needed to date a doctrine.","whyCN":"英语把事件名直接作修饰语，因此无需形容词就能给教义标年代。"},{"no":"08","title":"Reform of spelling or writing","titleCN":"拼写或文字的改革","definition":"a deliberate change to the spelling or script of a language","definitionCN":"对一种语言的拼法或文字所作的有意改变","example":"The reformation of Turkish spelling replaced Arabic letters with Latin ones in 1928.","exampleCN":"土耳其的拼写改革在 1928 年用拉丁字母取代了阿拉伯字母。","why":"the general sense is productive, and language planners borrowed it for their own reshaping of texts.","whyCN":"通义具有能产性，语言规划者便借它来描述自己对文本的重塑。"}],"etymology":{"intro":{"en":"Reformation goes back to Latin reformatio, the noun of reformare 'to form again', and it entered English first as a general word for improvement.","cn":"reformation 上承拉丁 reformatio，是 reformare「重新塑形」的名词，进入英语时先指一般的改良。"},"items":[{"era":"LATIN REFORMARE","en":"reformare 'to form again, reshape' joins re- 'again' to formare 'to form', itself from forma 'shape'.","cn":"reformare「重新塑形」由 re-「再次」加 formare「成形」构成，后者出自 forma「形状」。"},{"era":"LATIN REFORMATIO","en":"reformatio meant 'a reforming, a restoration', used of bringing something back to its proper earlier state.","cn":"reformatio 意为「改革、复原」，用于把某物带回其原本恰当的状态。"},{"era":"ENGLISH GENERAL SENSE","en":"English reformation is recorded in the early fifteenth century as a plain noun for correction or improvement.","cn":"英语 reformation 在 15 世纪初已有记录，作为普通的「纠正、改良」名词。"},{"era":"CHURCH SENSE","en":"Through the fifteenth century the word was applied to calls for church reform, and after 1517 it named the movement itself.","cn":"整个 15 世纪这个词被用于呼求教会改革，1517 年之后则直接指那场运动。"},{"era":"CAPITALISATION","en":"Writers now capitalise Reformation for the historical event and keep the lowercase form for reform in general.","cn":"今人用大写 Reformation 指历史事件，小写形式留给一般意义的改革。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation is dated to the early fifteenth century, and the moment when the capitalised event sense settled differs from author to author.","cn":"来源不确定（首见年代）：英语最早书证定在 15 世纪初；大写事件义何时稳定下来，各家说法不一。"}]},"similar":{"note":{"en":"Group one holds words on the same formare stock; group two holds the rival religious and political labels.","cn":"第一组是同出 formare 词干的词；第二组是竞争性的宗教与政治标签。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reform","ipa":"/rɪˈfɔːm/","tag":"verb and general noun","definition":"The verb and the everyday noun of improvement, without the historical weight of the long form.","definitionCN":"动词与日常名词，指改良，没有长词形的历史分量。"},{"word":"formation","ipa":"/fɔːˈmeɪʃn/","tag":"a shaping, not a reshaping","definition":"From formare but with no re-, so it names the original making of something, such as a rock formation.","definitionCN":"同出 formare 却没有 re-，指某物最初的生成，如岩层。"},{"word":"information","ipa":"/ˌɪnfəˈmeɪʃn/","tag":"different prefix","definition":"From informare 'to give shape to the mind', and unrelated to correction of abuses.","definitionCN":"出自 informare「给心智赋形」，与矫正弊端无关。"},{"word":"deformation","ipa":"/ˌdiːfɔːˈmeɪʃn/","tag":"the reverse","definition":"The same root with de-, naming the loss or distortion of shape, the opposite of reform.","definitionCN":"同一词根加 de-，指形状的丧失或扭曲，与改革相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"revolution","ipa":"/ˌrevəˈluːʃn/","tag":"wholesale overthrow","definition":"A change that replaces the whole order, usually by force; reform works inside the existing frame.","definitionCN":"以整体取代旧秩序的变化，常伴武力；改革则在既有框架内进行。"},{"word":"renewal","ipa":"/rɪˈnjuːəl/","tag":"fresh vigour","definition":"A return of vitality rather than a change of rules, often used of cities or faith.","definitionCN":"指活力的恢复而非规则的改变，常用于城市或信仰。"},{"word":"correction","ipa":"/kəˈrekʃn/","tag":"fixing an error","definition":"A narrower word for setting right a specific mistake, with no program of change.","definitionCN":"较窄的词，指改正具体错误，不含整套变革纲领。"},{"word":"Counter-Reformation","ipa":"/ˌkaʊntə ˌrefəˈmeɪʃn/","tag":"the Catholic answer","definition":"The Catholic response to the Protestant movement, built from the same noun with a prefix of opposition.","definitionCN":"天主教对新教运动的回应，由同一名词加表对抗的前缀构成。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin verb, a real suffix and real historical labels.","cn":"正常联想：真实的拉丁动词、真实的后缀与真实的历史标签。"},"normal":[{"en":"re- 'again' + formare 'to shape' = to shape again, hence to reform.","cn":"re-「再次」+ formare「塑形」= 重新塑形，也就是改革。"},{"en":"forma 'shape' also gives form, formal, formation and formula.","cn":"forma「形状」还给出 form、formal、formation、formula。"},{"en":"Capital R marks the event, lowercase r marks the process: the Reformation versus a reformation of taxes.","cn":"大写 R 标事件，小写 r 标过程：宗教改革对税制改革。"},{"en":"The date to hold is 1517, when the Ninety-Five Theses were printed and copied across Europe.","cn":"要记住的年代是 1517 年，九十五条论纲被印出并传抄欧洲。"},{"en":"Church, prison and spelling all take the word: each is a reshaping of an inherited text or habit.","cn":"教会、监狱与拼写都能用这个词：三者都是对继承来的文本或习惯的重塑。"}],"abstract":[{"en":"Picture a sheet of grievances nailed to a door, still wet from the press.","cn":"想象一张刚下印刷机的诉状被钉在门上。"},{"en":"Picture a statue carried out of a church while whitewash goes on the wall.","cn":"想象一尊雕像被搬出教堂，白灰正刷上墙。"},{"en":"Picture a spelling book where every old letter has been crossed out.","cn":"想象一本拼写课本，每个旧字母都被划掉。"}]},"examples":[{"en":"The reformation of the civil service began with open examinations.","cn":"文官制度的改革从公开考试开始。"},{"en":"Historians date the Reformation from the printing of the theses in 1517.","cn":"史家把宗教改革定在 1517 年论纲付印之时。"},{"en":"The abbey's reformation of its rule shortened the daily offices.","cn":"修道院对会规的改革缩短了每日的礼拜。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞佛美申」听似「再佛一美」——把旧样子重新塑一遍 → 改革、宗教改革","word":"reformation"},"root":"拉丁 reformatio「改革、复原」= re-「再次」+ formare「塑形」（出自 forma「形状」）+ -tio 动作名词后缀。","sensesIntro":{"en":"Eight senses share one gesture, shaping something again: an act, its result, the great religious reshaping, earlier church reforms, correction of persons, revision of rules, a period label, and even a spelling system.","cn":"八个义项共享同一个动作——把某物重新塑一遍：行为、结果、那场宗教大重塑、更早的教会整顿、对人的矫正、规章的修订、时期标签，乃至一套拼写制度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a list nailed to a church door while old statues leave and the walls are whitewashed.","cn":"核心意象：一张纸钉在教堂门上，旧雕像正被搬走，墙面重新刷白。"},"chain":["RESHAPE","IMPROVED STATE","CHURCH REFORM","PROTESTANT BREAK","CORRECT CONDUCT","REVISE RULES"],"branches":[{"senses":"S1 · S2","en":"ACT AND RESULT: the same -tio noun names the doing and the better state left behind.","cn":"动作与结果：同一个名词既指做的过程，也指留下的较好状态。"},{"senses":"S3 · S4","en":"CHURCH: one event captured the word, yet the general sense still covers earlier reforms.","cn":"教会：一次事件占住了这个词，通义却仍覆盖更早的改革。"},{"senses":"S5 · S6","en":"PERSONS AND RULES: moral correction of an offender and revision of a written constitution are both reshaping.","cn":"人与规章：对犯错者的道德矫正与对成文宪章的修订，都是重塑。"},{"senses":"S7","en":"PERIOD LABEL: the event name works as a modifier, so doctrines can be dated without an adjective.","cn":"时期标签：事件名可作修饰语，教义无需形容词就能标年代。"},{"senses":"S8","en":"TEXT: spelling reform carries the general sense into the alphabet itself.","cn":"文本：拼写改革把通义带进字母表本身。"}]},"affixes":{"intro":{"en":"Reformation is a Latin action noun whose pieces still build ordinary English words about shape.","cn":"reformation 是一个拉丁动作名词，它的各部件至今仍在构成关于「形状」的日常英语词。"},"latinIntro":{"en":"Latin forma 'shape' and formare 'to form' give form, formal, formation and reform; reformatio adds the action suffix.","cn":"拉丁 forma「形状」与 formare「成形」给出 form、formal、formation、reform；reformatio 又加上动作后缀。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'again')","meaning":"again, back","meaningCN":"再次；回","example":"The prefix marks a second shaping.","exampleCN":"这个前缀标出第二次塑形。"},{"word":"form-","structure":"forma (Latin noun, 'shape, mould')","meaning":"shape","meaningCN":"形状；模子","example":"The root supplies the mould in every member of the family.","exampleCN":"这个词根为整个词族提供「模子」的意思。"},{"word":"-ation","structure":"-atio, -ationis (Latin action suffix)","meaning":"the act or result of","meaningCN":"动作或结果","example":"The suffix turns a verb into a noun of process.","exampleCN":"这个后缀把动词变成过程名词。"},{"word":"reform","structure":"re- + formare","meaning":"to shape again, improve","meaningCN":"改革；改良","example":"The committee reformed the admissions rules.","exampleCN":"委员会改革了招生规则。"},{"word":"reformation","structure":"reform + -ation","meaning":"the act or result of reforming","meaningCN":"改革；宗教改革","example":"The reformation of the guild statutes took a year.","exampleCN":"行会章程的改革用了一年。"},{"word":"reformer","structure":"reform + -er","meaning":"one who reforms","meaningCN":"改革者","example":"The reformer attacked the sale of offices.","exampleCN":"这位改革者抨击卖官。"},{"word":"reformative","structure":"reform + -ative","meaning":"tending to reform","meaningCN":"起改良作用的","example":"The measure had a reformative aim but a weak text.","exampleCN":"这项措施目的在改良，条文却很弱。"},{"word":"reformatory","structure":"reform + -atory","meaning":"intended to correct conduct","meaningCN":"改造的；感化性的","example":"The reformatory school taught trades.","exampleCN":"感化学校教授手艺。"},{"word":"formation","structure":"formare + -ation","meaning":"a shaping or arrangement","meaningCN":"形成；构造","example":"The rock formation runs along the coast.","exampleCN":"这道岩层沿着海岸延伸。"},{"word":"form","structure":"forma through Old French","meaning":"shape or established procedure","meaningCN":"形状；形式；表格","example":"The form of the argument matters as much as its content.","exampleCN":"论证的形式与内容同样重要。"}],"latinEntries":[{"word":"forma","structure":"forma, formae (f., first declension)","meaning":"shape, form, mould","meaningCN":"形状；形式；模子"},{"word":"formare","structure":"formare, formavi, formatum (verb, first conjugation)","meaning":"to form, shape","meaningCN":"使成形；塑造"},{"word":"reformare","structure":"reformare, reformavi, reformatum (verb, first conjugation)","meaning":"to form again, restore","meaningCN":"重新塑形；恢复"},{"word":"reformatio","structure":"reformatio, reformationis (f., third declension)","meaning":"a reforming, restoration","meaningCN":"改革；复原"}]}},{"word":"rebellion","ipa_uk":"/rɪˈbeljən/","ipa_us":"/rɪˈbeljən/","definition_zh":"叛乱；起义；反抗；叛逆","definition_en":"an organised attempt to overthrow a government by force, or any refusal to obey an authority","core_image":"黄昏的城门口，人群把旗子倒举，门内守军列队，墙上贴着刚刷上去的通告，纸角还在风里翻","scene":"黄昏的城门前，人群把旗子倒过来举着，门内守军排成队列。The rebellion began when troops refused to fire on the crowd.","sceneCN":"这里 rebellion 指「以武力对抗当权者的有组织起事」（第 1 个义项：武装叛乱）；句意为这场叛乱始于军队拒绝向人群开枪。场景物件：倒举的旗、紧闭的城门、通告纸、列队的士兵。","pos":[{"tag":"n.","zh":"叛乱；起义；反抗；叛逆"}],"collocations":[{"phrase":"armed rebellion","zh":"武装叛乱"},{"phrase":"crush a rebellion","zh":"镇压叛乱"},{"phrase":"rebellion against the crown","zh":"对王权的反叛"},{"phrase":"open rebellion","zh":"公开反叛"},{"phrase":"a rebellion breaks out","zh":"叛乱爆发"},{"phrase":"teenage rebellion","zh":"青少年的叛逆"}],"forms":[{"label":"复数","form":"rebellions"},{"label":"动词","form":"rebel"},{"label":"指人的名词","form":"rebel"},{"label":"形容词","form":"rebellious"},{"label":"副词","form":"rebelliously"}],"derivatives":[{"word":"rebel","pos":"n./v.","zh":"反叛者 / 反叛"},{"word":"rebellious","pos":"adj.","zh":"叛逆的；难驾驭的"},{"word":"rebelliously","pos":"adv.","zh":"叛逆地"},{"word":"rebelliousness","pos":"n.","zh":"叛逆性"},{"word":"rebeldom","pos":"n.","zh":"反叛者群体（旧用）"}],"senses":[{"no":"01","title":"An armed rising against a government","titleCN":"武装叛乱、起义","definition":"an organised attempt by a group to overthrow or resist a government by force","definitionCN":"一群人试图以武力推翻或抵抗政府的组织化行动","example":"The rebellion began when troops refused to fire on the crowd.","exampleCN":"这场叛乱始于军队拒绝向人群开枪。","why":"rebellare means 'to renew war', so the word's core is a second war inside the state.","whyCN":"rebellare 意为「重新开战」，所以这个词的核心是国家内部再打一场战争。"},{"no":"02","title":"Refusal to obey an authority","titleCN":"对权威的抗拒","definition":"a general stance of refusing orders from those in power, with or without weapons","definitionCN":"对当权者命令的普遍抗拒，无论是否动武","example":"Submission came slowly, and rebellion against the new tax smouldered for years.","exampleCN":"顺从来得缓慢，对新税的反抗闷烧了好几年。","why":"the armed sense is only the loudest form of the same refusal, so the word can drop the guns and keep the attitude.","whyCN":"武装只是同一种抗拒里最响的形式，因此这个词可以放下枪而保留态度。"},{"no":"03","title":"Defiance of social norms","titleCN":"对社会规范的反叛","definition":"a young person's or artist's rejection of expected behaviour and dress","definitionCN":"年轻人或艺术家对预期行为与衣着规范的拒绝","example":"Her rebellion was a short haircut and a motorcycle in a town of hats.","exampleCN":"她的叛逆是一头短发和一辆摩托，落在一座人人戴帽的小镇里。","why":"the political word migrated to private life in the twentieth century, where the enemy is convention rather than a crown.","whyCN":"这个政治词在 20 世纪移入私人生活，敌人从王冠变成了习俗。"},{"no":"04","title":"Mutiny of troops or sailors","titleCN":"军队或船员的哗变","definition":"a revolt within an armed force against its own officers","definitionCN":"武装力量内部对其军官的起事","example":"A rebellion in the ranks cost the general two regiments before dawn.","exampleCN":"队伍里的哗变让将军在天亮前损失了两个团。","why":"inside an army the same act is still called a rebellion, though a navy may prefer mutiny.","whyCN":"在军队内部同一种行为仍叫 rebellion，海军则更常用 mutiny。"},{"no":"05","title":"A named historical uprising","titleCN":"有专名的历史起事","definition":"a specific rising known by a name and a date in the history books","definitionCN":"史书以名号与年代记载的具体起事","example":"Shays' Rebellion showed how weak the articles of confederation were.","exampleCN":"谢斯起义暴露了邦联条例的虚弱。","why":"historians turn events into proper names, and the common noun becomes a chapter heading.","whyCN":"史家把事件变成专名，普通名词于是成了章节标题。"},{"no":"06","title":"Inner resistance to one's own feelings","titleCN":"内心的抗拒情绪","definition":"the emotional refusal of a person to accept a fact, a rule or a role","definitionCN":"个人对某个事实、规则或角色的情感性拒绝","example":"His rebellion against the diagnosis lasted longer than the treatment.","exampleCN":"他对诊断的抗拒比对治疗坚持得更久。","why":"the metaphor moves inward: the self becomes both ruler and subject, and the refusal is staged inside one head.","whyCN":"比喻转向内部：自我既是统治者又是臣民，抗拒在一个脑袋里上演。"},{"no":"07","title":"A revolt of subordinates within an institution","titleCN":"机构内部下级对上级的反抗","definition":"a refusal by members of an organisation to accept its leadership or a decision","definitionCN":"组织成员拒绝接受其领导或某项决定","example":"A backbench rebellion forced the leader to withdraw the bill.","exampleCN":"后座议员的反抗迫使领袖撤回议案。","why":"the word is native to party and committee politics, where no shots are fired but votes are counted.","whyCN":"这个词在政党与委员会政治里很自然：没有枪声，只有计票。"},{"no":"08","title":"Cultural revolt against tradition","titleCN":"文化与艺术上对传统的反叛","definition":"a movement in art or thought that rejects inherited forms on purpose","definitionCN":"艺术或思想上刻意拒绝继承形式的风潮","example":"The rebellion against classical symmetry produced buildings that lean and crack.","exampleCN":"对古典对称的反叛造出了倾斜开裂的房子。","why":"the last extension drops the state entirely and keeps only the gesture of refusing an inherited order.","whyCN":"最后一层扩展完全放下国家，只留下拒绝继承秩序的姿势。"}],"etymology":{"intro":{"en":"Rebellion came through Old French from Latin rebellio, the noun of rebellare 'to wage war again', built on bellum 'war'.","cn":"rebellion 经古法语来自拉丁 rebellio，是 rebellare「重新开战」的名词，基础是 bellum「战争」。"},"items":[{"era":"LATIN BELLUM","en":"Bellum 'war' is the base of rebellare. Its deeper origin is disputed; it may be a back-formation from duellum, and older forms are reconstructed.","cn":"bellum「战争」是 rebellare 的基础。它更深的来源有争议，可能由 duellum 逆构而成，更早的形式属重构。"},{"era":"LATIN REBELLARE","en":"re- 'again' plus bellare 'to wage war' gave rebellare 'to renew war, to revolt'.","cn":"re-「再次」加 bellare「作战」构成 rebellare「重新开战、反叛」。"},{"era":"OLD FRENCH","en":"Old French rebellion carried the word into English in the fourteenth century, first naming the state of being a rebel.","cn":"古法语 rebellion 在 14 世纪把这个词带入英语，最初指「身为反叛者」的状态。"},{"era":"STATE TO EVENT","en":"By the sixteenth century the sense had moved from a condition to an organised event with leaders and dates.","cn":"到 16 世纪，词义从一种状态转为有领袖、有年代的组织化事件。"},{"era":"WIDENING","en":"Later the word spread to any defiance, from a teenager's rebellion to a rebellion against convention.","cn":"后来它扩展到任何抗拒，从青少年的叛逆到对习俗的反叛。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of bellum is unresolved, and any Indo-European root proposed for it is a reconstruction.","cn":"来源不确定（更深词源）：bellum 在拉丁语之前的来源没有定论，凡为其提出的印欧词根均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words on the same bellum stock plus two dangerous look-alikes; group two holds the rival names for risings.","cn":"第一组是同出 bellum 词干的词与两个易混形近词；第二组是各类起事的竞争性名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rebel","ipa":"/ˈrebl/","tag":"person or verb","definition":"The person who rises, or the act of rising; the long noun names the event, the short one names the actor.","definitionCN":"指起事的人或起事这一动作；长词指事件，短词指人。"},{"word":"rebellious","ipa":"/rɪˈbeljəs/","tag":"the adjective","definition":"Describes a person or mood that resists authority, without naming an organised event.","definitionCN":"形容抗拒权威的人或情绪，不指组织化事件。"},{"word":"revel","ipa":"/ˈrevl/","tag":"different root","definition":"To make merry, from Latin revelare 'to unveil'; it looks close but shares no root with rebellion.","definitionCN":"意为狂欢，出自拉丁 revelare「揭开」；形近却与 rebellion 无词根关系。"},{"word":"bellicose","ipa":"/ˈbelɪkəʊs/","tag":"same root, no re-","definition":"From bellum 'war' plus -icose, meaning 'eager to fight'; it describes a temper, not an uprising.","definitionCN":"由 bellum「战争」加 -icose 构成，意为「好战的」，形容性情而非起事。"}]},{"heading":"NEAR MEANING","entries":[{"word":"revolt","ipa":"/rɪˈvəʊlt/","tag":"the turning away","definition":"Often the first movement of refusal, and also a verb meaning to disgust; it stresses the act of turning.","definitionCN":"常指最初的转身拒绝，也作动词表示使人反感；强调「转身」这一动作。"},{"word":"uprising","ipa":"/ˈʌpraɪzɪŋ/","tag":"short and local","definition":"A popular rising, usually spontaneous and short; rebellion suggests more organisation and duration.","definitionCN":"指民众起事，多为自发且短暂；rebellion 则暗示更多组织与更长时间。"},{"word":"insurrection","ipa":"/ˌɪnsəˈrekʃn/","tag":"formal and legal","definition":"The legal and official word for a rising against the state, used in statutes and charges.","definitionCN":"对国家起事的法律与官方用词，见于法规与控罪。"},{"word":"mutiny","ipa":"/ˈmjuːtəni/","tag":"against officers","definition":"A revolt inside an armed force against its own commanders, narrower than rebellion.","definitionCN":"武装力量内部针对自己指挥官的起事，比 rebellion 窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin root, real cognates and real historical names.","cn":"正常联想：真实的拉丁词根、真实的同源词与真实的历史事件名。"},"normal":[{"en":"re- 'again' + bellum 'war' = war again, this time inside the state.","cn":"re-「再次」+ bellum「战争」= 再打一场仗，这次在国家内部。"},{"en":"bellum also gives bellicose and belligerent, both about waging war.","cn":"bellum 还给出 bellicose 与 belligerent，都与作战有关。"},{"en":"The family runs rebel, rebellion, rebellious, rebelliously, rebelliousness.","cn":"同族词包括 rebel、rebellion、rebellious、rebelliously、rebelliousness。"},{"en":"Collocations mark the scale: armed rebellion, open rebellion, crush a rebellion.","cn":"搭配标出规模：武装叛乱、公开反叛、镇压叛乱。"},{"en":"History supplies proper names: Shays' Rebellion, the Jacobite Rebellions.","cn":"历史提供专名：谢斯起义、詹姆斯党叛乱。"}],"abstract":[{"en":"Picture a banner held upside down at a city gate.","cn":"想象城门下一面被倒举的旗。"},{"en":"Picture a door barred from the inside while a crowd fills the street.","cn":"想象门从里面被闩上，人群却已挤满街道。"},{"en":"Picture a teenager's short hair cutting through a town of hats.","cn":"想象一头短发穿过一座人人戴帽的小镇。"}]},"examples":[{"en":"The rebellion lasted a season and changed a dynasty's tax policy for a century.","cn":"这场叛乱只持续一季，却改了一个王朝百年的税政。"},{"en":"His rebellion against the new rules was silent but complete.","cn":"他对新规的反叛是沉默的，却是彻底的。"},{"en":"Teachers read teenage rebellion as a sign of growing independence.","cn":"教师把青少年的叛逆看作独立性生长的迹象。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞拜林」听似「再背犁」——被压得再背一遍犁的人转身举旗 → 叛乱、反抗","word":"rebellion"},"root":"拉丁 rebellio「反叛」= re-「再次」+ bellare「作战」（出自 bellum「战争」）+ -io 名词后缀；bellum 的更深来源不确定。","sensesIntro":{"en":"Eight senses run from an army to an attitude: an armed rising, plain refusal of authority, social defiance, mutiny, a named event, inner resistance, a party revolt and a cultural break with tradition.","cn":"八个义项从军队走到态度：武装起事、对权威的单纯拒绝、社会性叛逆、军中哗变、有专名的事件、内心抗拒、党内倒戈，以及对传统的文化决裂。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crowd holding a banner upside down before a shut city gate.","cn":"核心意象：紧闭的城门前，人群把旗子倒举。"},"chain":["TAKE UP ARMS","REFUSE OBEDIENCE","DEFY NORMS","MUTINY","INNER RESISTANCE","CULTURAL REVOLT"],"branches":[{"senses":"S1 · S5","en":"ARMED EVENT: the general rising and the named historical case are the same act seen twice, once as a category and once as a chapter.","cn":"武装事件：泛指的起事与有专名的历史个案是同一行为的两种看法，一为类别，一为章节。"},{"senses":"S2 · S7","en":"REFUSAL OF AUTHORITY: whether the authority is a state or a party leader, the gesture is the same.","cn":"拒绝权威：无论权威是国家还是党内领袖，姿势相同。"},{"senses":"S3 · S8","en":"DEFIANCE OF FORM: social and artistic rebellion both attack inherited rules rather than a ruler.","cn":"对形式的叛逆：社会叛逆与艺术叛逆都攻击继承的规则，而非某位统治者。"},{"senses":"S4","en":"MUTINY: inside an armed force the same refusal turns against its own officers.","cn":"哗变：在武装力量内部，同一种拒绝转向自己的军官。"},{"senses":"S6","en":"INNER RESISTANCE: the metaphor moves inside one head, where the self is both ruler and subject.","cn":"内心抗拒：比喻移进一个脑袋，自我既是统治者又是臣民。"}]},"affixes":{"intro":{"en":"Rebellion is a Latin noun of action from a verb of war, and both the prefix and the root build other English words.","cn":"rebellion 是拉丁「战争」动词的动作名词，前缀与词根都在构成别的英语词。"},"latinIntro":{"en":"Latin bellum 'war' yields bellicose and belligerent, while rebellare adds re- 'again' and gives rebel and rebellion.","cn":"拉丁 bellum「战争」衍生 bellicose 与 belligerent；rebellare 加上 re-「再次」，给出 rebel 与 rebellion。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'again')","meaning":"again","meaningCN":"再次","example":"The prefix turns war into renewed war.","exampleCN":"这个前缀把战争变成再起的战争。"},{"word":"bell-","structure":"bellum (Latin noun, 'war')","meaning":"war","meaningCN":"战争","example":"The root supplies the martial core of the word.","exampleCN":"这个词根提供这个词的武力内核。"},{"word":"-ion","structure":"-io, -ionis (Latin noun suffix)","meaning":"act or state","meaningCN":"动作或状态","example":"The suffix makes an event noun from the verb.","exampleCN":"这个后缀把动词变成事件名词。"},{"word":"rebel","structure":"re- + bellare","meaning":"to renew war, rise against","meaningCN":"反叛；起事","example":"The northern provinces rebelled twice.","exampleCN":"北方各省两次反叛。"},{"word":"rebellion","structure":"rebel + -ion","meaning":"an organised rising","meaningCN":"叛乱；起义","example":"The rebellion was over before the harvest.","exampleCN":"叛乱在收获前就结束了。"},{"word":"rebellious","structure":"rebellion + -ous","meaning":"given to resisting","meaningCN":"叛逆的","example":"The rebellious district ignored three edicts.","exampleCN":"这个叛逆的地区无视了三道敕令。"},{"word":"rebelliously","structure":"rebellious + -ly","meaning":"in a resisting manner","meaningCN":"叛逆地","example":"He answered rebelliously and left the room.","exampleCN":"他叛逆地回了一句就离开了房间。"},{"word":"bellicose","structure":"bellum + -icose","meaning":"eager for war","meaningCN":"好战的","example":"The bellicose speech promised a short campaign.","exampleCN":"那篇好战演说许诺一场短战役。"},{"word":"belligerent","structure":"bellum + -gerent","meaning":"waging war","meaningCN":"交战的；好斗的","example":"Both belligerent states claimed the river.","exampleCN":"两个交战国都声称拥有这条河。"}],"latinEntries":[{"word":"bellum","structure":"bellum, belli (n., second declension)","meaning":"war","meaningCN":"战争"},{"word":"bellare","structure":"bellare, bellavi, bellatum (verb, first conjugation)","meaning":"to wage war","meaningCN":"作战"},{"word":"rebellare","structure":"rebellare, rebellavi, rebellatum (verb, first conjugation)","meaning":"to renew war, revolt","meaningCN":"重新开战；反叛"},{"word":"rebellio","structure":"rebellio, rebellionis (f., third declension)","meaning":"revolt, rebellion","meaningCN":"反叛；叛乱"}]}},{"word":"revolt","ipa_uk":"/rɪˈvəʊlt/","ipa_us":"/rɪˈvoʊlt/","definition_zh":"起义；反叛；使反感；厌恶；反胃","definition_en":"to rise against a ruler or authority, or to cause and feel strong disgust","core_image":"一只手掌把桌上的契约推开，另一只手已把椅子带翻，屋外的队伍正涌向广场","scene":"集市十字柱上刚贴上新的税单，人群围拢，锄头与草叉被举起来。The peasants revolted after the new tax was posted at the market cross.","sceneCN":"这里 revolt 指「起而反抗统治者」（第 1 个义项：发动起义）；句意为新税单贴在集市十字柱后，农民们起事了。场景物件：税单、十字柱、草叉、围拢的人群。","pos":[{"tag":"v.","zh":"起义；反叛；使反感；感到厌恶"},{"tag":"n.","zh":"起义；叛乱；反抗状态"}],"collocations":[{"phrase":"revolt against the government","zh":"反抗政府"},{"phrase":"rise in revolt","zh":"起而反叛"},{"phrase":"in revolt","zh":"处于反叛状态"},{"phrase":"peasant revolt","zh":"农民起义"},{"phrase":"revolt at the sight","zh":"见之生厌"},{"phrase":"a revolting smell","zh":"令人作呕的气味"}],"forms":[{"label":"三单","form":"revolts"},{"label":"过去式","form":"revolted"},{"label":"过去分词","form":"revolted"},{"label":"现在分词","form":"revolting"},{"label":"名词复数","form":"revolts"},{"label":"形容词","form":"revolting"}],"derivatives":[{"word":"revolting","pos":"adj.","zh":"令人反感的；作呕的"},{"word":"revolted","pos":"adj.","zh":"反叛的；感到厌恶的"},{"word":"revolution","pos":"n.","zh":"革命；旋转"},{"word":"revolve","pos":"v.","zh":"旋转；围绕"}],"senses":[{"no":"01","title":"To rise against a ruler","titleCN":"起而反抗统治者","definition":"to take up resistance against a government or ruler, often with force","definitionCN":"对政府或统治者采取抵抗，常伴武力","example":"The peasants revolted after the new tax was posted at the market cross.","exampleCN":"新税单贴在集市十字柱后，农民们起事了。","why":"the Italian source means 'to turn back', and a subject who turns back on his ruler is exactly that image.","whyCN":"意大利语来源意为「转回去」，臣民转身背对君主，正是这幅图。"},{"no":"02","title":"To cause strong disgust","titleCN":"使感到强烈反感","definition":"to make someone feel shock and repulsion at something base or cruel","definitionCN":"使某人对卑劣或残酷之事感到震惊与排斥","example":"The conditions in the cellar revolted every inspector who saw them.","exampleCN":"地窖里的情形让每个见到的检查员都反感。","why":"the physical image of the stomach turning produced this transitive sense, where a sight acts on a person.","whyCN":"胃里翻腾这一身体图景产生了这个及物义：景象对人起作用。"},{"no":"03","title":"To feel disgust at something","titleCN":"对某事感到厌恶","definition":"to feel revulsion oneself, usually with at or against","definitionCN":"自己感到强烈排斥，常与 at 或 against 连用","example":"She revolted at the smell of the glue and left the workshop.","exampleCN":"她闻到胶水的气味就作呕，离开了作坊。","why":"the same image seen from inside: the person is the one whose stomach turns.","whyCN":"同一幅图从内部看：翻腾的是这个人自己的胃。"},{"no":"04","title":"A rising against a government","titleCN":"起义、叛乱（名词）","definition":"the event of rising against authority, often brief and unsuccessful","definitionCN":"对抗权威的起事，常较短暂且未成功","example":"The revolt was put down in a week, but its slogans lasted a generation.","exampleCN":"起义一周内被镇压，口号却传了一代。","why":"the noun is the event form of the verb, naming a single rising rather than a long rebellion.","whyCN":"名词是动词的事件形式，指一次起事，而非长期的叛乱。"},{"no":"05","title":"The state of being in resistance","titleCN":"处于反抗的状态","definition":"the condition of standing against authority, as in the phrase in revolt","definitionCN":"处于对抗权威的状态，见于 in revolt 这一短语","example":"The whole province was in revolt before the governor admitted the truth.","exampleCN":"总督承认真相之前，全省已处在反叛状态。","why":"English keeps the state sense in a fixed phrase, distinct from the countable event.","whyCN":"英语用固定短语保留状态义，与可数的单次事件区分。"},{"no":"06","title":"To refuse to accept an idea or practice","titleCN":"拒绝接受某种观念或做法","definition":"to reject a rule, belief or custom without taking up arms","definitionCN":"不诉诸武力而拒绝某项规则、信念或习俗","example":"He revolted against the idea that a career must be chosen at eighteen.","exampleCN":"他拒绝接受「十八岁就得选定职业」这一观念。","why":"once the object is an idea rather than a king, the verb becomes a matter of personal refusal.","whyCN":"当对象从君主变成观念，这个动词就成了个人拒绝的事。"},{"no":"07","title":"A vassal's renunciation of allegiance","titleCN":"臣属对君主的背弃","definition":"the act of withdrawing loyalty from a lord, an older and narrower legal sense","definitionCN":"撤回对领主的效忠，是较早且较窄的法律义","example":"The baron's revolt cost him his castles but not his name.","exampleCN":"这位男爵的背弃让他丢了城堡，却保住了名号。","why":"medieval law separated turning away from open war, and English kept a trace of that distinction.","whyCN":"中世纪法律把「转身离弃」与公开作战分开，英语仍留有一丝痕迹。"},{"no":"08","title":"Of the stomach: to turn, to feel nausea","titleCN":"胃里翻腾、作呕","definition":"to heave or turn, as the stomach does before vomiting","definitionCN":"像胃在呕吐前那样翻动、搅动","example":"The boat rolled once, and every stomach on board revolted.","exampleCN":"船晃了一下，船上每个人的胃都翻腾起来。","why":"this is the literal bodily image behind all the disgust senses, and English still uses it directly.","whyCN":"这是所有「厌恶」义背后的身体本图，英语至今仍直接使用。"}],"etymology":{"intro":{"en":"Revolt came through French from Italian rivoltare 'to turn back, overturn', which rests on Latin volvere 'to roll'.","cn":"revolt 经法语来自意大利语 rivoltare「转回、翻覆」，其底是拉丁 volvere「滚动」。"},"items":[{"era":"ITALIAN RIVOLTARE","en":"French révolter came from Italian rivoltare, 'to turn back, to overturn', a word of everyday motion before it was political.","cn":"法语 révolter 来自意大利语 rivoltare「转回、翻覆」，先是一个日常动作词，后来才政治化。"},{"era":"VULGAR LATIN","en":"The Italian verb rests on Vulgar Latin revolvitare, a frequentative of revolvere 'to roll back', from volvere 'to roll'.","cn":"这个意大利语动词的底是俗拉丁 revolvitare，即 revolvere「滚回」的反复动词，出自 volvere「滚动」。"},{"era":"POLITICAL SENSE","en":"The sense 'to cast off obedience' is recorded in the sixteenth century, first of subjects turning against a ruler.","cn":"「抛弃顺从」这一义在 16 世纪有记录，最初指臣民转而对君主不利。"},{"era":"DISGUST SENSE","en":"The sense 'to repel, to disgust' grew from the image of the stomach turning over and is recorded in the same century.","cn":"「使人排斥、厌恶」这一义由胃部翻腾的意象生长而来，也在同一世纪有记录。"},{"era":"NOUN USE","en":"The noun revolt followed the verb and now usually names a short, local or unsuccessful rising.","cn":"名词 revolt 随动词而来，如今多指短暂、局部或未成功的起事。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the route through French and Italian is not documented step by step, and the first date of the disgust sense is only approximate.","cn":"来源不确定（首见年代）：经法语与意大利语的传递过程没有逐步书证，厌恶义的最早年代也只能约略推定。"}]},"similar":{"note":{"en":"Group one holds words that look like revolt but come from other verbs; group two holds the rival names for risings and for disgust.","cn":"第一组是形似 revolt、实际出自别的动词的词；第二组是起事与厌恶的竞争性说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"revolve","ipa":"/rɪˈvɒlv/","tag":"same root, no re- of revolt","definition":"From Latin volvere 'to roll', meaning to turn around an axis; the shared root is real, the meaning is not political.","definitionCN":"出自拉丁 volvere「滚动」，意为绕轴旋转；词根确实相同，意义与政治无关。"},{"word":"revoke","ipa":"/rɪˈvəʊk/","tag":"different root","definition":"From re- plus vocare 'to call', meaning to cancel a grant or right; it looks close and shares no root.","definitionCN":"由 re- 加 vocare「呼叫」构成，意为撤销授予或权利；形近而无词根关系。"},{"word":"revolver","ipa":"/rɪˈvɒlvə/","tag":"named from revolving","definition":"The firearm is named for its revolving cylinder, not for revolt, though the two words sit one letter apart.","definitionCN":"这种枪因转轮而得名，与 revolt 无关，两个词只差一个字母。"},{"word":"revolt","ipa":"/rɪˈvəʊlt/","tag":"the headword itself","definition":"The noun and verb treated here; its noun plural revolts marks single events, not a condition.","definitionCN":"即本词条的名词与动词；其复数标单次事件，而非持续状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rebellion","ipa":"/rɪˈbeljən/","tag":"longer and more organised","definition":"Suggests planning and duration; a revolt may be a single sudden turning.","definitionCN":"暗示筹划与持续；revolt 可能只是一次突然的转身。"},{"word":"uprising","ipa":"/ˈʌpraɪzɪŋ/","tag":"popular and spontaneous","definition":"A rising of ordinary people, often local; revolt adds the sense of casting off allegiance.","definitionCN":"指普通民众的起事，常限于一地；revolt 另有「抛弃效忠」之意。"},{"word":"disgust","ipa":"/dɪsˈɡʌst/","tag":"plain word for revulsion","definition":"The everyday noun and verb for strong dislike; revolt is stronger and more literary in this sense.","definitionCN":"指强烈厌恶的日常名词与动词；此义上的 revolt 更强、更书面。"},{"word":"nauseate","ipa":"/ˈnɔːzieɪt/","tag":"physical revulsion","definition":"To make someone feel sick at the stomach, the bodily image that revolt also carries.","definitionCN":"使人胃里难受，正是 revolt 也带着的那幅身体图。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin verb of rolling, real relatives and real collocations.","cn":"正常联想：真实的拉丁「滚动」动词、真实同族词与真实搭配。"},"normal":[{"en":"re- 'back' + volvere 'to roll' = to roll back, to turn against.","cn":"re-「向后」+ volvere「滚动」= 滚回去、转而对抗。"},{"en":"The same volvere root appears in revolve, revolution and voluble is not related.","cn":"同一 volvere 词根见于 revolve、revolution；voluble 与之无关。"},{"en":"Two families share the spelling: political revolt and bodily revolting.","cn":"两组意思共用拼写：政治上的反叛与身体上的作呕。"},{"en":"Fixed phrases mark the grammar: revolt against, in revolt, rise in revolt.","cn":"固定搭配标出语法：反抗、处于反叛、起而反叛。"},{"en":"Keep revolt apart from revoke and revolver, which differ by one letter and by root.","cn":"把 revolt 与 revoke、revolver 分开，它们只差一个字母，词根也不同。"}],"abstract":[{"en":"Picture a chair knocked over as someone turns away from a signed paper.","cn":"想象有人转身离开一份签好的文件，椅子被带翻。"},{"en":"Picture milk turning sour in a cup held to the nose.","cn":"想象一杯牛奶凑到鼻前，已经变酸。"},{"en":"Picture a wave curling back on itself before it reaches the sand.","cn":"想象一道浪在触沙之前先卷了回去。"}]},"examples":[{"en":"The garrison revolted when its pay was three months late.","cn":"驻军因军饷拖欠三个月而哗变。"},{"en":"The idea of a fixed retirement age revolts many younger workers.","cn":"固定退休年龄这一观念让许多年轻劳动者反感。"},{"en":"The smell from the drain was enough to revolt a whole street.","cn":"下水道的气味足以让整条街的人作呕。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞沃特」听似「再卧倒」——不肯再卧倒的人翻身而起 → 起义；闻到恶心物也让人「翻身」→ 厌恶","word":"revolt"},"root":"经法语 révolter 来自意大利语 rivoltare「转回、翻覆」，其上为俗拉丁 revolvitare，是 revolvere「滚回」的反复动词，出自 volvere「滚动」。","sensesIntro":{"en":"Eight senses swing between politics and the body: turning against a ruler, causing and feeling disgust, the event noun, the state phrase, refusing an idea, renouncing a lord, and the stomach's own turning.","cn":"八个义项在政治与身体之间摆动：转身对抗统治者、使人厌恶与自身厌恶、事件名词、状态短语、拒绝某种观念、背弃领主，以及胃自身的翻腾。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pushing a contract away while a chair tips over and a crowd moves outside.","cn":"核心意象：一只手把契约推开，椅子翻倒，屋外人群正在移动。"},"chain":["TURN BACK","RISE AGAINST","RENOUNCE ALLEGIANCE","REPEL","FEEL NAUSEA","REFUSE AN IDEA"],"branches":[{"senses":"S1 · S4","en":"POLITICAL TURN: the verb and the event noun name the same breaking of obedience, once as act and once as happening.","cn":"政治转身：动词与事件名词指同一次顺从的断裂，一为动作，一为发生。"},{"senses":"S2 · S3","en":"DISGUST, TWO DIRECTIONS: a sight can repel a person, and a person can feel repelled, with the same image behind both.","cn":"厌恶的两个方向：景象可以排斥人，人也可以感到被排斥，背后是同一幅图。"},{"senses":"S5 · S7","en":"STATE AND ALLEGIANCE: a standing condition of resistance and a lord's lost loyalty are older, narrower layers.","cn":"状态与效忠：持续的反抗状态与领主的失去忠诚，是更早、更窄的层次。"},{"senses":"S6","en":"IDEA REFUSED: drop the weapons and the object becomes a belief, but the gesture stays.","cn":"拒绝观念：放下武器，对象变成信念，姿势却不变。"},{"senses":"S8","en":"THE BODY: the stomach's literal turning is the source image for all the rest.","cn":"身体：胃的实感翻腾是其余一切义项的源图。"}]},"affixes":{"intro":{"en":"Revolt is a Latin verb of rolling with a prefix of reversal, and the same root builds words about turning and revolution.","cn":"revolt 是一个带反转前缀的拉丁「滚动」动词，同一词根构成关于旋转与革命的一批词。"},"latinIntro":{"en":"Latin volvere 'to roll' gives revolve and revolution, and revolvere 'to roll back' lies behind revolt and the Italian verb that carried it.","cn":"拉丁 volvere「滚动」给出 revolve 与 revolution；revolvere「滚回」则是 revolt 及其中介意大利语动词的底。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back, again')","meaning":"back","meaningCN":"向后；回","example":"The prefix gives the rolling a direction.","exampleCN":"这个前缀给滚动一个方向。"},{"word":"volv-","structure":"volvere (Latin verb, 'to roll, turn')","meaning":"to roll","meaningCN":"滚动；转动","example":"The root supplies the turning image.","exampleCN":"这个词根提供转动的意象。"},{"word":"-t","structure":"-tus (Latin participial ending)","meaning":"result or act","meaningCN":"表结果或动作","example":"The ending yields the noun of a completed turning.","exampleCN":"这个词尾给出「转完了」的名词。"},{"word":"revolt","structure":"re- + volvere","meaning":"to turn back, rise against","meaningCN":"反叛；起义","example":"The tenants revolted over the new levy.","exampleCN":"佃户因新税而反抗。"},{"word":"revolted","structure":"revolt + -ed","meaning":"having risen, or feeling disgust","meaningCN":"已反叛的；感到厌恶的","example":"The revolted soldiers refused the order.","exampleCN":"反叛的士兵拒绝了命令。"},{"word":"revolting","structure":"revolt + -ing","meaning":"causing disgust","meaningCN":"令人作呕的","example":"The revolting stew was left untouched.","exampleCN":"那锅令人作呕的炖菜没人动。"},{"word":"revolve","structure":"re- + volvere","meaning":"to turn around an axis","meaningCN":"旋转；围绕","example":"The wheel revolves once per second.","exampleCN":"轮子每秒转一圈。"},{"word":"revolution","structure":"revolvere + -tion","meaning":"a turning over, a wholesale change","meaningCN":"革命；旋转","example":"The revolution began with a bread price.","exampleCN":"那场革命从面包价格开始。"}],"latinEntries":[{"word":"volvere","structure":"volvere, volvi, volutum (verb, third conjugation)","meaning":"to roll, turn","meaningCN":"滚动；转动"},{"word":"revolvere","structure":"revolvere, revolvi, revolutum (verb, third conjugation)","meaning":"to roll back, turn over","meaningCN":"滚回；翻覆"},{"word":"revolutio","structure":"revolutio, revolutionis (f., third declension)","meaning":"a turning over, a revolution","meaningCN":"翻转；革命"}]}},{"word":"uprising","ipa_uk":"/ʌpˈraɪzɪŋ/","ipa_us":"/ʌpˈraɪzɪŋ/","definition_zh":"起义；暴动；（古义）起身、上升","definition_en":"a spontaneous popular revolt, especially one that is short, local or sudden","core_image":"夜里一条窄巷挤满人，火把把墙照红，前排的人正把木箱推倒当台阶","scene":"监狱内院的铁门半开，走廊上散落着纸片与被推翻的桌椅。The prison uprising ended when the guards opened the inner gate.","sceneCN":"这里 uprising 指「被统治者突然发起的反抗事件」（第 2 个义项：范围有限的暴动）；句意为狱警打开内门后，这场监狱暴动结束了。场景物件：铁门、散落的纸片、翻倒的桌椅、火把。","pos":[{"tag":"n.","zh":"起义；暴动；（古义）起身、上升"}],"collocations":[{"phrase":"armed uprising","zh":"武装起义"},{"phrase":"popular uprising","zh":"民众起义"},{"phrase":"prison uprising","zh":"监狱暴动"},{"phrase":"crush an uprising","zh":"镇压起义"},{"phrase":"a wave of uprisings","zh":"一波起义"},{"phrase":"national uprising","zh":"民族起义"}],"forms":[{"label":"复数","form":"uprisings"},{"label":"动词（短语）","form":"rise up"},{"label":"动词原形","form":"rise"},{"label":"过去式","form":"rose"},{"label":"过去分词","form":"risen"},{"label":"名词","form":"rising"}],"derivatives":[{"word":"rise","pos":"v./n.","zh":"上升；起立"},{"word":"rising","pos":"n./adj.","zh":"上升；上升的"},{"word":"uprise","pos":"v./n.","zh":"起义；升起"},{"word":"riser","pos":"n.","zh":"起床者；梯级竖板"},{"word":"arisen","pos":"v.","zh":"arise 的过去分词"}],"senses":[{"no":"01","title":"An armed popular revolt","titleCN":"民众武装起义","definition":"a rising of ordinary people against those who rule them, often with weapons","definitionCN":"普通民众对统治者的起事，常持武器","example":"The uprising began in the market and reached the barracks by noon.","exampleCN":"起义从市场开始，到中午已传到兵营。","why":"uprising is simply 'a rising up', and English applied the physical verb to crowds long before it became a political noun.","whyCN":"uprising 本只是「向上起身」，英语把这个身体动词用在人群上，远早于它成为政治名词。"},{"no":"02","title":"A sudden local riot","titleCN":"局部突发暴动","definition":"a short revolt inside one institution or district, such as a prison or camp","definitionCN":"发生在单一机构或街区内的短暂反抗，如监狱或营地","example":"The prison uprising ended when the guards opened the inner gate.","exampleCN":"狱警打开内门后，这场监狱暴动结束了。","why":"the word suits events measured in hours, which is why prisons, camps and ships supply so many examples.","whyCN":"这个词适合以小时计的事件，因此监狱、营地与船只提供了大量用例。"},{"no":"03","title":"A named historical rising","titleCN":"有专名的历史起义","definition":"a particular rising recorded under a name and a date","definitionCN":"以名号与年代载入史册的某次起事","example":"The Warsaw Ghetto Uprising is remembered for lasting a month.","exampleCN":"华沙隔都起义因坚持一个月而被记住。","why":"historians make proper names out of events, and the compound keeps the plain noun inside the title.","whyCN":"史家把事件变成专名，复合标题里仍保留这个朴素名词。"},{"no":"04","title":"A mass protest movement","titleCN":"非暴力的群众抗争浪潮","definition":"a broad campaign of civil resistance that may avoid weapons altogether","definitionCN":"可能完全不动武的广泛民间抵抗运动","example":"A quiet uprising of parents filled the council chamber week after week.","exampleCN":"一场家长的静默抗争一周又一周地坐满议事厅。","why":"the metaphor no longer needs guns: any mass refusal that rises from below can take the name.","whyCN":"这个比喻不再需要枪：任何自下而上的大规模拒绝都能用这个名字。"},{"no":"05","title":"A national independence rising","titleCN":"民族独立起义","definition":"a rising of a subject people seeking to end foreign rule","definitionCN":"被统治民族为结束外来统治而发动的起事","example":"The national uprising of 1916 is taught in every school.","exampleCN":"一九一六年的民族起义在每所学校都被讲授。","why":"when the unit is a people rather than a crowd, the word gains the weight of sovereignty.","whyCN":"当单位是一个民族而非一群人之时，这个词便带上了主权分量。"},{"no":"06","title":"The literal act of rising","titleCN":"古义：起身、上升","definition":"the physical act of getting up or of a thing moving upward, the oldest sense","definitionCN":"起身或物体向上移动的实感动作，是最早的词义","example":"The prayer book still speaks of the uprising of the sun.","exampleCN":"祈祷书里仍说着太阳的升起。","why":"the political sense took over, yet poetry and liturgy kept the literal one alive.","whyCN":"政治义占了上风，诗歌与礼仪却让实感义活了下来。"},{"no":"07","title":"A surge of feeling","titleCN":"情绪的涌起（文学用法）","definition":"a rising movement of emotion or force inside a person or a crowd","definitionCN":"人或人群中情绪或力量的涌动","example":"An uprising of anger carried the crowd past the barricade.","exampleCN":"一阵愤怒的涌起把人群推过了街垒。","why":"the same upward motion is mapped onto feeling, so an emotion can rise like a crowd.","whyCN":"同样的向上运动被映射到情绪上，情绪于是可以像人群一样升起。"},{"no":"08","title":"A collective outcry online","titleCN":"网络上的集体声讨","definition":"a rapid mass protest organised through social media rather than streets","definitionCN":"借助社交媒体而非街头迅速组织的大规模抗议","example":"The hashtag turned a local complaint into a digital uprising overnight.","exampleCN":"那个话题标签一夜之间把一桩地方投诉变成一场网络声讨。","why":"new media gave the old word a new stage, and the rising now happens in feeds.","whyCN":"新媒体给这个旧词一个新舞台，起身发生在信息流里。"}],"etymology":{"intro":{"en":"Uprising is a native English compound of up and rising, and its political sense is only a few centuries old.","cn":"uprising 是英语本族复合词，由 up 与 rising 构成，其政治义只有数百年历史。"},"items":[{"era":"ENGLISH COMPOUND","en":"Uprising joins the adverb up to rising, the verbal noun of rise, with no Latin element at all.","cn":"uprising 把副词 up 接在 rise 的动名词 rising 上，完全不含拉丁成分。"},{"era":"OLD ENGLISH RISAN","en":"Rise goes back to Old English rīsan 'to get up, rise', a Germanic verb with cognates in Dutch rijzen and Old High German rīsan.","cn":"rise 上承古英语 rīsan「起身、上升」，是日耳曼动词，在荷兰语 rijzen 与古高地德语 rīsan 有同源词。"},{"era":"LITERAL SENSE","en":"In the fourteenth century an uprising was simply the act of getting up or the rising of a heavenly body.","cn":"14 世纪时，uprising 只指起身的动作或天体的升起。"},{"era":"REVOLT SENSE","en":"By the sixteenth century the word was used for a popular rising against rulers, and this sense drove out the literal one.","cn":"到 16 世纪，这个词被用于民众对统治者的起事，这一义逐渐挤走了实感义。"},{"era":"MODERN NUANCE","en":"Today uprising usually names a short, local or spontaneous revolt, while longer organised ones are called rebellions or revolutions.","cn":"今天 uprising 多指短暂、局部或自发的起事，较长久的组织化起事则称 rebellion 或 revolution。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest citation for the revolt sense is dated loosely to the 1560s, and the literal sense lingered in poetry after that.","cn":"来源不确定（首见年代）：起事义的最早书证只能约略定在 16 世纪六十年代；实感义此后仍在诗歌中延续。"}]},"similar":{"note":{"en":"Group one holds look-alikes built on the same rise family; group two holds the rival names for revolts.","cn":"第一组是同出 rise 词族的形近词；第二组是各类起事的竞争性名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rising","ipa":"/ˈraɪzɪŋ/","tag":"the plain noun","definition":"The general noun of rising, which can also mean a revolt in older British usage, without the up-.","definitionCN":"泛指上升的普通名词，旧英式用法也可指起事，只是没有 up-。"},{"word":"uprise","ipa":"/ʌpˈraɪz/","tag":"rare verb and noun","definition":"A rarer single-word form meaning to rise up; the longer uprising is the everyday noun.","definitionCN":"较少见的单词形式，意为升起；日常名词用较长的 uprising。"},{"word":"upsurge","ipa":"/ˈʌpsɜːdʒ/","tag":"sudden increase","definition":"A surge of activity or feeling, from Latin surgere 'to rise', and never a political rising.","definitionCN":"指活动或情绪的骤增，出自拉丁 surgere「升起」，从不指政治起事。"},{"word":"upheaval","ipa":"/ʌpˈhiːvl/","tag":"violent disruption","definition":"A heavy disturbance or overturning, from heave, broader than a single rising.","definitionCN":"指剧烈的动荡或翻覆，出自 heave，比单次起事更宽。"}]},{"heading":"NEAR MEANING","entries":[{"word":"revolt","ipa":"/rɪˈvəʊlt/","tag":"turning away","definition":"Stresses the casting off of allegiance, and can also mean to disgust.","definitionCN":"强调抛弃效忠，也可指使人厌恶。"},{"word":"rebellion","ipa":"/rɪˈbeljən/","tag":"organised and sustained","definition":"Implies leaders, plans and duration; an uprising is usually quicker and looser.","definitionCN":"暗示领袖、计划与持续时间；uprising 通常更快、更松散。"},{"word":"insurrection","ipa":"/ˌɪnsəˈrekʃn/","tag":"legal label","definition":"The formal or legal name for a rising against the state, used in statutes and charges.","definitionCN":"对国家起事的正式或法律名称，见于法规与控罪。"},{"word":"riot","ipa":"/ˈraɪət/","tag":"disorder without a program","definition":"Crowd violence that may have no political aim; an uprising always has a target above it.","definitionCN":"人群暴力，可能没有政治目标；uprising 总有上方的目标。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a native compound, a real Germanic verb and real historical titles.","cn":"正常联想：本族复合词、真实的日耳曼动词与真实历史标题。"},"normal":[{"en":"up + rising: the plainest possible description of a crowd getting to its feet.","cn":"up + rising：对人群站起来这件事最直白的描述。"},{"en":"The rise family runs rise, rose, risen, rising, uprise, uprising.","cn":"rise 词族包括 rise、rose、risen、rising、uprise、uprising。"},{"en":"No Latin here: the word is native English, unlike revolt or rebellion.","cn":"这里没有拉丁成分：与 revolt、rebellion 不同，它是英语本族词。"},{"en":"Titles preserve it: the Warsaw Ghetto Uprising, the Soweto Uprising.","cn":"专名保留了它：华沙隔都起义、索韦托起义。"},{"en":"Scale words pair with it: armed, popular, prison, national.","cn":"表规模的词与它搭配：武装的、民众的、监狱的、民族的。"}],"abstract":[{"en":"Picture a narrow lane packed with people and torches at night.","cn":"想象夜里一条窄巷挤满人与火把。"},{"en":"Picture a crate pushed over to serve as a step.","cn":"想象一只木箱被推倒，当作台阶。"},{"en":"Picture a hall where every hand goes up at once.","cn":"想象一座大厅里所有手同时举起。"}]},"examples":[{"en":"The uprising spread from one district to four within a week.","cn":"起义一周内从一区蔓延到四区。"},{"en":"A prison uprising usually ends at the inner gate.","cn":"监狱暴动通常止于内门。"},{"en":"The history class compared the uprising with the later rebellion.","cn":"历史课把这次起义与后来的叛乱作了比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿普莱辛」听似「往上立身」——被压住的人一齐立起来 → 起义、暴动","word":"uprising"},"root":"英语本族复合词：up「向上」+ rising（rise 的动名词）；rise 上承古英语 rīsan「起身、上升」，属日耳曼语族，无拉丁同族词。","sensesIntro":{"en":"Eight senses rise from a body to a crowd: the armed rising, the local riot, the named event, the non-violent campaign, the national struggle, the literal getting up, the surge of feeling and the online outcry.","cn":"八个义项从身体升到人群：武装起事、局部暴动、有专名的事件、非暴力抗争、民族斗争、实感起身、情绪涌起与网络声讨。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrow lane packed with people and torches, a crate pushed over as a step.","cn":"核心意象：一条挤满人与火把的窄巷，一只木箱被推倒当台阶。"},"chain":["RISE UP","CROWD RISES","LOCAL RIOT","ARMED REVOLT","NAMED EVENT","SURGE OF FEELING"],"branches":[{"senses":"S1 · S5","en":"PEOPLE IN ARMS: the general popular rising and the national struggle differ in scale, not in gesture.","cn":"武装的民众：泛指民众起事与民族斗争差别在规模，不在姿势。"},{"senses":"S2","en":"SUDDEN AND LOCAL: a prison yard hosts a rising measured in hours rather than in months.","cn":"突然与局部：监狱院子里的一场起事以小时而非月计。"},{"senses":"S3 · S4","en":"NAMED AND PEACEFUL: history turns one into a title, while civil resistance proves the word needs no weapons.","cn":"专名与和平：历史把一次变成标题，民间抵抗则证明这个词不需要武器。"},{"senses":"S6 · S7","en":"BODY AND FEELING: the oldest sense is getting up, and emotion borrows the same upward motion.","cn":"身体与情绪：最早的义项是起身，情绪借用同一种向上运动。"},{"senses":"S8","en":"NEW STAGE: the rising now happens in feeds as often as in streets.","cn":"新舞台：起身如今在信息流里发生的次数不亚于街头。"}]},"affixes":{"intro":{"en":"Uprising is built only from native English pieces, so its whole structure can be read without leaving the Germanic layer.","cn":"uprising 只由英语本族成分构成，因此整个结构不必离开日耳曼层就能读通。"},"latinIntro":{"en":"There is no Latin relative here: the word is a native compound of up and rising, and its older relatives are Germanic.","cn":"这里没有拉丁同族词：它是 up 与 rising 的本族复合词，较古的同族形式属日耳曼语。"},"items":[{"word":"up-","structure":"Old English up, adverb of direction","meaning":"upward","meaningCN":"向上","example":"The particle gives the whole word its upward direction.","exampleCN":"这个小词给整词向上的方向。"},{"word":"rise","structure":"Old English rīsan (strong verb)","meaning":"to get up, move upward","meaningCN":"起身；上升","example":"The verb is the base of the whole family.","exampleCN":"这个动词是整个词族的基础。"},{"word":"-ing","structure":"Old English -ing, verbal noun ending","meaning":"the act of","meaningCN":"…的动作","example":"The ending turns the verb into an event noun.","exampleCN":"这个词尾把动词变成事件名词。"},{"word":"uprising","structure":"up + rising","meaning":"a rising up, a revolt","meaningCN":"起义；暴动","example":"The uprising lasted one night.","exampleCN":"那场暴动只持续一夜。"},{"word":"uprise","structure":"up + rise","meaning":"to rise up","meaningCN":"升起；起事","example":"The old verb now survives mostly in poetry.","exampleCN":"这个旧动词如今多存于诗歌。"},{"word":"rising","structure":"rise + -ing","meaning":"an act of rising, a revolt","meaningCN":"上升；起事","example":"A rising in the north worried the council.","exampleCN":"北方的一场起事让议会不安。"},{"word":"risen","structure":"past participle of rise","meaning":"having risen","meaningCN":"已升起的","example":"The risen sun cleared the ridge.","exampleCN":"升起的太阳越过山脊。"},{"word":"riser","structure":"rise + -er","meaning":"one who rises, or a vertical piece","meaningCN":"起床者；竖板","example":"The stair riser was cut from oak.","exampleCN":"楼梯竖板是橡木做的。"}],"latinEntries":[]}},{"word":"resistance","ipa_uk":"/rɪˈzɪstəns/","ipa_us":"/rɪˈzɪstəns/","definition_zh":"抵抗；抵抗力；阻力；电阻；抗药性；反对","definition_en":"the act of fighting or standing against something, or the ability of a body, circuit or organism to oppose a force","core_image":"一道木栅被潮水反复顶撞，木条弯下去又弹回来，栅后的人仍在把沙袋往上叠","scene":"战时小城的地窖里，桌上摊着折成小块的纸条与手绘地图，自行车靠在墙边。The resistance hid couriers in cellars and moved maps by bicycle.","sceneCN":"这里 resistance 指「被占领区内的地下抵抗组织」（第 2 个义项：有组织的地下抵抗运动）；句意为抵抗组织把送信人藏在地窖里，用自行车传递地图。场景物件：地窖、折起的纸条、手绘地图、自行车。","pos":[{"tag":"n.","zh":"抵抗；抵抗力；阻力；电阻；抗药性"}],"collocations":[{"phrase":"resistance to change","zh":"对变革的抗拒"},{"phrase":"armed resistance","zh":"武装抵抗"},{"phrase":"drug resistance","zh":"抗药性"},{"phrase":"electrical resistance","zh":"电阻"},{"phrase":"air resistance","zh":"空气阻力"},{"phrase":"the French Resistance","zh":"法国抵抗运动"}],"forms":[{"label":"复数","form":"resistances"},{"label":"动词","form":"resist"},{"label":"形容词","form":"resistant"},{"label":"名词（元件）","form":"resistor"},{"label":"名词（电阻率）","form":"resistivity"}],"derivatives":[{"word":"resist","pos":"v.","zh":"抵抗；忍住"},{"word":"resistant","pos":"adj.","zh":"抵抗的；有抵抗力的"},{"word":"resistor","pos":"n.","zh":"电阻器"},{"word":"resistivity","pos":"n.","zh":"电阻率"},{"word":"resistless","pos":"adj.","zh":"不可抵抗的；无抵抗力的"}],"senses":[{"no":"01","title":"Fighting against an attack","titleCN":"抵抗进攻、防御","definition":"organised opposition to an armed attack or an occupying power","definitionCN":"对武装进攻或占领力量的组织化对抗","example":"The town's resistance lasted longer than its walls.","exampleCN":"这座城的抵抗比它的城墙撑得更久。","why":"resistere is 'to stand against', and the oldest English uses are about holding a position against force.","whyCN":"resistere 意为「站住对抗」，英语最早的用例都是顶住武力。"},{"no":"02","title":"An underground movement","titleCN":"地下抵抗组织","definition":"a secret network that fights an occupier from within, often capitalised","definitionCN":"在占领区内秘密对抗占领者的网络，常大写","example":"The resistance hid couriers in cellars and moved maps by bicycle.","exampleCN":"抵抗组织把送信人藏在地窖里，用自行车传递地图。","why":"twentieth-century occupations gave the abstract noun a concrete body, and the capital letter marks the organisation.","whyCN":"20 世纪的占领让这个抽象名词有了具体躯体，大写字母标出组织本身。"},{"no":"03","title":"Refusal to accept or obey","titleCN":"拒绝接受、反对","definition":"a firm refusal to agree with a plan, a rule or a demand","definitionCN":"坚决拒绝同意某项计划、规则或要求","example":"Resistance to the new timetable came from every department.","exampleCN":"对新时间表的反对来自每一个部门。","why":"standing against need not be physical, so the same noun covers a committee's refusal as easily as a barricade.","whyCN":"「站住对抗」不必是身体动作，因此同一个名词既可指街垒，也可指委员会的拒绝。"},{"no":"04","title":"A material's strength against force","titleCN":"材料抗外力的能力","definition":"the property of a substance that lets it withstand pressure, wear or heat","definitionCN":"物质承受压力、磨损或高温的性质","example":"The alloy's resistance to salt water made it ideal for the pier.","exampleCN":"这种合金抗海水，正适合建栈桥。","why":"engineering took the moral word and made it measurable: how much a body stands before it gives way.","whyCN":"工程学拿走了这个道义词，把它变成可测量的量：一个物体在屈服前能顶住多少。"},{"no":"05","title":"Electrical resistance","titleCN":"电阻","definition":"the opposition a conductor offers to the flow of current, measured in ohms","definitionCN":"导体对电流通过的阻碍，以欧姆计","example":"Thin wire adds resistance and turns current into heat.","exampleCN":"细导线增加电阻，把电流变成热。","why":"the word was ready-made for physics because a circuit behaves like a defended position.","whyCN":"物理学拿来这个词毫不费力，因为电路的行为就像一个被守住的阵地。"},{"no":"06","title":"Biological immunity to attack","titleCN":"生物的抗性、抗药性","definition":"the ability of a plant, pest or germ to survive a drug or a disease that once harmed it","definitionCN":"植物、害虫或病菌对曾经有害的药物或疾病存活下来的能力","example":"Overuse of the spray bred resistance in the beetles within a decade.","exampleCN":"滥用这种喷剂，十年内就让甲虫产生了抗性。","why":"evolution supplied the clearest case: a population stands against what kills it, and the survivors define the trait.","whyCN":"演化提供了最清楚的例子：种群顶住致死之物，存活者定义了这种性状。"},{"no":"07","title":"Air or fluid drag","titleCN":"空气或流体阻力","definition":"the force that opposes a body moving through air or water","definitionCN":"物体在空气或水中运动时受到的对抗力","example":"A fairing cuts air resistance more than a stronger engine adds speed.","exampleCN":"整流罩减少空气阻力，比更强的引擎更能提速。","why":"the physical sense splits by medium, and aerodynamics named one branch of it for daily use.","whyCN":"实感义按介质分出分支，空气动力学把其中一支带入日常语言。"},{"no":"08","title":"Inner reluctance to change","titleCN":"心理上对改变的抗拒","definition":"a person's or group's unwillingness to accept a new idea, often unconscious","definitionCN":"个人或群体不愿接受新观念，常是无意识的","example":"Resistance appeared in the questions long before anyone said no.","exampleCN":"抗拒早在有人开口说「不」之前就出现在提问里。","why":"psychology moved the word inward, where the opposing force is a habit rather than an army.","whyCN":"心理学把这个词移入内部，对抗的力量成了习惯而非军队。"}],"etymology":{"intro":{"en":"Resistance goes back to Latin resistentia, the noun of resistere 'to stand against', built on re- and sistere 'to stand'.","cn":"resistance 上承拉丁 resistentia，是 resistere「站住对抗」的名词，由 re- 与 sistere「站立」构成。"},"items":[{"era":"LATIN RESISTERE","en":"resistere meant 'to stand against, withstand, oppose', literally to stand back against something.","cn":"resistere 意为「站住对抗、顶住、反对」，字面是「向后站住顶住某物」。"},{"era":"RE PLUS SISTERE","en":"re- 'back, against' plus sistere 'to stand, set oneself', a reduplicated verb related to stare 'to stand'.","cn":"re-「向后、对抗」加 sistere「站立、使自己站定」，后者是与 stare「站」相关的重叠动词。"},{"era":"ENGLISH FOURTEENTH CENTURY","en":"The word entered English in the fourteenth century, first as a physical or moral act of withstanding.","cn":"这个词在 14 世纪进入英语，最初指身体或道义上的顶住。"},{"era":"ELECTRICITY","en":"Nineteenth-century physics gave it a measured sense, the opposition a conductor offers to a current.","cn":"19 世纪物理学给了它可测量的意义：导体对电流的阻碍。"},{"era":"MEDICINE","en":"Twentieth-century medicine added resistance to drugs and to disease, the ability of an organism to survive what should kill it.","cn":"20 世纪医学加上对药物与疾病的抗性，即生物在理应致死之物下存活的能力。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin base of sistere is reconstructed, and the priority between the moral and physical senses in English is not documented.","cn":"来源不确定（更深词源）：sistere 在拉丁语之前的词基属重构；英语中道义义与身体义孰先亦无书证。"}]},"similar":{"note":{"en":"Group one holds the same sistere stock, including one true opposite; group two holds rival words for opposing force.","cn":"第一组同出 sistere 词干，并含一个真正的反义词；第二组是表达对抗之力的竞争性词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"resist","ipa":"/rɪˈzɪst/","tag":"the verb","definition":"To stand against or to refrain from, as in resist temptation; the noun adds the measurable senses.","definitionCN":"意为站住对抗或忍住，如抵制诱惑；名词另带可测量的诸义。"},{"word":"resistant","ipa":"/rɪˈzɪstənt/","tag":"the adjective","definition":"Describes something that withstands, often with to: resistant to heat, resistant to change.","definitionCN":"形容能顶住的事物，常与 to 连用：耐热的、抗拒改变的。"},{"word":"resistor","ipa":"/rɪˈzɪstə/","tag":"the component","definition":"The physical device that adds electrical resistance, a concrete count noun.","definitionCN":"指增加电阻的具体元件，是可数名词。"},{"word":"assist","ipa":"/əˈsɪst/","tag":"same root, opposite sense","definition":"From ad- plus sistere, 'to stand by someone', so the same verb of standing yields help instead of opposition.","definitionCN":"由 ad- 加 sistere 构成，意为「站在某人身边」，同一「站立」动词由此给出帮助而非对抗。"}]},{"heading":"NEAR MEANING","entries":[{"word":"opposition","ipa":"/ˌɒpəˈzɪʃn/","tag":"general counter-force","definition":"Any standing against, in politics or argument, without the physical or electrical senses.","definitionCN":"政治或争论中的任何对立，不含身体或电学义。"},{"word":"defiance","ipa":"/dɪˈfaɪəns/","tag":"open refusal","definition":"Visible refusal to obey, with a challenge in the tone; resistance can be silent and technical.","definitionCN":"公开拒绝服从，语气带挑战；resistance 可以是沉默的、技术性的。"},{"word":"immunity","ipa":"/ɪˈmjuːnəti/","tag":"biological protection","definition":"Full protection against a disease, stronger than mere resistance, which may only slow it.","definitionCN":"对疾病的完全保护，强于仅有抗性；抗性可能只是拖慢。"},{"word":"drag","ipa":"/dræɡ/","tag":"the force in fluids","definition":"The specific word for resistance offered by air or water to a moving body.","definitionCN":"专指空气或水对运动物体施加的阻力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin verb, a real opposite and real technical collocations.","cn":"正常联想：真实的拉丁动词、真实的反义词与真实技术搭配。"},"normal":[{"en":"re- 'against' + sistere 'stand' = stand against, the whole word in one gesture.","cn":"re-「对抗」+ sistere「站立」= 站住对抗，整个词就是这一个动作。"},{"en":"assist is the mirror image: ad- + sistere, standing by instead of against.","cn":"assist 是镜像：ad- + sistere，站在旁边而非对面。"},{"en":"The family runs resist, resistance, resistant, resistor, resistivity.","cn":"同族词包括 resist、resistance、resistant、resistor、resistivity。"},{"en":"Technical phrases mark the branches: electrical resistance, drug resistance, air resistance.","cn":"技术搭配标出分支：电阻、抗药性、空气阻力。"},{"en":"History capitalises one branch: the Resistance in occupied Europe.","cn":"历史让一支大写：被占领欧洲的抵抗运动。"}],"abstract":[{"en":"Picture a wooden fence bending under a wave and springing back.","cn":"想象一道木栅在浪下弯折又弹回。"},{"en":"Picture sandbags stacked behind a door that will not open.","cn":"想象打不开的门后堆着沙袋。"},{"en":"Picture a narrow wire growing warm as current struggles through it.","cn":"想象细导线在电流艰难通过时渐渐发热。"}]},"examples":[{"en":"The material's resistance to heat decides the cost of the lining.","cn":"材料耐热的程度决定衬里的成本。"},{"en":"Resistance to the plan hardened once the budget was published.","cn":"预算公布后，对这项计划的反对变得强硬。"},{"en":"Low resistance in the cable keeps the signal clean.","cn":"电缆电阻低，信号才能保持清晰。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞吉斯腾斯」听似「再拒死」——顶住不退，就是再拒一次死 → 抵抗、阻力","word":"resistance"},"root":"拉丁 resistentia「抵抗」= re-「对抗、向后」+ sistere「站立」+ -ntia 名词后缀；sistere 与 stare「站」相关，其在拉丁语之前的词基属重构。","sensesIntro":{"en":"Eight senses hold one posture, standing against: against an army, an occupier, a rule, a load, a current, a disease, the air, and finally one's own habit.","cn":"八个义项守住同一个姿势——站住对抗：对抗军队、占领者、规则、载荷、电流、疾病、空气，最后是对抗自己的习惯。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wooden fence bending under repeated waves and springing back while sandbags pile up behind it.","cn":"核心意象：一道木栅在反复的浪下弯曲又弹回，栅后沙袋越叠越高。"},"chain":["STAND AGAINST","HOLD A POSITION","UNDERGROUND FIGHT","BEAR A LOAD","OPPOSE A CURRENT","SURVIVE A DRUG"],"branches":[{"senses":"S1 · S2","en":"ORGANISED FIGHT: an army at the walls and a network in the cellars are the same posture at two scales.","cn":"组织化对抗：城墙上的军队与地窖里的网络，是同一姿势的两种规模。"},{"senses":"S3","en":"REFUSAL: a committee saying no stands against a plan exactly as a barricade stands against troops.","cn":"拒绝：委员会对计划说「不」，与街垒对抗军队是同一个站法。"},{"senses":"S4 · S7","en":"PHYSICAL LOAD: a material under pressure and a body moving through air both measure how much opposition is offered.","cn":"实体载荷：受压的材料与穿行空气的物体，都在计量所提供对抗的大小。"},{"senses":"S5","en":"CIRCUIT: electricity gave the posture a number and a unit.","cn":"电路：电学给这个姿势一个数值与一个单位。"},{"senses":"S6 · S8","en":"LIVING DEFENCE: a beetle surviving a spray and a mind refusing a new idea both stand against what would change them.","cn":"活的防御：挨过喷剂的甲虫与拒绝新观念的心智，都在对抗会改变它们的东西。"}]},"affixes":{"intro":{"en":"Resistance is a Latin action noun whose root also builds a true antonym, so the word can be read against its mirror.","cn":"resistance 是一个拉丁动作名词，其词根还构成一个真正的反义词，因此可以对着镜像读它。"},"latinIntro":{"en":"Latin sistere 'to stand' gives resist, resistance, assist and insist, while stare 'to stand' supplies the plainer English relatives.","cn":"拉丁 sistere「站立」给出 resist、resistance、assist、insist；stare「站」则提供更朴素的英语同族词。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back, against')","meaning":"against, back","meaningCN":"对抗；向后","example":"The prefix aims the standing against something.","exampleCN":"这个前缀把「站立」对准某物。"},{"word":"sist-","structure":"sistere (Latin verb, 'to stand, set')","meaning":"to stand","meaningCN":"站立","example":"The root supplies the posture in every word of the family.","exampleCN":"这个词根为词族每个词提供姿势。"},{"word":"-ance","structure":"-antia (Latin noun suffix)","meaning":"state or quality","meaningCN":"状态；性质","example":"The suffix turns the verb into a quality noun.","exampleCN":"这个后缀把动词变成性质名词。"},{"word":"resist","structure":"re- + sistere","meaning":"to stand against","meaningCN":"抵抗；忍住","example":"The coating resists rust for a decade.","exampleCN":"这层涂料十年不锈。"},{"word":"resistance","structure":"resist + -ance","meaning":"the act or power of withstanding","meaningCN":"抵抗；阻力；电阻","example":"The resistance of the wire is printed on the box.","exampleCN":"导线的电阻印在盒子上。"},{"word":"resistant","structure":"resist + -ant","meaning":"withstanding","meaningCN":"有抵抗力的","example":"The variety is resistant to mildew.","exampleCN":"这个品种抗白粉病。"},{"word":"resistor","structure":"resist + -or","meaning":"a device that resists current","meaningCN":"电阻器","example":"A resistor controls the current in the circuit.","exampleCN":"电阻器控制电路中的电流。"},{"word":"resistivity","structure":"resistive + -ity","meaning":"resistance per unit length","meaningCN":"电阻率","example":"Copper has low resistivity.","exampleCN":"铜的电阻率低。"},{"word":"assist","structure":"ad- + sistere","meaning":"to stand by, help","meaningCN":"帮助","example":"A nurse assisted at the operation.","exampleCN":"一名护士在手术中协助。"},{"word":"insist","structure":"in- + sistere","meaning":"to stand upon, persist","meaningCN":"坚持","example":"She insisted on a written answer.","exampleCN":"她坚持要一个书面答复。"}],"latinEntries":[{"word":"sistere","structure":"sistere, stiti, statum (verb, third conjugation)","meaning":"to stand, set, place","meaningCN":"站立；安置"},{"word":"resistere","structure":"resistere, restiti, resistitum (verb, third conjugation)","meaning":"to stand against, withstand","meaningCN":"站住对抗；顶住"},{"word":"resistentia","structure":"resistentia, resistentiae (f., first declension)","meaning":"resistance, opposition","meaningCN":"抵抗；对抗"}]}},{"word":"conquest","ipa_uk":"/ˈkɒŋkwest/","ipa_us":"/ˈkɑːŋkwest/","definition_zh":"征服；占领；被征服之地；攻克；赢得（爱情）","definition_en":"the act of taking a country or people by force, the territory so taken, or any hard-won victory","core_image":"城头换上一面陌生的旗，城门洞开，攻城的木梯还靠在墙边，队列正从门洞里走过","scene":"山谷尽头的石城城门洞开，城头换上陌生旗号，攻城木梯靠在墙边。The conquest of the valley took three summers and cost two armies.","sceneCN":"这里 conquest 指「以武力攻取并控制某地的行为」（第 1 个义项：军事征服）；句意为征服这座山谷用了三个夏天，耗掉了两支军队。场景物件：城门、换上的旗、攻城木梯、队列。","pos":[{"tag":"n.","zh":"征服；占领；被征服之地；攻克；赢得"}],"collocations":[{"phrase":"the Norman Conquest","zh":"诺曼征服"},{"phrase":"conquest of territory","zh":"领土的征服"},{"phrase":"conquest of space","zh":"对太空的征服"},{"phrase":"economic conquest","zh":"经济上的占领"},{"phrase":"a conquest of disease","zh":"对疾病的攻克"},{"phrase":"military conquest","zh":"军事征服"}],"forms":[{"label":"复数","form":"conquests"},{"label":"动词","form":"conquer"},{"label":"指人的名词","form":"conqueror"},{"label":"形容词","form":"conquered"},{"label":"形容词（可征服的）","form":"conquerable"}],"derivatives":[{"word":"conquer","pos":"v.","zh":"征服；战胜"},{"word":"conqueror","pos":"n.","zh":"征服者"},{"word":"conquerable","pos":"adj.","zh":"可征服的"},{"word":"unconquered","pos":"adj.","zh":"未被征服的"},{"word":"reconquest","pos":"n.","zh":"重新征服"}],"senses":[{"no":"01","title":"The act of taking a country by force","titleCN":"以武力攻取他国的行为","definition":"the military act of defeating a state or people and taking control of its land","definitionCN":"击败一个国家或民族并控制其土地的军事行为","example":"The conquest of the valley took three summers and cost two armies.","exampleCN":"征服这座山谷用了三个夏天，耗掉了两支军队。","why":"conquirere means 'to seek out and gain', so the word presents taking as the end of a long search.","whyCN":"conquirere 意为「搜寻并取得」，因此这个词把攻取呈现为一场漫长搜寻的终点。"},{"no":"02","title":"The land so taken","titleCN":"被征服的领土","definition":"the territory that passes under a conqueror's control, treated as a possession","definitionCN":"转入征服者控制之下、被当作产业处理的土地","example":"The new conquest was taxed before its roads were mapped.","exampleCN":"这块新征服的领地在道路测绘之前就已开始征税。","why":"English often lets an action noun stand for its object, so the act becomes a place on the map.","whyCN":"英语常让动作名词代替其对象，于是行为本身变成了地图上的一块地方。"},{"no":"03","title":"The overcoming of an obstacle","titleCN":"对抽象障碍的攻克","definition":"a hard-won success over a natural or social obstacle such as disease or space","definitionCN":"对疾病、太空等自然或社会障碍艰难取得的成功","example":"The conquest of smallpox took two centuries and a global campaign.","exampleCN":"对天花的攻克用了两个世纪与一场全球运动。","why":"the shape repeats: something resists, and people organise until it gives way, so war language serves science.","whyCN":"形状重复：某物抵抗，人们组织起来直到它让步，于是战争语言被科学借用。"},{"no":"04","title":"The winning of someone's affection","titleCN":"赢得某人的爱慕","definition":"the act of winning a person's love or admiration, often used lightly","definitionCN":"赢得某人的爱情或倾慕，常带轻佻语气","example":"He treated the courtship as a conquest and told everyone about it.","exampleCN":"他把这段追求当作一次征服，还向所有人炫耀。","why":"the metaphor turns a person into territory, which is why modern writers often flag the word as crude.","whyCN":"这个比喻把人变成领土，因此现代作家常指出这个词粗鲁。"},{"no":"05","title":"A named historical event","titleCN":"有专名的历史事件","definition":"a specific conquest remembered under a name, such as the Norman Conquest","definitionCN":"以名号被记住的具体征服，如诺曼征服","example":"The Norman Conquest replaced the English court and half its vocabulary.","exampleCN":"诺曼征服替换了英格兰的宫廷与半套词汇。","why":"historians turn one campaign into a proper name, and the common noun becomes a chapter heading.","whyCN":"史家把一次战事变成专名，普通名词于是成了章节标题。"},{"no":"06","title":"Control of a market or industry","titleCN":"市场或产业上的占领","definition":"the gaining of dominant control over trade, customers or a sector","definitionCN":"取得对贸易、客户或某一行业的主导控制","example":"The company's conquest of the delivery market worried the regulators.","exampleCN":"该公司对配送市场的占领让监管者不安。","why":"business borrowed the military noun because market share behaves like ground that can be held or lost.","whyCN":"商业借用这个军事名词，因为市场份额就像可以守住或丢掉的地面。"},{"no":"07","title":"Spiritual mastery of the self","titleCN":"精神上对自我的克制","definition":"the religious subduing of passions and will, an older inward sense","definitionCN":"宗教意义上对情欲与意志的制伏，是较早的内在义","example":"The monk wrote of the conquest of anger as a daily labour.","exampleCN":"这位修士把克制愤怒写作日复一日的劳作。","why":"the inward sense keeps the same structure but moves the enemy inside, which ascetic writing found useful.","whyCN":"内在义保留同样结构，只把敌人移进内部，苦修文学正需要它。"},{"no":"08","title":"Mastery of a field of knowledge","titleCN":"对一门知识或技艺的掌握","definition":"the gradual winning of command over a subject, skill or craft","definitionCN":"逐步取得对某门学问、技能或手艺的掌控","example":"Her conquest of the cello began with scales at forty.","exampleCN":"她对大提琴的攻克从四十岁的音阶开始。","why":"the last extension drops land entirely: what is taken is a difficulty, and the taking is learning.","whyCN":"最后一层完全放下土地：被攻取的是困难，而攻取就是学习。"}],"etymology":{"intro":{"en":"Conquest came through Old French conqueste from the Latin verb conquirere 'to seek out and gain'.","cn":"conquest 经古法语 conqueste 来自拉丁动词 conquirere「搜寻并取得」。"},"items":[{"era":"OLD FRENCH CONQUESTE","en":"Old French conqueste carried the noun into English in the thirteenth century, first as the act of winning by force.","cn":"古法语 conqueste 在 13 世纪把这个名词带入英语，最初指以武力取得的行为。"},{"era":"VULGAR LATIN CONQUAESITA","en":"The French form rests on Vulgar Latin conquaesita, a noun of result from conquirere, literally 'things sought together'.","cn":"法语形式以俗拉丁 conquaesita 为底，那是 conquirere 的结果名词，字面为「一同搜寻所得之物」。"},{"era":"LATIN CONQUIRERE","en":"conquirere 'to seek out, procure, gain' joins com- 'together, thoroughly' to quaerere 'to seek'.","cn":"conquirere「搜寻、取得、赢得」由 com-「共同、彻底」加 quaerere「寻找」构成。"},{"era":"OBJECT SENSE","en":"From the act the word shifted to the land won, so a conquest could be a place on a map.","cn":"词义从行为转向被赢得的土地，于是 conquest 可以是地图上的一块地方。"},{"era":"WIDENING","en":"Later conquest covered mastery of disease, space, a market or a heart, since all repeat the shape of winning something that resists.","cn":"后来它覆盖对疾病、太空、市场或人心的掌握，因为这些都重复「赢得抵抗之物」的形状。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin origin of quaerere is disputed, and any root proposed for it is a reconstruction.","cn":"来源不确定（更深词源）：quaerere 在拉丁语之前的来源有争议，为其提出的词根均属重构。"}]},"similar":{"note":{"en":"Group one holds words on the same quaerere stock; group two holds rival nouns for taking and winning.","cn":"第一组是同出 quaerere 词干的词；第二组是表达攻取与赢得的竞争性名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conquer","ipa":"/ˈkɒŋkə/","tag":"the verb","definition":"The act itself; conquest is the noun of that act and then the land it produces.","definitionCN":"指动作本身；conquest 是该动作的名词，随后又指由此得到的土地。"},{"word":"conqueror","ipa":"/ˈkɒŋkərə/","tag":"the person","definition":"The agent noun; a conquest needs a conqueror, but the words answer different questions.","definitionCN":"施事名词；一次征服需要一个征服者，但两个词回答的问题不同。"},{"word":"quest","ipa":"/kwest/","tag":"a search","definition":"From quaerere without the prefix, meaning a long search or an adventure, with no taking of land.","definitionCN":"同出 quaerere 而无前缀，指漫长的寻找或冒险，不含攻取土地。"},{"word":"request","ipa":"/rɪˈkwest/","tag":"seeking again","definition":"re- plus quaerere, 'to seek again', hence to ask for something; the root is shared, the sense is not.","definitionCN":"re- 加 quaerere，意为「再次寻求」，故指请求；词根相同，意义不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"victory","ipa":"/ˈvɪktəri/","tag":"winning the fight","definition":"Winning a battle or contest, with no promise of holding what was won.","definitionCN":"指赢得战斗或比赛，不保证守住所得。"},{"word":"occupation","ipa":"/ˌɒkjuˈpeɪʃn/","tag":"holding the ground","definition":"The state of holding territory, which may lack the decisive taking that conquest names.","definitionCN":"指占领状态，可能缺少 conquest 所指的决定性攻取。"},{"word":"takeover","ipa":"/ˈteɪkəʊvə/","tag":"business control","definition":"The commercial word for gaining control of a firm, narrower than conquest.","definitionCN":"取得公司控制的商业用词，比 conquest 窄。"},{"word":"seizure","ipa":"/ˈsiːʒə/","tag":"sudden capture","definition":"A quick taking of a thing or place, often legal or physical, without a campaign.","definitionCN":"迅速夺取某物或某地，常属法律或身体动作，不含战役。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin verb, a real suffix and real historical titles.","cn":"正常联想：真实的拉丁动词、真实的后缀与真实历史标题。"},"normal":[{"en":"con- 'thoroughly' + quaerere 'seek' = seek until you gain it, which is conquest.","cn":"con-「彻底」+ quaerere「寻找」= 一直找到取得为止，这就是征服。"},{"en":"The same root runs through quest, question, request and inquire.","cn":"同一词根贯穿 quest、question、request、inquire。"},{"en":"The family runs conquer, conquest, conqueror, conquerable, reconquest.","cn":"同族词包括 conquer、conquest、conqueror、conquerable、reconquest。"},{"en":"History supplies the proper name: the Norman Conquest of 1066.","cn":"历史提供专名：一〇六六年的诺曼征服。"},{"en":"Two fixed phrases show the widening: the conquest of space and the conquest of disease.","cn":"两个固定搭配显示词义扩展：对太空的征服、对疾病的攻克。"}],"abstract":[{"en":"Picture a strange flag going up over a gate while a siege ladder stays against the wall.","cn":"想象一面陌生旗在城门上升起，攻城梯还靠在墙边。"},{"en":"Picture a map with one province repainted in a new colour overnight.","cn":"想象地图上一省一夜之间被涂成新颜色。"},{"en":"Picture a last jigsaw piece pressed into place.","cn":"想象最后一块拼图被按进位置。"}]},"examples":[{"en":"The conquest brought a new language to the courts and a new tax to the fields.","cn":"这次征服给宫廷带来新语言，给田地带来新税。"},{"en":"The conquest of the mountain took four attempts and one lost guide.","cn":"对这座山的征服用了四次尝试和一位失踪的向导。"},{"en":"Their conquest of the market lasted until a rival cut prices.","cn":"他们对市场的占领持续到对手降价为止。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康奎斯特」听似「扛过去」——一路寻求、硬扛到底直到拿下 → 征服、占领","word":"conquest"},"root":"古法语 conqueste，上承俗拉丁 conquaesita，为拉丁 conquirere「搜寻并取得」的结果名词 = com-「彻底」+ quaerere「寻找」；quaerere 的更深来源不确定。","sensesIntro":{"en":"Eight senses extend one act of taking: a country, the land itself, an obstacle, a heart, a named campaign, a market, the self, and a field of study.","cn":"八个义项伸展自同一个「拿下」动作：拿下国家、拿下土地本身、拿下障碍、拿下人心、拿下有名号的战事、拿下市场、拿下自我、拿下一门学问。"},"semanticMap":{"core":{"en":"CORE IMAGE: a strange flag over an open gate, a siege ladder still leaning on the wall.","cn":"核心意象：敞开的城门上换了一面陌生的旗，攻城梯仍靠在墙边。"},"chain":["SEEK AND GAIN","TAKE BY ARMS","HOLD THE LAND","SEIZE A MARKET","WIN A HEART","MASTER THE SELF"],"branches":[{"senses":"S1 · S5","en":"CAMPAIGN: the general act and the named historical case differ only in whether a chapter title has been given.","cn":"战事：泛指行为与有专名的历史个案，差别只在于是否被写进章节标题。"},{"senses":"S2 · S6","en":"HELD GROUND: a province and a market share are both ground that can be kept or lost.","cn":"被守住的地面：一省土地与一份市场份额，都是可守可失的地面。"},{"senses":"S3 · S8","en":"OBSTACLE AND SKILL: disease, space and a cello all yield to organised effort, which is why war words serve them.","cn":"障碍与技艺：疾病、太空与大提琴都向有组织的努力让步，战争词因此被借用。"},{"senses":"S4","en":"A PERSON AS TERRITORY: courtship borrows the map, and the metaphor is often criticised for it.","cn":"把人当领土：求爱借用了地图，这一比喻也因此常受批评。"},{"senses":"S7","en":"INWARD ENEMY: ascetic writing turns the campaign inside, against the passions.","cn":"内在的敌人：苦修文学把战事转向内部，对准情欲。"}]},"affixes":{"intro":{"en":"Conquest is a Latin result noun whose root of seeking also builds everyday words about questions.","cn":"conquest 是一个拉丁结果名词，其「寻找」词根还构成日常的提问类词。"},"latinIntro":{"en":"Latin quaerere 'to seek' gives quest, question, request, inquire and conquer; the prefix con- adds thoroughness.","cn":"拉丁 quaerere「寻找」给出 quest、question、request、inquire、conquer；前缀 con- 增添「彻底」。"},"items":[{"word":"con-","structure":"com- (Latin prefix, 'together, thoroughly')","meaning":"thoroughly","meaningCN":"彻底；共同","example":"The prefix makes the seeking exhaustive.","exampleCN":"这个前缀让寻找变得彻底。"},{"word":"quaer-","structure":"quaerere (Latin verb, 'to seek, ask')","meaning":"to seek","meaningCN":"寻找；求取","example":"The root supplies the search behind the taking.","exampleCN":"这个词根提供攻取背后的搜寻。"},{"word":"-est","structure":"-estus (Latin result ending, through French)","meaning":"result of an action","meaningCN":"动作的结果","example":"The ending turns the verb into the thing gained.","exampleCN":"这个词尾把动词变成所得之物。"},{"word":"quest","structure":"quaerere through Old French queste","meaning":"a search","meaningCN":"寻找；探寻","example":"The quest for the source took ten years.","exampleCN":"寻找源头用了十年。"},{"word":"conquest","structure":"con- + quaerere + -est","meaning":"the act or land of taking","meaningCN":"征服；被征服之地","example":"The conquest redrew the border.","exampleCN":"这次征服重划了边界。"},{"word":"conquer","structure":"con- + quaerere through French conquerre","meaning":"to take by force","meaningCN":"征服；战胜","example":"They conquered the coast in one campaign.","exampleCN":"他们用一次战役征服了海岸。"},{"word":"conqueror","structure":"conquer + -or","meaning":"one who conquers","meaningCN":"征服者","example":"The conqueror spared the library.","exampleCN":"征服者留下了那座图书馆。"},{"word":"question","structure":"quaerere + -tion","meaning":"a seeking, hence an asking","meaningCN":"问题；疑问","example":"The question had no easy answer.","exampleCN":"这个问题没有简单答案。"},{"word":"request","structure":"re- + quaerere","meaning":"to seek again, hence to ask","meaningCN":"请求","example":"She requested a copy of the map.","exampleCN":"她请求给她一份地图的副本。"},{"word":"inquire","structure":"in- + quaerere","meaning":"to seek into","meaningCN":"询问；查究","example":"They inquired into the loss of the records.","exampleCN":"他们查究档案丢失一事。"}],"latinEntries":[{"word":"quaerere","structure":"quaerere, quaesivi, quaesitum (verb, third conjugation)","meaning":"to seek, ask","meaningCN":"寻找；询问"},{"word":"conquirere","structure":"conquirere, conquisivi, conquisitum (verb, third conjugation)","meaning":"to seek out, gain","meaningCN":"搜寻；取得"},{"word":"conquisitor","structure":"conquisitor, conquisitoris (m., third declension)","meaning":"one who seeks out","meaningCN":"搜寻者；征募者"}]}},{"word":"conquer","ipa_uk":"/ˈkɒŋkə/","ipa_us":"/ˈkɑːŋkər/","definition_zh":"征服；占领；战胜；克服；赢得","definition_en":"to take control of a place or people by force, or to overcome anything that resists","core_image":"一队人翻过最后的山脊，在石堆上插下自己的旗，来路在雾里蜿蜒到看不见的地方","scene":"山口石堆旁，队伍把旗插进碎石，来路在雾中蜿蜒。Rome conquered the region in two campaigns and taxed it for centuries.","sceneCN":"这里 conquer 指「以武力攻取并占领某地」（第 1 个义项：军事征服）；句意为罗马用两次战役征服了这个地区，并对它征税数百年。场景物件：山口石堆、插旗、碎石、雾中路迹。","pos":[{"tag":"v.","zh":"征服；占领；战胜；克服；赢得"}],"collocations":[{"phrase":"conquer territory","zh":"征服领土"},{"phrase":"conquer a country","zh":"征服一个国家"},{"phrase":"conquer fear","zh":"克服恐惧"},{"phrase":"conquer Everest","zh":"登顶珠峰"},{"phrase":"conquer the market","zh":"占领市场"},{"phrase":"conquer a disease","zh":"攻克一种疾病"}],"forms":[{"label":"三单","form":"conquers"},{"label":"过去式","form":"conquered"},{"label":"过去分词","form":"conquered"},{"label":"现在分词","form":"conquering"},{"label":"名词","form":"conquest"},{"label":"指人的名词","form":"conqueror"}],"derivatives":[{"word":"conquest","pos":"n.","zh":"征服；被征服之地"},{"word":"conqueror","pos":"n.","zh":"征服者"},{"word":"conquerable","pos":"adj.","zh":"可征服的"},{"word":"unconquerable","pos":"adj.","zh":"不可征服的"},{"word":"conquering","pos":"adj.","zh":"征服的；制胜的"}],"senses":[{"no":"01","title":"To take a place by force","titleCN":"以武力攻占地区","definition":"to gain control of a country or region by military means","definitionCN":"以军事手段取得对国家或地区的控制","example":"Rome conquered the region in two campaigns and taxed it for centuries.","exampleCN":"罗马用两次战役征服了这个地区，并对它征税数百年。","why":"the oldest English uses are military because the verb came from the language of campaigns and land.","whyCN":"英语最早的用例是军事性的，因为这个动词出自战事与土地的语言。"},{"no":"02","title":"To defeat an enemy","titleCN":"击败对手、敌军","definition":"to beat an opposing force or people in war, without necessarily holding their land","definitionCN":"在战争中击败对方力量或民族，不必占领其土地","example":"The general conquered the raiders but withdrew before winter.","exampleCN":"将军击败了劫掠者，却在入冬前撤走。","why":"beating and holding are two results of one action, and English allows the verb to name either.","whyCN":"击败与占领是同一动作的两种结果，英语让这个动词可以指其中任一种。"},{"no":"03","title":"To overcome a difficulty or disease","titleCN":"克服困难或疾病","definition":"to succeed against an obstacle, illness or natural limitation","definitionCN":"在与障碍、疾病或自然限制的对抗中取得成功","example":"The campaign conquered the disease in a decade but not the fear of it.","exampleCN":"这场运动十年内攻克了那种病，却没有攻克对它的恐惧。","why":"an obstacle behaves like an enemy that will not yield, so the war verb transfers without strain.","whyCN":"障碍的行为像不肯屈服的敌人，因此战争动词毫无阻碍地转移过来。"},{"no":"04","title":"To win someone's affection","titleCN":"赢得某人的爱慕或敬重","definition":"to succeed in winning a person's love or admiration","definitionCN":"成功赢得某人的爱情或倾慕","example":"He conquered the audience with one unscripted story.","exampleCN":"他用一个即兴故事赢得了全场观众。","why":"the metaphor treats a heart as ground to be taken, a usage now often read as too aggressive.","whyCN":"这个比喻把人心当作可取的地面，如今常被视为过于强势。"},{"no":"05","title":"To reach the top of a mountain","titleCN":"登顶山峰","definition":"to succeed in climbing to the summit of a peak","definitionCN":"成功攀上一座山峰的顶点","example":"They conquered the north face after three failed seasons.","exampleCN":"在三个失败季节之后，他们征服了北壁。","why":"climbing borrowed the verb because a mountain refuses, and reaching the top is a kind of victory.","whyCN":"登山借用这个动词，因为山会拒绝人，而到达顶点是一种胜利。"},{"no":"06","title":"To take over a market","titleCN":"占领市场、取得份额","definition":"to gain dominant control of a market, audience or industry","definitionCN":"取得对市场、受众或行业的主导控制","example":"The firm conquered the budget-airline market in five years.","exampleCN":"这家公司在五年内占领了廉价航空市场。","why":"business language uses the campaign shape: share is ground, rivals are armies, and growth is advance.","whyCN":"商业语言沿用战事形状：份额是地面，对手是军队，增长是推进。"},{"no":"07","title":"To master an inner fear","titleCN":"克服内心的恐惧","definition":"to bring one's own fear, anger or habit under control","definitionCN":"把自己的恐惧、愤怒或习惯置于控制之下","example":"She conquered her fear of the water at thirty-eight.","exampleCN":"她在三十八岁克服了对水的恐惧。","why":"the enemy is now inside the person, and the victory is measured by calm rather than ground.","whyCN":"敌人此时在人体内，胜利以平静而非土地来衡量。"},{"no":"08","title":"To master a subject or skill","titleCN":"掌握一门学科或技艺","definition":"to learn a difficult subject or craft well enough to use it with confidence","definitionCN":"把一门困难的学问或手艺学到可以自信运用的程度","example":"He conquered calculus in one summer and physics the next.","exampleCN":"他一个夏天攻克了微积分，第二年攻下了物理。","why":"the same verb serves learning because a hard subject also resists until effort breaks through.","whyCN":"同一个动词可用于学习，因为困难的科目也会抵抗，直到努力突破。"}],"etymology":{"intro":{"en":"Conquer came through Old French conquerre from Latin conquirere 'to seek out and gain'.","cn":"conquer 经古法语 conquerre 来自拉丁 conquirere「搜寻并取得」。"},"items":[{"era":"OLD FRENCH CONQUERRE","en":"Old French conquerre brought the verb into English in the thirteenth century, and its earliest uses are military.","cn":"古法语 conquerre 在 13 世纪把动词带入英语，最早的用法都是军事性的。"},{"era":"LATIN CONQUIRERE","en":"conquirere 'to seek out, procure, gain' joins com- 'thoroughly' to quaerere 'to seek'.","cn":"conquirere「搜寻、取得、赢得」由 com-「彻底」加 quaerere「寻找」构成。"},{"era":"MILITARY CORE","en":"Because gaining was done by force in the contexts where the word was used, taking land became the default sense.","cn":"由于这个词所用的语境里「取得」靠武力完成，攻取土地便成了默认词义。"},{"era":"SPREAD TO OBSTACLES","en":"From battles the verb spread to anything that resists, such as a disease, a mountain, a fear or a market.","cn":"从战役出发，动词扩展到任何抵抗之物：疾病、山峰、恐惧、市场。"},{"era":"ROMANCE SENSE","en":"The sense of winning affection is old in English and treats a heart as territory, a usage now often criticised.","cn":"赢得爱慕这一义在英语里很老，把人心的当作领土，这一用法如今常受批评。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin origin of quaerere is disputed, and the first date of the figurative senses is only approximate.","cn":"来源不确定（更深词源）：quaerere 在拉丁语之前的来源有争议；各比喻义的最早年代也只能约略推定。"}]},"similar":{"note":{"en":"Group one holds the same quaerere stock plus one dangerous look-alike; group two holds the rival verbs of beating and holding.","cn":"第一组同出 quaerere 词干，并含一个易混形近词；第二组是击败与占据的竞争性动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conquest","ipa":"/ˈkɒŋkwest/","tag":"the noun","definition":"The act or the land gained; conquer is what a commander does, conquest is what follows.","definitionCN":"指行为或所得土地；conquer 是统帅所做的，conquest 是随之而来的。"},{"word":"conqueror","ipa":"/ˈkɒŋkərə/","tag":"the person","definition":"The agent noun, marked by -or, for the one who performs the action.","definitionCN":"施事名词，由 -or 标出，指执行动作的人。"},{"word":"concur","ipa":"/kənˈkɜː/","tag":"different root","definition":"From con- plus currere 'to run', meaning to agree or coincide; one letter apart and unrelated in meaning.","definitionCN":"由 con- 加 currere「跑」构成，意为同意或同时发生；只差一个字母，意义无关。"},{"word":"quest","ipa":"/kwest/","tag":"the search itself","definition":"The same root without the prefix, naming a long search rather than a successful taking.","definitionCN":"同一词根不带前缀，指漫长的寻找，而非成功的攻取。"}]},{"heading":"NEAR MEANING","entries":[{"word":"defeat","ipa":"/dɪˈfiːt/","tag":"win the fight","definition":"To beat an opponent in a battle or contest, with no implication of lasting control.","definitionCN":"在战斗或比赛中击败对手，不暗示长久控制。"},{"word":"overcome","ipa":"/ˌəʊvəˈkʌm/","tag":"beat an obstacle or feeling","definition":"The usual verb for getting past a difficulty, fear or illness; less territorial than conquer.","definitionCN":"越过困难、恐惧或疾病的常用动词；比 conquer 少一层领土意味。"},{"word":"occupy","ipa":"/ˈɒkjupaɪ/","tag":"hold with troops","definition":"To station forces in a place and control it, which may happen without a fight.","definitionCN":"派兵驻扎并控制某地，可能未经战斗。"},{"word":"subdue","ipa":"/səbˈdjuː/","tag":"bring under control","definition":"To quiet or master resistance, often by force or authority, without the full campaign image.","definitionCN":"以武力或权威压住抵抗，不含完整的战役意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin root, real relatives and real fixed phrases.","cn":"正常联想：真实的拉丁词根、真实同族词与真实固定搭配。"},"normal":[{"en":"con- 'thoroughly' + quaerere 'seek' = seek until it is yours.","cn":"con-「彻底」+ quaerere「寻找」= 一直寻到它归你为止。"},{"en":"The same root runs through conquest, quest, question, request and inquire.","cn":"同一词根贯穿 conquest、quest、question、request、inquire。"},{"en":"Collocations show the spread: conquer territory, conquer fear, conquer Everest.","cn":"搭配显示扩展：征服领土、克服恐惧、登顶珠峰。"},{"en":"The surname of history is William the Conqueror, dated 1066.","cn":"历史里的名号是征服者威廉，年份一〇六六。"},{"en":"Keep conquer apart from concur, which is about agreement, not taking.","cn":"把 conquer 与 concur 分开，后者讲同意，不讲攻取。"}],"abstract":[{"en":"Picture a flag going into a cairn on a ridge while the road behind disappears in mist.","cn":"想象旗子插进山脊石堆，来路在雾里消失。"},{"en":"Picture a chess king tipped over on its side.","cn":"想象一枚棋子王被推倒侧卧。"},{"en":"Picture a locked door opened by a key found after a long search.","cn":"想象一扇锁着的门，被一枚久寻才得的钥匙打开。"}]},"examples":[{"en":"The empire conquered three neighbours and lost two of them within a century.","cn":"帝国征服了三个邻邦，一个世纪内又丢掉了其中两个。"},{"en":"She conquered the fear of speaking by starting with one sentence a day.","cn":"她每天从一句话开始，克服了当众讲话的恐惧。"},{"en":"No company has conquered this market for longer than a decade.","cn":"没有哪家公司占领这个市场超过十年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康克」听似「扛克」——一路扛过去、克住对方 → 征服、克服","word":"conquer"},"root":"古法语 conquerre，上承拉丁 conquirere「搜寻并取得」= com-「彻底」+ quaerere「寻找」；quaerere 的更深来源不确定。","sensesIntro":{"en":"Eight senses apply one verb of taking to land, enemies, illness, hearts, summits, markets, fear and finally to a hard subject.","cn":"八个义项把同一个「拿下」动词依次用于土地、敌人、疾病、人心、山顶、市场、恐惧，最后用于一门难学的科目。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flag planted in a cairn on the last ridge, the road behind vanishing into mist.","cn":"核心意象：旗子插在最后一道山脊的石堆上，来路在雾中消失。"},"chain":["SEEK AND GAIN","TAKE BY ARMS","DEFEAT AN ENEMY","OVERCOME OBSTACLE","WIN A HEART","MASTER A FIELD"],"branches":[{"senses":"S1 · S2","en":"TAKING AND BEATING: holding ground and beating a force are two outcomes of one campaign verb.","cn":"攻取与击败：守住地面与击败力量，是同一个战事动词的两种结果。"},{"senses":"S3 · S7","en":"OUTER AND INNER OBSTACLE: a disease outside and a fear inside both refuse until effort breaks them.","cn":"外在障碍与内在障碍：身外的疾病与心里的恐惧都抵抗，直到努力突破。"},{"senses":"S4","en":"A HEART AS GROUND: the romantic sense borrows the map and is now often read as aggressive.","cn":"把人心当地面：浪漫义借用了地图，如今常被读作强势。"},{"senses":"S5 · S8","en":"SUMMIT AND SUBJECT: a mountain and a hard discipline both yield to a long climb.","cn":"山顶与科目：山峰与难学的学科都向漫长的攀登让步。"},{"senses":"S6","en":"MARKET: business keeps the campaign shape, with share as ground and rivals as armies.","cn":"市场：商业保留战事形状，份额是地面，对手是军队。"}]},"affixes":{"intro":{"en":"Conquer is a Latin prefixed verb whose root of seeking also builds the language of questions.","cn":"conquer 是一个带前缀的拉丁动词，其「寻找」词根还构成提问类词汇。"},"latinIntro":{"en":"Latin quaerere yields quest, question, request and inquire, while conquirere adds the prefix of thoroughness.","cn":"拉丁 quaerere 衍生 quest、question、request、inquire；conquirere 则加上表「彻底」的前缀。"},"items":[{"word":"con-","structure":"com- (Latin prefix, 'thoroughly')","meaning":"thoroughly, together","meaningCN":"彻底；共同","example":"The prefix marks a completed search.","exampleCN":"这个前缀标出搜寻到底。"},{"word":"quaer-","structure":"quaerere (Latin verb, 'to seek')","meaning":"to seek","meaningCN":"寻找","example":"The root is the search inside the taking.","exampleCN":"这个词根是攻取内部的寻找。"},{"word":"conquer","structure":"con- + quaerere through French","meaning":"to take by force","meaningCN":"征服；战胜","example":"They conquered the valley in a single summer.","exampleCN":"他们一个夏天就征服了山谷。"},{"word":"conquest","structure":"conquer + -st","meaning":"the act or land gained","meaningCN":"征服；被征服之地","example":"The conquest doubled the province.","exampleCN":"这次征服使该省扩大一倍。"},{"word":"conqueror","structure":"conquer + -or","meaning":"one who takes by force","meaningCN":"征服者","example":"The conqueror rebuilt the bridge.","exampleCN":"征服者重建了那座桥。"},{"word":"conquerable","structure":"conquer + -able","meaning":"able to be taken","meaningCN":"可征服的","example":"The fortress was thought conquerable in a week.","exampleCN":"人们原以为这座堡垒一周可下。"},{"word":"unconquerable","structure":"un- + conquerable","meaning":"not able to be taken","meaningCN":"不可征服的","example":"The pass proved unconquerable in winter.","exampleCN":"这道隘口在冬季证明无法攻取。"},{"word":"quest","structure":"quaerere through Old French","meaning":"a search","meaningCN":"探寻","example":"The quest for the well lasted a generation.","exampleCN":"寻找那口井用了一代人。"},{"word":"question","structure":"quaerere + -tion","meaning":"an asking, a doubt","meaningCN":"问题；疑问","example":"The question stopped the meeting.","exampleCN":"那个问题让会议停了下来。"},{"word":"request","structure":"re- + quaerere","meaning":"to ask for","meaningCN":"请求","example":"He requested a map of the pass.","exampleCN":"他索要一份隘口地图。"}],"latinEntries":[{"word":"quaerere","structure":"quaerere, quaesivi, quaesitum (verb, third conjugation)","meaning":"to seek, ask","meaningCN":"寻找；询问"},{"word":"conquirere","structure":"conquirere, conquisivi, conquisitum (verb, third conjugation)","meaning":"to seek out, gain","meaningCN":"搜寻；取得"},{"word":"conquisitor","structure":"conquisitor, conquisitoris (m., third declension)","meaning":"one who seeks out","meaningCN":"搜寻者"}]}},{"word":"conqueror","ipa_uk":"/ˈkɒŋkərə/","ipa_us":"/ˈkɑːŋkərər/","definition_zh":"征服者；占领者；战胜者；（某领域的）攻克者","definition_en":"a person who takes a country or people by force, or who defeats an obstacle, a rival or a disease","core_image":"城头站着披甲的人，脚下是刚换旗的城，城门下列队入城，头盔与肩甲上落满尘土","scene":"城头站着披甲的人，城门下列队入城，头盔与肩甲上落满尘土。The conqueror spared the shrine but emptied its treasury.","sceneCN":"这里 conqueror 指「以武力攻取城池或国家的人」（第 1 个义项：军事征服者）；句意为这位征服者没有毁掉神庙，却把里面的库藏搬空了。场景物件：城头、盔甲、入城队列、神庙门廊。","pos":[{"tag":"n.","zh":"征服者；占领者；战胜者；攻克者"}],"collocations":[{"phrase":"William the Conqueror","zh":"征服者威廉"},{"phrase":"a ruthless conqueror","zh":"冷酷的征服者"},{"phrase":"the conqueror of Everest","zh":"珠峰的征服者"},{"phrase":"conqueror of disease","zh":"战胜疾病的人"},{"phrase":"foreign conquerors","zh":"外来征服者"},{"phrase":"the conqueror's terms","zh":"征服者的条件"}],"forms":[{"label":"复数","form":"conquerors"},{"label":"动词","form":"conquer"},{"label":"名词（行为）","form":"conquest"},{"label":"形容词","form":"conquering"},{"label":"阴性形式（罕见）","form":"conqueress"}],"derivatives":[{"word":"conquer","pos":"v.","zh":"征服；战胜"},{"word":"conquest","pos":"n.","zh":"征服；被征服之地"},{"word":"conquerable","pos":"adj.","zh":"可征服的"},{"word":"unconquerable","pos":"adj.","zh":"不可征服的"}],"senses":[{"no":"01","title":"One who takes a country by force","titleCN":"以武力攻取国家的人","definition":"a person who defeats a state or people and takes control of its land","definitionCN":"击败国家或民族并控制其土地的人","example":"The conqueror spared the shrine but emptied its treasury.","exampleCN":"这位征服者没有毁掉神庙，却把库藏搬空了。","why":"the -or ending marks the agent, so the word names a person where conquest names an act.","whyCN":"-or 词尾标出施事者，因此 conquest 指行为，这个词指人。"},{"no":"02","title":"A ruler known by the title","titleCN":"以「征服者」为称号的君主","definition":"a monarch remembered under that name, as in William the Conqueror","definitionCN":"以这个名号被记住的君主，如征服者威廉","example":"William the Conqueror ordered a survey of every field and pig.","exampleCN":"征服者威廉下令清查每一块田与每一头猪。","why":"a single decisive campaign can become a royal epithet, and history keeps the capital letter.","whyCN":"一次决定性的战事可以变成君主的别号，历史书写保留大写。"},{"no":"03","title":"One who reaches a summit","titleCN":"登上顶峰的人","definition":"a person who succeeds in climbing a mountain or reaching an extreme place","definitionCN":"成功攀上山峰或抵达极端之地的人","example":"The conqueror of the north face refused to name the route.","exampleCN":"这位北壁的征服者拒绝公开路线。","why":"climbing language treats the mountain as an opponent, so the successful climber is its conqueror.","whyCN":"登山语言把山当作对手，成功的攀登者因此成为它的征服者。"},{"no":"04","title":"A winner in competition","titleCN":"比赛中的胜者","definition":"a person who defeats rivals in a contest, especially a long campaign","definitionCN":"在比赛中击败对手的人，尤指漫长赛季","example":"The season's conqueror lost only one match.","exampleCN":"这一赛季的胜者只输过一场。","why":"sport borrows war nouns freely, and a champion is a conqueror of a schedule rather than of land.","whyCN":"体育随意借用战争名词，冠军征服的是赛程而非土地。"},{"no":"05","title":"One who defeats a disease","titleCN":"攻克某种疾病的人或力量","definition":"a person or measure that defeats an illness or a physical limit","definitionCN":"击败某种疾病或身体限制的人或手段","example":"Jenner is remembered as a conqueror of smallpox.","exampleCN":"詹纳被记住为天花的攻克者。","why":"medicine uses the agent noun for the doctor, the vaccine or the campaign, whichever finally wins.","whyCN":"医学用这个施事名词指医生、疫苗或运动，凡是最终取胜者皆可。"},{"no":"06","title":"A seducer, in a crude metaphor","titleCN":"情场上的征服者（带贬义）","definition":"a person who treats romantic success as a series of victories","definitionCN":"把感情上的成功当作一连串胜利的人","example":"He collected the names of every conquest and called himself a conqueror.","exampleCN":"他把每一次得手都记下名字，自称征服者。","why":"the metaphor makes people into territory, and the noun carries that bluntness more than the verb does.","whyCN":"这个比喻把人变成领土，名词比动词更直白地带着这种粗暴。"},{"no":"07","title":"One who masters a field","titleCN":"某领域的开创性掌握者","definition":"a person who opens or dominates a branch of knowledge or craft","definitionCN":"开辟或主导某门学问或技艺的人","example":"She is called a conqueror of the theory, though she prefers the word translator.","exampleCN":"她被称为该理论的征服者，尽管她更愿意被叫作译者。","why":"the last extension keeps only the idea of a decisive personal victory inside a discipline.","whyCN":"最后一层只保留「在某学科内取得决定性个人胜利」这一点。"},{"no":"08","title":"A foreign invader, viewed with hostility","titleCN":"带敌意的外来征服者","definition":"an outside power or its agents seen as illegitimate occupiers","definitionCN":"被视为不正当占领者的外来力量或其代理人","example":"The chronicle lists the foreign conquerors and their taxes in one column.","exampleCN":"编年史把外来征服者与他们的税目列在同一栏。","why":"the noun can shift from praise to blame depending on who is speaking, and the colonised record keeps the blame.","whyCN":"这个名词随说话者从褒转贬，被殖民者的记录保留了那层贬责。"}],"etymology":{"intro":{"en":"Conqueror is the agent noun of conquer, coming through Old French conquerere from Latin conquirere 'to seek out and gain'.","cn":"conqueror 是 conquer 的施事名词，经古法语 conquerere 来自拉丁 conquirere「搜寻并取得」。"},"items":[{"era":"OLD FRENCH CONQUEREOR","en":"Old French conquerere, also spelled conquerour, named the person who won by force and entered English in the thirteenth century.","cn":"古法语 conquerere（亦作 conquerour）指以武力取胜的人，13 世纪进入英语。"},{"era":"LATIN CONQUIRERE","en":"The base is conquirere 'to seek out and gain', com- 'thoroughly' plus quaerere 'to seek'.","cn":"其底是 conquirere「搜寻并取得」，由 com-「彻底」加 quaerere「寻找」构成。"},{"era":"AGENT SUFFIX -OR","en":"The -or ending marks the doer, the same device that makes victor, creator and successor out of verbs.","cn":"-or 词尾标出做动作的人，victor、creator、successor 也由同一手段构成。"},{"era":"ROYAL EPITHET","en":"Norman rulers were called the Conqueror after the eleventh-century conquest, and the capitalised title fixed one decisive image.","cn":"诺曼统治者在 11 世纪征服之后被称为「征服者」，大写称号固定了一个决定性形象。"},{"era":"WIDENING","en":"Modern English applies the word to climbers, champions and doctors who defeat a disease, all agents of a successful struggle.","cn":"现代英语把它用于登山者、冠军与攻克疾病的医生，都是成功斗争的施事者。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English use is dated loosely to the thirteenth century, and the older spelling conquerour was standard before the modern form.","cn":"来源不确定（首见年代）：英语最早用例只能约略定在 13 世纪；旧拼法 conquerour 在现代拼法之前是标准。"}]},"similar":{"note":{"en":"Group one holds the same agent-noun family; group two holds the rival names for winners and takers.","cn":"第一组是同出施事名词词族的词；第二组是胜者与攻取者的竞争性名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conquer","ipa":"/ˈkɒŋkə/","tag":"the verb","definition":"The action itself; the person noun adds -or and becomes a role, a title or an insult.","definitionCN":"动作本身；加 -or 后成为角色、称号或骂名。"},{"word":"conquest","ipa":"/ˈkɒŋkwest/","tag":"the act or land","definition":"The event or the territory, never the person; it also names romantic success more often than the agent noun does.","definitionCN":"指事件或土地，绝不指人；它比施事名词更常指情场得手。"},{"word":"conquerable","ipa":"/ˈkɒŋkərəbl/","tag":"able to be taken","definition":"A passive adjective: it describes ground, not a person.","definitionCN":"被动形容词，描述可被攻取的地面，不描述人。"},{"word":"conquering","ipa":"/ˈkɒŋkərɪŋ/","tag":"the participle","definition":"Used as an adjective for an army or a hero in the act of winning, not as a standing title.","definitionCN":"作形容词指正在取胜的军队或英雄，不是固定称号。"}]},{"heading":"NEAR MEANING","entries":[{"word":"victor","ipa":"/ˈvɪktə/","tag":"winner of the fight","definition":"A winner in a battle or contest; he may leave without holding anything.","definitionCN":"战斗或比赛的胜者；可能什么都不占领就离开。"},{"word":"invader","ipa":"/ɪnˈveɪdə/","tag":"one who enters","definition":"A person or army entering by force, successful or not; conqueror implies success.","definitionCN":"以武力进入的人或军队，成败皆可；conqueror 则含成功。"},{"word":"vanquisher","ipa":"/ˈvæŋkwɪʃə/","tag":"literary defeater","definition":"A formal or literary word for one who defeats, with no territorial claim.","definitionCN":"正式或文学的「击败者」，不含领土主张。"},{"word":"champion","ipa":"/ˈtʃæmpiən/","tag":"winner of a contest","definition":"The winner of a competition or a cause's defender, never of a country.","definitionCN":"比赛胜者或某项事业的捍卫者，从不指国家的攻取者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real agent suffix, a real title and real modern extensions.","cn":"正常联想：真实的施事后缀、真实称号与真实现代扩展。"},"normal":[{"en":"conquer + -or: the suffix marks the person, as in victor and creator.","cn":"conquer + -or：后缀标出人，如 victor 与 creator。"},{"en":"William the Conqueror, 1066, is the title that fixed the capital letter.","cn":"征服者威廉，一〇六六，是固定大写用法的称号。"},{"en":"The family runs conquer, conquest, conqueror, conquerable, unconquerable.","cn":"同族词包括 conquer、conquest、conqueror、conquerable、unconquerable。"},{"en":"Modern phrases stretch it: the conqueror of Everest, a conqueror of smallpox.","cn":"现代搭配把它拉长：珠峰的征服者、天花的攻克者。"},{"en":"The same noun can praise or blame, depending on who writes the chronicle.","cn":"同一个名词可褒可贬，取决于谁写编年史。"}],"abstract":[{"en":"Picture armour coated with dust on a captured gate tower.","cn":"想象落满尘土的盔甲立在刚夺下的城门楼上。"},{"en":"Picture a boot planted on a summit cairn.","cn":"想象一只靴子踩在山顶石堆上。"},{"en":"Picture a ring of keys, each opening a door someone else built.","cn":"想象一串钥匙，每一把都开着一扇别人造的门。"}]},"examples":[{"en":"The conqueror's terms were light on paper and heavy in practice.","cn":"征服者的条件写在纸上很轻，落到实处很重。"},{"en":"The conqueror of the north face spent one night on the summit.","cn":"这位北壁的征服者在峰顶待了一夜。"},{"en":"Historians now describe the conquerors as occupiers with a better press.","cn":"史家如今把这些征服者描述为宣传更好的占领者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康克勒」听似「扛克了」——把对方克住的人 → 征服者","word":"conqueror"},"root":"conquer 的施事名词，经古法语 conquerere（亦作 conquerour），上承拉丁 conquirere「搜寻并取得」= com-「彻底」+ quaerere「寻找」+ -or 施事后缀。","sensesIntro":{"en":"Eight senses follow one person through different arenas: a country, a royal title, a summit, a contest, a disease, a heart, a discipline and, from the other side, an occupier.","cn":"八个义项让同一个人穿过不同场地：国家、君主称号、山顶、赛场、疾病、人心、学科，最后从被征服者一面看，是占领者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dust-covered figure in armour standing on a gate tower just taken.","cn":"核心意象：一个满身尘土的披甲者站在刚夺下的城门楼上。"},"chain":["TAKE BY FORCE","BEAR THE TITLE","CLIMB THE PEAK","WIN THE MATCH","BEAT DISEASE","WIN A HEART"],"branches":[{"senses":"S1 · S2","en":"PERSON AND TITLE: the ordinary agent and the royal epithet are the same role, one generic and one capitalised.","cn":"人与称号：普通的施事者与君主别号是同一角色，一为泛指，一为大写。"},{"senses":"S3 · S8","en":"SUMMIT AND OCCUPIER: a climber conquers a mountain; a native record calls the same figure an occupier.","cn":"山顶与占领者：登山者征服山；当地记录则把同一形象称作占领者。"},{"senses":"S4","en":"CONTEST: sport turns a season into a campaign and its winner into a conqueror.","cn":"赛场：体育把一个赛季变成战役，把胜者变成征服者。"},{"senses":"S5 · S7","en":"DISEASE AND DISCIPLINE: a vaccine and a theorist both defeat something that would not yield.","cn":"疾病与学科：疫苗与理论家都在击败不肯让步之物。"},{"senses":"S6","en":"HEART: the crudest use turns people into territory and keeps the noun's bluntness.","cn":"人心：最粗的用法把人变成领土，并保留名词的直白。"}]},"affixes":{"intro":{"en":"Conqueror adds a Latin agent suffix to a Latin verb of seeking, so the whole word can be read as 'the one who seeks until he gains'.","cn":"conqueror 在拉丁「寻找」动词上加拉丁施事后缀，整词可读作「寻到取得为止的那个人」。"},"latinIntro":{"en":"Latin quaerere 'to seek' and conquirere 'to gain' supply the verb, and -or supplies the person; the same suffix builds victor and creator.","cn":"拉丁 quaerere「寻找」与 conquirere「取得」提供动词，-or 提供人；同一后缀构成 victor 与 creator。"},"items":[{"word":"con-","structure":"com- (Latin prefix, 'thoroughly')","meaning":"thoroughly","meaningCN":"彻底","example":"The prefix marks a completed gaining.","exampleCN":"这个前缀标出「取得到底」。"},{"word":"quaer-","structure":"quaerere (Latin verb, 'to seek')","meaning":"to seek","meaningCN":"寻找","example":"The root supplies the search.","exampleCN":"这个词根提供寻找。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix also builds victor and successor.","exampleCN":"这个后缀还构成 victor 与 successor。"},{"word":"conquer","structure":"con- + quaerere","meaning":"to take by force","meaningCN":"征服；战胜","example":"He conquered the eastern shore.","exampleCN":"他征服了东岸。"},{"word":"conquest","structure":"conquer + -st","meaning":"the act or the land","meaningCN":"征服；被征服之地","example":"The conquest took a single season.","exampleCN":"这次征服只用了一个季节。"},{"word":"conqueror","structure":"conquer + -or","meaning":"one who takes","meaningCN":"征服者","example":"The conqueror rebuilt the walls.","exampleCN":"征服者重建了城墙。"},{"word":"conqueress","structure":"conqueror + -ess","meaning":"a rare feminine form","meaningCN":"女征服者（罕见）","example":"The conqueress appears in one old ballad.","exampleCN":"这位女征服者只在一首旧歌谣里出现。"},{"word":"conquerable","structure":"conquer + -able","meaning":"able to be taken","meaningCN":"可征服的","example":"The island looked conquerable from the sea.","exampleCN":"从海上看，这座岛似乎可下。"},{"word":"unconquerable","structure":"un- + conquerable","meaning":"never taken","meaningCN":"不可征服的","example":"The ridge was called unconquerable.","exampleCN":"那道山脊曾被称为不可征服。"}],"latinEntries":[{"word":"quaerere","structure":"quaerere, quaesivi, quaesitum (verb, third conjugation)","meaning":"to seek, ask","meaningCN":"寻找；询问"},{"word":"conquirere","structure":"conquirere, conquisivi, conquisitum (verb, third conjugation)","meaning":"to seek out, gain","meaningCN":"搜寻；取得"},{"word":"conquisitor","structure":"conquisitor, conquisitoris (m., third declension)","meaning":"one who seeks out","meaningCN":"搜寻者"}]}},{"word":"invasion","ipa_uk":"/ɪnˈveɪʒn/","ipa_us":"/ɪnˈveɪʒn/","definition_zh":"入侵；侵略；涌入；侵扰；（医学）侵袭","definition_en":"the entry of an armed force into another country, or any unwanted mass entry or spread","core_image":"拂晓前的海滩，登陆艇成排靠岸，跳板放下，沙上留下一条条新踩出的路，雾还没散","scene":"拂晓前的海滩，登陆艇成排靠岸，雾里只见跳板与脚印。The invasion began before dawn, with landing craft running through fog.","sceneCN":"这里 invasion 指「武装力量进入他国领土的军事行动」（第 1 个义项：军事入侵）；句意为入侵在黎明前开始，登陆艇穿过浓雾靠岸。场景物件：登陆艇、跳板、沙滩脚印、雾。","pos":[{"tag":"n.","zh":"入侵；侵略；涌入；侵扰；侵袭"}],"collocations":[{"phrase":"military invasion","zh":"军事入侵"},{"phrase":"the invasion of privacy","zh":"对隐私的侵犯"},{"phrase":"a tourist invasion","zh":"游客大批涌入"},{"phrase":"invasion of weeds","zh":"杂草的蔓延"},{"phrase":"the Norman invasion","zh":"诺曼人的入侵"},{"phrase":"an invasion of pests","zh":"害虫侵袭"}],"forms":[{"label":"复数","form":"invasions"},{"label":"动词","form":"invade"},{"label":"指人的名词","form":"invader"},{"label":"形容词","form":"invasive"},{"label":"名词（侵入性；扩散性）","form":"invasiveness"}],"derivatives":[{"word":"invade","pos":"v.","zh":"入侵；涌入；侵扰"},{"word":"invader","pos":"n.","zh":"入侵者"},{"word":"invasive","pos":"adj.","zh":"侵入的；蔓延的"},{"word":"invasiveness","pos":"n.","zh":"侵入性；扩散性"},{"word":"non-invasive","pos":"adj.","zh":"非侵入性的"}],"senses":[{"no":"01","title":"An armed entry into another country","titleCN":"军事入侵","definition":"the act of sending armed forces into a country to occupy or attack it","definitionCN":"派武装力量进入他国以占领或攻击的行为","example":"The invasion began before dawn, with landing craft running through fog.","exampleCN":"入侵在黎明前开始，登陆艇穿过浓雾靠岸。","why":"invadere means 'to go into', and the military sense is simply the largest and most violent kind of going in.","whyCN":"invadere 意为「走进去」，军事义只是这种「进入」中规模最大、最暴烈的一种。"},{"no":"02","title":"A mass arrival of people","titleCN":"人潮大批涌入","definition":"the sudden arrival of very large numbers of people in one place","definitionCN":"极大量人群突然抵达某地","example":"The summer invasion of camper vans fills every lay-by by noon.","exampleCN":"夏季涌入的露营车到中午就把每个路边停车带占满。","why":"the word keeps the shape of entry and adds numbers, so holiday crowds can be described as an invasion.","whyCN":"这个词保留「进入」的形状再加上数量，于是度假人潮也可被说成入侵。"},{"no":"03","title":"The spread of something harmful","titleCN":"有害物的蔓延","definition":"the rapid spread of weeds, insects or other unwanted organisms into a place","definitionCN":"杂草、昆虫等不受欢迎的生物迅速扩散到某地","example":"The invasion of knotweed closed the towpath for two summers.","exampleCN":"蓼草的蔓延让纤道关闭了两个夏天。","why":"ecology borrowed the military noun because a new species takes ground much as an army does.","whyCN":"生态学借用这个军事名词，因为新物种占领地面，方式与军队相似。"},{"no":"04","title":"Intrusion into private space","titleCN":"对隐私或私人空间的侵扰","definition":"an unwanted entry into a person's private life, body or attention","definitionCN":"对个人私生活、身体或注意力的不请自来","example":"The cameras were an invasion of the family's quietest hours.","exampleCN":"那些镜头侵入了这家人最安静的时刻。","why":"modern privacy law fixed the phrase invasion of privacy, which extends the word from land to the self.","whyCN":"现代隐私法固定了「侵犯隐私」这一说法，把这个词从土地扩展到人身。"},{"no":"05","title":"Medical spread into tissue","titleCN":"医学上的侵袭","definition":"the movement of cancer or infection into surrounding tissue","definitionCN":"癌或感染向周围组织移动","example":"The scan showed invasion of the nearby lymph nodes.","exampleCN":"扫描显示病变已侵袭附近的淋巴结。","why":"medicine uses the word for anything that crosses a boundary it should not cross.","whyCN":"医学用这个词指任何越过本不该越过之边界的病变。"},{"no":"06","title":"Biological invasion by a new species","titleCN":"外来物种的入侵","definition":"the establishment and spread of a non-native species in a new habitat","definitionCN":"非本地物种在新栖息地立足并扩散","example":"The invasion of the lake by zebra mussels changed its water clarity.","exampleCN":"斑马贻贝入侵这座湖，改变了水的清澈度。","why":"conservation biology made this a standing term, distinct from a single arrival.","whyCN":"保护生物学把它固定为术语，以区别于单次的到来。"},{"no":"07","title":"Encroachment on rights or customs","titleCN":"对权利或习俗的侵犯","definition":"the gradual or open taking over of a right, custom or sphere of authority","definitionCN":"对某项权利、习俗或权限范围的逐步或公开侵占","example":"The guild called the new levy an invasion of its ancient privileges.","exampleCN":"行会称新税是对其古老特权的侵犯。","why":"legal and political speech treat rights as ground, so any encroachment becomes an invasion.","whyCN":"法律与政治语言把权利当作地面，任何侵占于是都成了入侵。"},{"no":"08","title":"A named historical campaign","titleCN":"有专名的历史入侵","definition":"a particular invasion remembered under a name and a date","definitionCN":"以名号与年代被记住的某次入侵","example":"The Norman invasion of 1066 changed the language of the court.","exampleCN":"一〇六六年的诺曼入侵改变了宫廷的语言。","why":"historians turn one campaign into a proper name, and the common noun becomes a heading in a textbook.","whyCN":"史家把一次战事变成专名，普通名词于是成了教科书里的标题。"}],"etymology":{"intro":{"en":"Invasion is Latin invasio, the noun of invadere 'to go into', built on in- 'into' and vadere 'to go'.","cn":"invasion 是拉丁 invasio，即 invadere「走进去」的名词，由 in-「进入」与 vadere「走」构成。"},"items":[{"era":"LATIN INVADERE","en":"invadere meant 'to go into, enter upon, attack', a plain verb of movement that took on a hostile colour in military contexts.","cn":"invadere 意为「走进去、进入、攻击」，本是一个朴素的移动动词，在军事语境中带上敌意。"},{"era":"IN PLUS VADERE","en":"in- 'into' plus vadere 'to go, advance' produced the verb; vadere also gives evade and evasion with the opposite prefix.","cn":"in-「进入」加 vadere「走、前进」构成该动词；vadere 加相反前缀还给出 evade 与 evasion。"},{"era":"LATIN INVASIO","en":"invasio named a going in or an attack, and English borrowed it in the fifteenth century as a legal and military term.","cn":"invasio 指进入或攻击，英语在 15 世纪把它作为法律与军事术语借入。"},{"era":"MEDICINE AND ECOLOGY","en":"Nineteenth and twentieth-century medicine applied it to disease spreading into tissue, and biology to species entering new ground.","cn":"19 与 20 世纪的医学用它指疾病侵入组织，生物学用它指物种进入新地面。"},{"era":"EVERYDAY USE","en":"In ordinary speech an invasion can be any unwelcome mass arrival, from tourists to messages.","cn":"在日常口语里，入侵可以是任何不受欢迎的大批到来，从游客到信息。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of vadere is unsettled, and any older form cited for it is a reconstruction.","cn":"来源不确定（更深词源）：vadere 在拉丁语之前的来源没有定论，为其引用的更早形式属重构。"}]},"similar":{"note":{"en":"Group one holds the same vadere stock, including one opposite; group two holds the rival words for hostile entry.","cn":"第一组同出 vadere 词干，并含一个反方向词；第二组是敌意进入的竞争性说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"invade","ipa":"/ɪnˈveɪd/","tag":"the verb","definition":"The action behind the noun; invasion is the event or the campaign seen as a whole.","definitionCN":"名词背后的动作；invasion 是把整件事或整场战事看作一个整体。"},{"word":"invasive","ipa":"/ɪnˈveɪsɪv/","tag":"the adjective","definition":"Describes something that spreads where it is not wanted, especially a plant, a species or a procedure.","definitionCN":"形容在不受欢迎之处扩散之物，尤指植物、物种或医疗操作。"},{"word":"evasion","ipa":"/ɪˈveɪʒn/","tag":"opposite prefix, escape","definition":"From e- 'out' plus vadere, a going out, hence avoidance; it looks like invasion's mirror.","definitionCN":"由 e-「向外」加 vadere 构成，指走出去，故为逃避；它像 invasion 的镜像。"},{"word":"evade","ipa":"/ɪˈveɪd/","tag":"opposite verb","definition":"To get out of the way of something, built on the same root with the opposite prefix.","definitionCN":"躲开某物，用同一词根加相反前缀构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"incursion","ipa":"/ɪnˈkɜːʃn/","tag":"brief raid","definition":"A short entry into hostile territory, often ending in withdrawal; invasion implies a larger plan.","definitionCN":"短暂进入敌方领土，常以撤出结束；invasion 暗示更大计划。"},{"word":"raid","ipa":"/reɪd/","tag":"sudden attack","definition":"A quick attack on a place, with no intention of holding it.","definitionCN":"对某地的快速攻击，无意占领。"},{"word":"intrusion","ipa":"/ɪnˈtruːʒn/","tag":"unwelcome personal entry","definition":"Entry into privacy, conversation or space, usually without violence.","definitionCN":"对隐私、谈话或空间的闯入，通常不带暴力。"},{"word":"encroachment","ipa":"/ɪnˈkrəʊtʃmənt/","tag":"gradual taking","definition":"A slow advance on land, rights or time, step by step rather than in one campaign.","definitionCN":"对土地、权利或时间的缓慢推进，逐步而非一次战事。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin verb, a real opposite and real technical branches.","cn":"正常联想：真实的拉丁动词、真实的反向词与真实技术分支。"},"normal":[{"en":"in- 'into' + vadere 'go' = a going in, which is the whole word.","cn":"in-「进入」+ vadere「走」= 走进去，整词就是这个动作。"},{"en":"evade and evasion reverse the prefix: going out instead of in.","cn":"evade 与 evasion 反转前缀：向外走而非向内。"},{"en":"The family runs invade, invasion, invasive, invader, invasiveness.","cn":"同族词包括 invade、invasion、invasive、invader、invasiveness。"},{"en":"Fixed phrases sort the branches: military invasion, invasion of privacy, invasion of weeds.","cn":"固定搭配分出各支：军事入侵、侵犯隐私、杂草蔓延。"},{"en":"History supplies the proper name: the Norman invasion of 1066.","cn":"历史提供专名：一〇六六年的诺曼入侵。"}],"abstract":[{"en":"Picture landing craft in rows on a foggy beach at first light.","cn":"想象拂晓雾中成排靠岸的登陆艇。"},{"en":"Picture ivy crossing a garden wall in one season.","cn":"想象常春藤一个季节就翻过花园的墙。"},{"en":"Picture a crowd pressing through a single open turnstile.","cn":"想象人群挤过唯一开着的闸口。"}]},"examples":[{"en":"The invasion lasted three weeks and the occupation three decades.","cn":"入侵持续三周，占领持续三十年。"},{"en":"Readers called the new tracking rule an invasion of privacy.","cn":"读者称新的追踪规则侵犯了隐私。"},{"en":"The invasion of the marsh by reeds changed the bird count.","cn":"芦苇侵入这片沼泽，改变了鸟类数量。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因维申」听似「硬围身」——硬闯进来围住别人 → 入侵、涌入","word":"invasion"},"root":"拉丁 invasio「进入、攻击」= in-「进入」+ vadere「走、前进」+ -sio 名词后缀；vadere 在拉丁语之前的来源不确定。","sensesIntro":{"en":"Eight senses follow one kind of entry: armed forces into a country, crowds into a place, weeds into a field, cameras into a life, cancer into tissue, a species into a habitat, a power into a right, and one named campaign into the history books.","cn":"八个义项沿着同一种「进入」展开：军队进入国家、人潮进入地方、杂草进入田地、镜头进入生活、癌进入组织、物种进入栖息地、权力进入权利，最后是一次有专名的战事进入史书。"},"semanticMap":{"core":{"en":"CORE IMAGE: landing craft in rows on a foggy beach before sunrise.","cn":"核心意象：日出前的雾中，登陆艇成排靠上海滩。"},"chain":["GO IN","ARMED ENTRY","CROWD ENTRY","HARMFUL SPREAD","SPECIES SPREAD","PRIVATE INTRUSION"],"branches":[{"senses":"S1 · S8","en":"CAMPAIGN: the general armed entry and the named historical case are the same act, one generic and one dated.","cn":"战事：泛指的武装进入与有专名的历史个案是同一行为，一为泛指，一为有年代。"},{"senses":"S2 · S7","en":"ENTERING WHAT IS NOT YOURS: holiday crowds and new levies both cross a boundary others rely on.","cn":"进入不属于自己的地方：度假人潮与新税都越过了别人赖以立身的界线。"},{"senses":"S3 · S6","en":"LIVING SPREAD: weeds and non-native species take ground slowly and hold it.","cn":"活的扩散：杂草与外来物种缓慢占地并守住。"},{"senses":"S4","en":"PRIVACY: the camera moves the word from land to the person.","cn":"隐私：镜头把这个词从土地移到人身。"},{"senses":"S5","en":"TISSUE: medicine names any crossing of a boundary that should hold.","cn":"组织：医学用它指任何越过本应守住的边界。"}]},"affixes":{"intro":{"en":"Invasion is a Latin action noun built from a prefix of entry and a verb of going, and the same pieces build its own opposite.","cn":"invasion 是一个拉丁动作名词，由表进入的前缀与「走」动词构成，同样的部件还构成它的反义词。"},"latinIntro":{"en":"Latin vadere 'to go' gives invade, invasion, evasive and evade, and invadere 'to go into' supplies the hostile sense.","cn":"拉丁 vadere「走」给出 invade、invasion、evasive、evade；invadere「走进去」提供敌意义。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'into')","meaning":"into","meaningCN":"进入","example":"The prefix gives the movement its direction.","exampleCN":"这个前缀给移动一个方向。"},{"word":"vad-","structure":"vadere (Latin verb, 'to go, advance')","meaning":"to go","meaningCN":"走；前进","example":"The root supplies the plain motion.","exampleCN":"这个词根提供朴素的动作。"},{"word":"-sion","structure":"-sio, -sionis (Latin noun suffix)","meaning":"act or result","meaningCN":"动作或结果","example":"The suffix makes an event noun from the verb.","exampleCN":"这个后缀把动词变成事件名词。"},{"word":"invade","structure":"in- + vadere","meaning":"to enter by force","meaningCN":"入侵；涌入","example":"Tourists invade the old town each August.","exampleCN":"每年八月游客涌入老城。"},{"word":"invasion","structure":"invade + -sion","meaning":"an entry by force or in numbers","meaningCN":"入侵；涌入","example":"The invasion stopped at the river.","exampleCN":"入侵止于河边。"},{"word":"invasive","structure":"invasion + -ive","meaning":"spreading where unwanted","meaningCN":"侵入性的；蔓延的","example":"The invasive reed choked the channel.","exampleCN":"这种入侵性芦苇堵塞了水道。"},{"word":"invader","structure":"invade + -er","meaning":"one who enters by force","meaningCN":"入侵者","example":"The invaders burned the bridge.","exampleCN":"入侵者烧掉了桥。"},{"word":"evade","structure":"e- + vadere","meaning":"to go out, escape","meaningCN":"逃避；躲开","example":"The clause lets firms evade the levy.","exampleCN":"这项条款让公司得以逃避征税。"},{"word":"evasion","structure":"evade + -sion","meaning":"an escape, an avoidance","meaningCN":"逃避；规避","example":"Tax evasion carries a heavy penalty.","exampleCN":"逃税处罚很重。"},{"word":"evasive","structure":"evasion + -ive","meaning":"tending to avoid","meaningCN":"回避的；躲闪的","example":"His evasive answer told us nothing.","exampleCN":"他躲闪的回答什么也没说明。"}],"latinEntries":[{"word":"vadere","structure":"vadere, vasi, vasum (verb, third conjugation)","meaning":"to go, advance","meaningCN":"走；前进"},{"word":"invadere","structure":"invadere, invasi, invasum (verb, third conjugation)","meaning":"to go into, attack","meaningCN":"走进去；攻击"},{"word":"invasio","structure":"invasio, invasionis (f., third declension)","meaning":"an entering, an attack","meaningCN":"进入；攻击"},{"word":"invasor","structure":"invasor, invasoris (m., third declension)","meaning":"one who enters by force","meaningCN":"侵入者"}]}},{"word":"invade","ipa_uk":"/ɪnˈveɪd/","ipa_us":"/ɪnˈveɪd/","definition_zh":"入侵；侵略；涌入；侵扰；侵袭","definition_en":"to enter a country with armed force, or to enter any place, space or body in unwanted numbers","core_image":"一扇半开的窗，风把落叶与尘土推进屋里，桌上的纸页被一片片掀动","scene":"荒废的果园里，藤蔓从篱笆缺口爬进来，把果树的支架缠成一片。Weeds invaded the abandoned orchard within two seasons.","sceneCN":"这里 invade 指「有害物大量蔓延进入某个区域」（第 4 个义项：杂草、害虫等的侵入）；句意为两个季节之内杂草就侵入了这座荒废的果园。场景物件：篱笆缺口、藤蔓、果树支架、落叶。","pos":[{"tag":"v.","zh":"入侵；侵略；涌入；侵扰；侵袭"}],"collocations":[{"phrase":"invade a country","zh":"入侵一个国家"},{"phrase":"invade someone's privacy","zh":"侵犯某人的隐私"},{"phrase":"invasive species","zh":"入侵物种"},{"phrase":"invade the market","zh":"抢占市场"},{"phrase":"invade someone's time","zh":"占用某人的时间"},{"phrase":"tumours invade tissue","zh":"肿瘤侵袭组织"}],"forms":[{"label":"三单","form":"invades"},{"label":"过去式","form":"invaded"},{"label":"过去分词","form":"invaded"},{"label":"现在分词","form":"invading"},{"label":"名词","form":"invasion"},{"label":"形容词","form":"invasive"}],"derivatives":[{"word":"invasion","pos":"n.","zh":"入侵；涌入；侵袭"},{"word":"invader","pos":"n.","zh":"入侵者"},{"word":"invasive","pos":"adj.","zh":"侵入的；蔓延的"},{"word":"invasiveness","pos":"n.","zh":"侵入性；扩散性"},{"word":"non-invasive","pos":"adj.","zh":"非侵入性的"}],"senses":[{"no":"01","title":"To enter a country with force","titleCN":"以武力入侵他国","definition":"to send armed forces into another country in order to attack or occupy it","definitionCN":"派武装力量进入他国以攻击或占领","example":"The fleet invaded the island at dawn and held the port by noon.","exampleCN":"舰队黎明入侵该岛，中午就控制了港口。","why":"invadere is a plain 'go into', and the hostile sense comes from the armed company that does the going.","whyCN":"invadere 本只是「走进去」，敌意义来自做这件事的武装队伍。"},{"no":"02","title":"To enter in large numbers","titleCN":"大批涌入","definition":"to enter a place in very large numbers, often in a way that overwhelms it","definitionCN":"极大量进入某地，常令当地不堪承受","example":"Fans invaded the square an hour before the match.","exampleCN":"比赛开始前一小时，球迷就涌满了广场。","why":"numbers alone can turn entry into invasion, because the place is no longer able to receive them.","whyCN":"仅数量就能把进入变成入侵，因为那地方已接不住这么多人。"},{"no":"03","title":"To encroach on time or space","titleCN":"侵占私人时间或空间","definition":"to take over a person's time, attention or room without invitation","definitionCN":"未经邀请就占用他人的时间、注意力或空间","example":"Meetings invaded every evening of the project.","exampleCN":"会议侵占了项目的每个晚上。","why":"the metaphor moves the border inward, so a calendar or a desk becomes territory that can be crossed.","whyCN":"比喻把边界移向内部，于是日程表或书桌成了可被越过的领土。"},{"no":"04","title":"To spread through a place as a weed or pest","titleCN":"有害物蔓延侵入","definition":"to spread into a habitat and take it over, as an aggressive plant, insect or fungus does","definitionCN":"像强势植物、昆虫或真菌那样扩散进栖息地并占据","example":"Weeds invaded the abandoned orchard within two seasons.","exampleCN":"两个季节之内杂草就侵入了这座荒废的果园。","why":"ecology uses the verb because the spread is one-directional and hard to reverse, like a campaign.","whyCN":"生态学用这个动词，因为这种扩散是单向且难以逆转的，像一场战事。"},{"no":"05","title":"To spread into body tissue","titleCN":"病变侵袭组织","definition":"to move into surrounding tissue, as a tumour or an infection does","definitionCN":"如肿瘤或感染那样进入周围组织","example":"The tumour invaded the muscle before it was found.","exampleCN":"肿瘤在被发现之前就已侵入肌肉。","why":"medicine keeps the boundary image: healthy tissue is territory, and the disease crosses into it.","whyCN":"医学保留边界意象：健康组织是领土，疾病越界进入。"},{"no":"06","title":"To take over a market","titleCN":"抢占市场","definition":"to enter and dominate a market or an audience held by others","definitionCN":"进入并主导他人占据的市场或受众","example":"Discount chains invaded the high street within a decade.","exampleCN":"折扣连锁十年内就占领了商业街。","why":"business copies the military shape, with existing shops as ground already held.","whyCN":"商业复制军事形状，已有的店铺就是被占住的地面。"},{"no":"07","title":"To violate rights or customs","titleCN":"侵犯权利或习俗","definition":"to cross into a sphere of rights, customs or authority that belongs to others","definitionCN":"越入属于他人的权利、习俗或权限范围","example":"The new rule invaded customs the village had kept for centuries.","exampleCN":"新规侵犯了这座村子守了几个世纪的习俗。","why":"rights behave like land in legal speech, so any crossing is an invasion.","whyCN":"法律语言里权利的行为像土地，任何越界都是入侵。"},{"no":"08","title":"Of a feeling: to fill the mind","titleCN":"情绪突然占据心头","definition":"to fill a person's mind suddenly and completely, as a feeling or a thought does","definitionCN":"如情绪或念头那样突然而彻底地占据人的心头","example":"A doubt invaded his mind at the worst possible moment.","exampleCN":"一个疑问在最不合适的时刻占据了他的心。","why":"the last extension removes the outside world: what enters is a feeling, and the territory is the self.","whyCN":"最后一层扩展去掉外部世界：进入的是情绪，领土是自我。"}],"etymology":{"intro":{"en":"Invade is Latin invadere 'to go into, enter upon, attack', built on in- 'into' and vadere 'to go'.","cn":"invade 是拉丁 invadere「走进去、进入、攻击」，由 in-「进入」与 vadere「走」构成。"},"items":[{"era":"LATIN INVADERE","en":"invadere meant 'to go into, enter upon', and in military writing it took the sense of attacking.","cn":"invadere 意为「走进去、进入」，在军事书写中带上攻击义。"},{"era":"IN PLUS VADERE","en":"in- 'into' plus vadere 'to go, advance'; the same root with e- 'out' gives evade.","cn":"in-「进入」加 vadere「走、前进」；同一词根加 e-「向外」给出 evade。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"The verb appears in English in the sixteenth century, at first for hostile entry into another country.","cn":"这个动词在 16 世纪出现于英语，最初指敌意进入他国。"},{"era":"SPREAD OF SENSES","en":"Later it covered crowds, weeds, disease and markets, all entering where they are not wanted.","cn":"后来它覆盖人潮、杂草、疾病与市场，都是进入不受欢迎之处。"},{"era":"MODERN RANGE","en":"Today invade is common in medicine, ecology, business and everyday complaints about tourists or noise.","cn":"今天 invade 常见于医学、生态、商业，以及关于游客或噪音的日常抱怨。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the origin of vadere before Latin is disputed, and the proposed older root is a reconstruction.","cn":"来源不确定（更深词源）：vadere 在拉丁语之前的来源有争议，所提更早词根属重构。"}]},"similar":{"note":{"en":"Group one holds the same vadere stock, including the opposite prefix; group two holds verbs of hostile or gradual entry.","cn":"第一组同出 vadere 词干，并含相反前缀者；第二组是敌意进入或逐步进入的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"evade","ipa":"/ɪˈveɪd/","tag":"opposite direction","definition":"E- 'out' plus vadere, to go out of the way, hence to escape; the mirror image of invade.","definitionCN":"e-「向外」加 vadere，走出路外，故为逃避；是 invade 的镜像。"},{"word":"evasion","ipa":"/ɪˈveɪʒn/","tag":"the noun of escape","definition":"The act of avoiding a duty, a question or a blow, built on the same root.","definitionCN":"逃避义务、问题或打击的行为，同出这一词根。"},{"word":"invasive","ipa":"/ɪnˈveɪsɪv/","tag":"the adjective","definition":"Describes a species, a test or a manner that spreads into what is not its own.","definitionCN":"形容物种、检查或方式扩散进不属于它的地方。"},{"word":"invasion","ipa":"/ɪnˈveɪʒn/","tag":"the event noun","definition":"The whole entry seen as one happening, from an army to a crowd.","definitionCN":"把整次进入看作一个事件，从军队到人群皆可。"}]},{"heading":"NEAR MEANING","entries":[{"word":"attack","ipa":"/əˈtæk/","tag":"strike, not necessarily enter","definition":"To begin fighting against someone; the attacker may never cross a border.","definitionCN":"开始对某人作战；攻击者可能从未越过边界。"},{"word":"intrude","ipa":"/ɪnˈtruːd/","tag":"enter where unwelcome","definition":"To put oneself into a place, conversation or life without invitation.","definitionCN":"未经邀请就进入某地、谈话或他人生活。"},{"word":"overrun","ipa":"/ˌəʊvəˈrʌn/","tag":"spread over in numbers","definition":"To spread over a place quickly and in large numbers, often of pests or troops.","definitionCN":"以大量迅速铺满某地，常用于害虫或军队。"},{"word":"encroach","ipa":"/ɪnˈkrəʊtʃ/","tag":"advance by steps","definition":"To move gradually onto land, rights or time that belong to another.","definitionCN":"逐步推进到属于他人的土地、权利或时间上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin verb, a real opposite and real branch phrases.","cn":"正常联想：真实的拉丁动词、真实反向词与真实分支搭配。"},"normal":[{"en":"in- 'into' + vadere 'go' = go in, the whole verb in two pieces.","cn":"in-「进入」+ vadere「走」= 走进去，两个部件就是整词。"},{"en":"evade is the mirror: e- 'out' instead of in.","cn":"evade 是镜像：用 e-「向外」而不是向内。"},{"en":"The family runs invade, invasion, invader, invasive, invasiveness.","cn":"同族词包括 invade、invasion、invader、invasive、invasiveness。"},{"en":"Technical phrases show the spread: invasive species, tumours invade tissue.","cn":"技术搭配显示扩展：入侵物种、肿瘤侵袭组织。"},{"en":"Everyday phrases show the metaphor: invade someone's privacy, invade someone's time.","cn":"日常搭配显示比喻：侵犯隐私、占用时间。"}],"abstract":[{"en":"Picture wind pushing leaves through a half-open window onto a desk.","cn":"想象风把落叶从半开的窗推进书桌。"},{"en":"Picture a vine crossing a fence gap and wrapping a trellis.","cn":"想象藤蔓越过篱笆缺口，缠住棚架。"},{"en":"Picture a ringing phone entering a quiet room.","cn":"想象铃声进入一间安静的屋子。"}]},"examples":[{"en":"The army invaded from the north and cut the railway in two days.","cn":"军队从北方入侵，两天内切断了铁路。"},{"en":"Reporters invaded the village after the story broke.","cn":"消息传开后，记者涌进了这个村子。"},{"en":"A doubt invaded her mind just before the answer was due.","cn":"就在答案到期之前，一个疑问占据了她的心。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因维德」听似「硬围的」——硬围进来的一群人 → 入侵、侵扰","word":"invade"},"root":"拉丁 invadere「走进去、攻击」= in-「进入」+ vadere「走、前进」；同根加 e- 得 evade；vadere 的更深来源不确定。","sensesIntro":{"en":"Eight senses send one verb of entering into a country, a square, a calendar, an orchard, a tissue, a market, a custom and finally a mind.","cn":"八个义项把同一个「进入」动词依次送入国家、广场、日程、果园、组织、市场、习俗，最后送入一颗心。"},"semanticMap":{"core":{"en":"CORE IMAGE: wind pushing leaves and dust through a half-open window onto a desk.","cn":"核心意象：风把落叶与尘土从半开的窗推进书桌。"},"chain":["GO IN","ARMED ENTRY","MASS ENTRY","UNWELCOME SPREAD","TAKE A MARKET","FILL THE MIND"],"branches":[{"senses":"S1 · S7","en":"BORDERS: a country and a body of rights are both territory that can be crossed.","cn":"边界：国家与一套权利都是可被越过的领土。"},{"senses":"S2 · S6","en":"NUMBERS AND SHARE: a crowd and a chain of shops both take ground by sheer volume.","cn":"数量与份额：人潮与连锁店都靠体量占地。"},{"senses":"S3","en":"PERSONAL SPACE: a calendar and a quiet room become territory when someone else fills them.","cn":"私人空间：日程与安静的房间在被人填满时就成了领土。"},{"senses":"S4 · S5","en":"LIVING SPREAD: weeds and tumours both cross a boundary and cannot easily be pushed back.","cn":"活的扩散：杂草与肿瘤都越过边界，且难以被推回。"},{"senses":"S8","en":"THE MIND: the last territory is the self, entered by a feeling.","cn":"心智：最后一块领土是自我，被情绪进入。"}]},"affixes":{"intro":{"en":"Invade is a Latin verb of going with a prefix of entry, and its own opposite is built from the same root.","cn":"invade 是一个带进入前缀的拉丁「走」动词，它的反义词也由同一词根构成。"},"latinIntro":{"en":"Latin vadere 'to go' gives evade and evasive with e-, and invadere 'to go into' gives invade and invasion.","cn":"拉丁 vadere「走」加 e- 给出 evade 与 evasive；invadere「走进去」给出 invade 与 invasion。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'into')","meaning":"into","meaningCN":"进入","example":"The prefix marks the direction of entry.","exampleCN":"这个前缀标出进入的方向。"},{"word":"vad-","structure":"vadere (Latin verb, 'to go')","meaning":"to go","meaningCN":"走","example":"The root is plain motion before it is hostility.","exampleCN":"这个词根先是朴素动作，后才有敌意。"},{"word":"invade","structure":"in- + vadere","meaning":"to enter by force","meaningCN":"入侵；侵扰","example":"The crowd invaded the platform.","exampleCN":"人群涌上了站台。"},{"word":"invasion","structure":"invade + -sion","meaning":"an entry in force or numbers","meaningCN":"入侵；涌入","example":"The invasion lasted a month.","exampleCN":"入侵持续一个月。"},{"word":"invader","structure":"invade + -er","meaning":"one who enters by force","meaningCN":"入侵者","example":"The invaders left the harbour.","exampleCN":"入侵者离开了港口。"},{"word":"invasive","structure":"invasion + -ive","meaning":"spreading where unwanted","meaningCN":"侵入性的","example":"The invasive fern covers the bank.","exampleCN":"这种入侵蕨类覆盖了河岸。"},{"word":"evade","structure":"e- + vadere","meaning":"to go out, avoid","meaningCN":"逃避","example":"They evaded the question twice.","exampleCN":"他们两次回避了这个问题。"},{"word":"evasion","structure":"evade + -sion","meaning":"an avoidance","meaningCN":"规避；逃避","example":"The evasion was legal but costly.","exampleCN":"这种规避合法但代价高。"},{"word":"evasive","structure":"evasion + -ive","meaning":"tending to avoid","meaningCN":"躲闪的","example":"He gave an evasive reply.","exampleCN":"他给了个躲闪的回答。"}],"latinEntries":[{"word":"vadere","structure":"vadere, vasi, vasum (verb, third conjugation)","meaning":"to go, advance","meaningCN":"走；前进"},{"word":"invadere","structure":"invadere, invasi, invasum (verb, third conjugation)","meaning":"to go into, attack","meaningCN":"走进去；攻击"},{"word":"invasio","structure":"invasio, invasionis (f., third declension)","meaning":"an entering, an attack","meaningCN":"进入；攻击"}]}},{"word":"invasion force","ipa_uk":"/ɪnˈveɪʒn fɔːs/","ipa_us":"/ɪnˈveɪʒn fɔːrs/","definition_zh":"入侵部队；侵略军；登陆编队","definition_en":"the whole body of troops, ships and aircraft assembled to carry out an invasion, or any major part of it","core_image":"河口外的锚地，运输船与护航舰排成长列，甲板上停着车辆与箱笼，岸线在雾里只露一道浅灰","scene":"河口外的锚地，运输船与护航舰排成长列，甲板上停着车辆。The invasion force assembled in the estuary and waited for calm weather.","sceneCN":"这里 invasion force 指「为实施入侵而集结的整支武装力量」（第 1 个义项：入侵部队整体）；句意为入侵部队在河口集结，等待天气转稳。场景物件：运输船、护航舰、甲板车辆、锚地。","pos":[{"tag":"n.","zh":"入侵部队；侵略军；登陆编队"}],"collocations":[{"phrase":"launch an invasion force","zh":"派出入侵部队"},{"phrase":"the invasion force landed","zh":"入侵部队登陆"},{"phrase":"assemble an invasion force","zh":"集结入侵部队"},{"phrase":"a large invasion force","zh":"庞大的入侵部队"},{"phrase":"the invasion force's supply line","zh":"入侵部队的补给线"}],"forms":[{"label":"复数","form":"invasion forces"},{"label":"相关名词（行为）","form":"invasion"},{"label":"相关动词","form":"invade"},{"label":"相关名词（人）","form":"invader"},{"label":"核心名词","form":"force"}],"derivatives":[{"word":"invasion","pos":"n.","zh":"入侵；涌入"},{"word":"invade","pos":"v.","zh":"入侵；侵扰"},{"word":"invader","pos":"n.","zh":"入侵者"},{"word":"force","pos":"n.","zh":"力量；部队"},{"word":"reinforce","pos":"v.","zh":"增援；加固"}],"senses":[{"no":"01","title":"The whole body assembled to invade","titleCN":"为入侵集结的整支部队","definition":"all the troops, ships and aircraft gathered to carry out one invasion","definitionCN":"为执行一次入侵而汇集的所有兵员、舰船与飞机","example":"The invasion force assembled in the estuary and waited for calm weather.","exampleCN":"入侵部队在河口集结，等待天气转稳。","why":"the phrase joins the name of the act to the name of the body, so it can hold an entire expedition in two words.","whyCN":"这个短语把行为之名与力量之名接在一起，两个词就装下整场远征。"},{"no":"02","title":"The landing troops","titleCN":"其中的登陆兵员","definition":"the soldiers or marines who are put ashore first, as distinct from the ships that carry them","definitionCN":"最先上岸的士兵或陆战队员，与运送他们的舰船相区别","example":"The invasion force came ashore in four waves before the tide turned.","exampleCN":"入侵部队在潮水转向之前分四批上岸。","why":"because a landing is the decisive moment, the phrase often narrows to the men on the beaches.","whyCN":"由于登陆是决定性时刻，这个短语常收窄到海滩上的人。"},{"no":"03","title":"The fleet that carries them","titleCN":"登陆舰艇编队","definition":"the ships and landing craft that move and supply the troops","definitionCN":"运送与补给兵员的舰船与登陆艇","example":"The invasion force lay offshore for two days under radio silence.","exampleCN":"入侵舰队在无线电静默下于近海停了两天。","why":"naval usage lets the same phrase name the floating half of the expedition, since without it no landing happens.","whyCN":"海军用法让同一短语指远征中漂浮的那一半，因为没有它就没有登陆。"},{"no":"04","title":"The air component","titleCN":"空降与空中支援部分","definition":"the aircraft and airborne units that support or precede the landing","definitionCN":"支援或先于登陆的飞机与空降部队","example":"The invasion force included night bombers and two airborne divisions.","exampleCN":"入侵编队包括夜间轰炸机与两个空降师。","why":"twentieth-century warfare made air power part of the body, so the phrase grew a third arm.","whyCN":"20 世纪的战争让空中力量成为这支队伍的一部分，短语由此长出第三条臂膀。"},{"no":"05","title":"The joint command organisation","titleCN":"联合特遣指挥编组","definition":"the headquarters and staff that control the whole operation","definitionCN":"控制整个行动的司令部与参谋机构","example":"The invasion force had its own signal company and weather officer.","exampleCN":"入侵部队有自己的通信连与气象军官。","why":"staff language treats the command as the force itself, because the body cannot move without it.","whyCN":"参谋语言把指挥机构当作部队本身，因为没有它这具躯体动不了。"},{"no":"06","title":"A named historical expedition","titleCN":"有专名的历史远征军","definition":"a particular invasion force remembered under a campaign name or a date","definitionCN":"以战役名或年代被记住的某支入侵部队","example":"The Norman invasion force carried horses, prefabricated forts and a duke.","exampleCN":"诺曼入侵部队带着马匹、预制堡垒和一位公爵。","why":"historians turn one assembly into a proper name, and the phrase becomes a chapter heading.","whyCN":"史家把一次集结变成专名，这个短语于是成了章节标题。"},{"no":"07","title":"A mass arrival, used loosely","titleCN":"比喻：大批涌入的人潮","definition":"any large group whose arrival feels like an occupation","definitionCN":"任何到来时像占领一样的大群人","example":"An invasion force of tourists took every table by one o'clock.","exampleCN":"到一点钟，一支由游客组成的入侵部队已占满每张桌子。","why":"journalists borrow the military phrase for comic effect, and the exaggeration is the point.","whyCN":"记者借用这个军事短语制造滑稽效果，夸张本身就是要点。"},{"no":"08","title":"A fictional or game army","titleCN":"虚构或推演中的入侵军团","definition":"an invading army in a novel, film, wargame or strategy game","definitionCN":"小说、电影、兵棋或策略游戏中的入侵军队","example":"The scenario gives each player one invasion force and one winter.","exampleCN":"这个推演给每位玩家一支入侵部队和一个冬天。","why":"games and fiction keep the phrase because it instantly supplies a side, a goal and a supply line.","whyCN":"游戏与虚构保留这个短语，因为它立刻提供一方、一个目标与一条补给线。"}],"etymology":{"intro":{"en":"Invasion force is an English phrase joining invasion, from Latin invasio, to force, from Old French force and Latin fortis 'strong'.","cn":"invasion force 是英语短语，把 invasion（来自拉丁 invasio）与 force（来自古法语 force、拉丁 fortis「强」）接在一起。"},"items":[{"era":"INVASION","en":"Invasion is Latin invasio 'a going into, an attack', the noun of invadere, built on in- 'into' and vadere 'to go'.","cn":"invasion 是拉丁 invasio「进入、攻击」，即 invadere 的名词，由 in-「进入」与 vadere「走」构成。"},{"era":"FORCE","en":"Force came through Old French force from Late Latin fortia, a noun of strength built on fortis 'strong'.","cn":"force 经古法语 force 来自晚期拉丁 fortia，这是由 fortis「强」构成的「力量」名词。"},{"era":"MILITARY PHRASE","en":"The phrase settled in the nineteenth and twentieth centuries as staff language for the whole body assembled to seize a coast or a country.","cn":"这个短语在 19 与 20 世纪固定为参谋用语，指为夺取海岸或国家而集结的整支部队。"},{"era":"WHOLE OR PART","en":"Because a landing needs ships, aircraft and troops, the phrase can name the whole or any major part, and context decides.","cn":"由于登陆需要舰船、飞机与兵员，这个短语可指全体，也可指任一主要部分，由语境决定。"},{"era":"LOOSE USE","en":"Journalists also use it for any large hostile-seeming arrival, from insects to tourists.","cn":"记者也用它指任何看似敌意的大批到来，从昆虫到游客。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the phrase has no single documented coinage, and its earliest military use is dated only approximately.","cn":"来源不确定（首见年代）：这个短语没有单一可考的最早造词，其最早军事用例只能约略定年。"}]},"similar":{"note":{"en":"Group one holds compounds built on force; group two holds other names for a body sent to fight abroad.","cn":"第一组是以 force 构成的复合词；第二组是派往海外作战之部队的其他名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"task force","ipa":"/ˈtɑːsk fɔːs/","tag":"unit for one job","definition":"A group assembled for a specific operation; it need not be an invasion and may be small.","definitionCN":"为特定行动组建的队伍；不一定是入侵，规模也可能很小。"},{"word":"air force","ipa":"/ˈeə fɔːs/","tag":"permanent service","definition":"A standing branch of a nation's military, not an expedition gathered for one landing.","definitionCN":"国家常设军种，不是为一次登陆而集结的远征。"},{"word":"invading force","ipa":"/ɪnˈveɪdɪŋ fɔːs/","tag":"the same body, verbal form","definition":"The present-participle variant describes the body while it acts; the noun phrase names it as a thing.","definitionCN":"现在分词变体描述正在行动的部队；名词短语则把它当作一个事物来命名。"},{"word":"force","ipa":"/fɔːs/","tag":"the head noun","definition":"On its own it means strength or an organised body; the compound narrows it to one purpose.","definitionCN":"单独使用时指力量或有组织的队伍；复合后收窄到单一目的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"expeditionary force","ipa":"/ˌekspəˈdɪʃənri fɔːs/","tag":"sent abroad","definition":"Troops sent to a distant theatre for a campaign, whether or not they invade.","definitionCN":"派往远方战区的部队，无论是否入侵。"},{"word":"armada","ipa":"/ɑːˈmɑːdə/","tag":"a great fleet","definition":"A large fleet, often used historically or rhetorically; it covers ships only.","definitionCN":"庞大的舰队，常用于历史或修辞语境；只涵盖舰船。"},{"word":"landing party","ipa":"/ˈlændɪŋ pɑːti/","tag":"a small group ashore","definition":"A small detachment put ashore for a limited task, much smaller than an invasion force.","definitionCN":"为有限任务上岸的小分队，比入侵部队小得多。"},{"word":"garrison","ipa":"/ˈɡærɪsn/","tag":"troops holding a place","definition":"Soldiers stationed to hold a place already taken, the opposite of a body sent to take one.","definitionCN":"驻扎守住已占之地的士兵，与派去攻取的部队正相反。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real compound, a real Latin root behind force and real campaign names.","cn":"正常联想：真实的复合结构、force 背后真实的拉丁词根与真实战役名。"},"normal":[{"en":"invasion + force: the act plus the body that performs it.","cn":"invasion + force：行为加上执行它的那具躯体。"},{"en":"force goes back to fortis 'strong', which also gives fort, fortify and effort.","cn":"force 上承 fortis「强」，还给出 fort、fortify、effort。"},{"en":"The phrase can name the troops, the ships, the aircraft or the command, and context decides.","cn":"这个短语可指兵员、舰船、飞机或指挥机构，由语境决定。"},{"en":"History supplies the example: the Norman invasion force of 1066.","cn":"历史提供例子：一〇六六年的诺曼入侵部队。"},{"en":"Modern loose use turns tourists into an invasion force, with the joke carried by the exaggeration.","cn":"现代宽松用法把游客变成入侵部队，笑点由夸张承担。"}],"abstract":[{"en":"Picture a queue of transports and escorts at anchor in an estuary.","cn":"想象河口锚地排成长列的运输船与护航舰。"},{"en":"Picture arrows on a map all ending at one beach.","cn":"想象地图上所有箭头都指向同一片海滩。"},{"en":"Picture a wave held back by a long concrete wall.","cn":"想象一道浪被长长的混凝土墙挡住。"}]},"examples":[{"en":"The invasion force needed calm water more than it needed more men.","cn":"这支入侵部队需要平静的水面，胜过需要更多人手。"},{"en":"The invasion force lost two supply ships before it reached the coast.","cn":"入侵部队在抵达海岸前损失了两艘补给船。"},{"en":"Planners gave the invasion force a single weather window.","cn":"计划人员只给了入侵部队一个天气窗口。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因维申福斯」听似「硬围身、复死」——硬围上来、拼命往前压的一整队人 → 入侵部队","word":"invasion force"},"root":"英语短语：invasion（拉丁 invasio，出自 in- + vadere）+ force（古法语 force，上承晚期拉丁 fortia、fortis「强」）。","sensesIntro":{"en":"Eight senses divide one expedition into its parts: the whole body, the landing troops, the fleet, the aircraft, the command, a named historical case, a joking crowd and a game army.","cn":"八个义项把同一支远征拆成几部分：全体、登陆兵员、舰队、航空部分、指挥机构、有专名的历史个案、戏谑的人潮与游戏中的军团。"},"semanticMap":{"core":{"en":"CORE IMAGE: transports and escorts in a long line at anchor, vehicles on deck, a grey coast in fog.","cn":"核心意象：运输船与护航舰在锚地排成长列，甲板上停着车辆，雾中只有一道灰色的海岸。"},"chain":["ASSEMBLE","ARMED BODY","LANDING TROOPS","SHIPS","AIR COMPONENT","JOINT COMMAND"],"branches":[{"senses":"S1 · S5","en":"WHOLE AND HEAD: the assembled expedition and its headquarters are named by the same phrase because neither moves without the other.","cn":"全体与首脑：整支远征与其司令部用同一短语命名，因为缺一皆不能动。"},{"senses":"S2 · S3","en":"MEN AND SHIPS: the troops on the beach and the fleet offshore are the two halves of one landing.","cn":"人与船：海滩上的兵员与近海的舰队，是一次登陆的两半。"},{"senses":"S4","en":"AIR: twentieth-century warfare added a third arm to the body.","cn":"空中：20 世纪的战争给这具躯体加上第三条臂膀。"},{"senses":"S6","en":"HISTORY: one assembly becomes a proper name and a chapter heading.","cn":"历史：一次集结变成专名与章节标题。"},{"senses":"S7 · S8","en":"BORROWED BODIES: tourists and game armies borrow the phrase, one for a joke and one for a scenario.","cn":"借用的躯体：游客与游戏军团都借用这个短语，一为玩笑，一为推演。"}]},"affixes":{"intro":{"en":"Invasion force is a two-word English phrase whose halves come from Latin and French, and each half has its own family.","cn":"invasion force 是一个两词英语短语，两半分别来自拉丁与法语，各自都有词族。"},"latinIntro":{"en":"Latin vadere 'to go' stands behind invasion, and Latin fortis 'strong' stands behind force through Late Latin fortia and Old French.","cn":"拉丁 vadere「走」是 invasion 的底；拉丁 fortis「强」经晚期拉丁 fortia 与古法语成为 force 的底。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'into')","meaning":"into","meaningCN":"进入","example":"The prefix marks entry in the first half.","exampleCN":"这个前缀标出前半部分的「进入」。"},{"word":"vad-","structure":"vadere (Latin verb, 'to go')","meaning":"to go","meaningCN":"走","example":"The root supplies motion in invasion.","exampleCN":"这个词根为 invasion 提供动作。"},{"word":"-sion","structure":"-sio (Latin noun suffix)","meaning":"act or result","meaningCN":"动作或结果","example":"The suffix makes invasion an event noun.","exampleCN":"这个后缀把 invasion 变成事件名词。"},{"word":"fort-","structure":"fortis (Latin adjective, 'strong')","meaning":"strong","meaningCN":"强的","example":"The root supplies strength in force and fortify.","exampleCN":"这个词根为 force 与 fortify 提供「强」。"},{"word":"invasion","structure":"in- + vadere + -sion","meaning":"an entry by force","meaningCN":"入侵","example":"The invasion opened at dawn.","exampleCN":"入侵在黎明开始。"},{"word":"force","structure":"fortia through Old French","meaning":"strength, an organised body","meaningCN":"力量；部队","example":"The force held the bridge.","exampleCN":"这支部队守住了桥。"},{"word":"invasion force","structure":"invasion + force","meaning":"the body assembled to invade","meaningCN":"入侵部队","example":"The invasion force waited offshore.","exampleCN":"入侵部队在近海等待。"},{"word":"task force","structure":"task + force","meaning":"a unit for one operation","meaningCN":"特遣部队","example":"A task force cleared the channel.","exampleCN":"一支特遣部队清理了水道。"},{"word":"reinforce","structure":"re- + in- + fortia","meaning":"to strengthen again","meaningCN":"增援；加固","example":"Two companies reinforced the landing.","exampleCN":"两个连增援了登陆。"},{"word":"effort","structure":"ex- + fortis","meaning":"a putting forth of strength","meaningCN":"努力","example":"The effort cost the fleet a day.","exampleCN":"这番努力让舰队多花了一天。"}],"latinEntries":[{"word":"vadere","structure":"vadere, vasi, vasum (verb, third conjugation)","meaning":"to go, advance","meaningCN":"走；前进"},{"word":"invadere","structure":"invadere, invasi, invasum (verb, third conjugation)","meaning":"to go into, attack","meaningCN":"走进去；攻击"},{"word":"invasio","structure":"invasio, invasionis (f., third declension)","meaning":"an entering, an attack","meaningCN":"进入；攻击"},{"word":"fortis","structure":"fortis, forte (adjective)","meaning":"strong, brave","meaningCN":"强的；勇敢的"},{"word":"fortia","structure":"fortia, fortium (n., third declension)","meaning":"strength, force","meaningCN":"力量；武力"}]}}]);
